INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Gooch & Housego PLC', 'Founded in 1948 and headquartered in Ilminster, Somerset, G&H is a publicly listed photonics technology company that designs and manufactures a uniquely broad range of optical and photonic products including acousto-optics, electro-optics, fibre optics, DFB laser modules, precision optics, and RF driver electronics. They serve OEM customers in life sciences, industrial, and aerospace & defence markets from multiple UK sites including Ilminster, Torquay, Ashford, St. Asaph, and Plymouth.', '{"company_type": "Photonics", "website_url": "https://gandh.com", "location": "Ilminster, Somerset, UK", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Acousto-Optic Devices", "Electro-Optic Modulators", "Fibre Optic Components", "Precision Optics", "Crystal Growth", "Thin Film Coatings", "Optical Assemblies", "RF Driver Electronics"], "industries": ["Aerospace", "Defense", "Life Sciences", "Industrial", "Space"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1948, "materials": ["Optical Glass", "Fused Silica", "Lithium Niobate", "Tellurium Dioxide", "Optical Fibre"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Teledyne e2v', 'Headquartered in Chelmsford, Essex, Teledyne e2v is one of the UK''s leading designers and manufacturers of specialised image sensors, CCD and CMOS detectors, RF power systems, and high-reliability semiconductors. With over 250 space mission deliveries, the company''s sensors have flown on NASA Hubble, ESA Gaia, and ESA JUICE, and are manufactured at its 24-acre Chelmsford facility. It serves space, healthcare, defence, industrial, and scientific markets as part of the Teledyne Technologies group.', '{"company_type": "Sensor Manufacturing", "website_url": "https://www.teledyne-e2v.com", "location": "Chelmsford, Essex, UK", "certifications": ["ISO 9001", "AS9100D"], "capabilities": ["CCD Image Sensor Design", "CMOS Image Sensor Design", "Hyperspectral Detectors", "RF Power Systems", "Focal Plane Arrays", "Space-Qualified Packaging", "High-Reliability Semiconductors"], "industries": ["Space", "Defense", "Medical", "Scientific Research", "Industrial"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1947, "materials": ["Silicon", "Gallium Arsenide", "Indium Phosphide"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Optical Surfaces Ltd', 'Founded in 1962 and based in Kenley, Surrey, Optical Surfaces Ltd is one of Europe''s leading manufacturers of high-precision optical components and systems, operating from workshops deep underground in solid chalk tunnels where temperature and vibration are exceptionally stable. The company specialises in large optics, beam expanders, collimators, and custom assemblies for space, astronomy, high-energy physics, and defence, with customers including NASA, ESA, CERN, and BAE Systems.', '{"company_type": "Precision Optics", "website_url": "https://optisurf.com", "location": "Kenley, Surrey, UK", "certifications": ["ISO 9001"], "capabilities": ["Large Optic Fabrication", "Beam Expanders", "Collimators", "Optical Assemblies", "Aspheric Surfaces", "Interferometric Testing", "Flat and Spherical Optics"], "industries": ["Space", "Astronomy", "Defense", "High-Energy Physics", "Scientific Research"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1962, "materials": ["Fused Silica", "Zerodur", "BK7", "Optical Glass", "Pyrex"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'UQG Optics Ltd', 'Founded in 1955 as The Universal Quartz Grinding Company and based in Cambridge, UQG Optics is a third-generation family-owned precision optical components manufacturer and supplier. The company produces and sources custom optical windows, lenses, prisms, mirrors, and filters in materials spanning UV to far-infrared, supplying direct to customers in over 50 countries. UQG serves research, defence, aerospace, and medical markets with ISO 9001-certified quality.', '{"company_type": "Precision Optics", "website_url": "https://www.uqgoptics.com", "location": "Cambridge, Cambridgeshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Optical Windows", "Custom Lenses", "Prisms", "Optical Filters", "Optical Mirrors", "Technical Glass Supply", "Custom Fabrication"], "industries": ["Research", "Defense", "Aerospace", "Medical", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1955, "materials": ["Optical Glass", "Fused Silica", "Germanium", "Silicon", "Calcium Fluoride", "Zinc Selenide", "Sapphire"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Thermoteknix Systems Ltd', 'Founded in 1982 and headquartered in Cambridge, Thermoteknix is a UK innovator in infrared thermal imaging, night vision, and augmented reality vision systems, with all products designed and manufactured at its Cambridge facility. The company exports to over 70 countries and has received the King''s Award for Enterprise for Innovation. It serves defence, security, industrial process, and aerospace customers, and operates additional offices in the USA, Singapore, and India.', '{"company_type": "Sensor Manufacturing", "website_url": "https://www.thermoteknix.com", "location": "Cambridge, Cambridgeshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Infrared Thermal Imaging Cameras", "Night Vision Systems", "Augmented Reality Vision", "Thermal Cores", "Fused Imaging Systems", "Electro-Optical System Integration"], "industries": ["Defense", "Security", "Aerospace", "Industrial", "Fire Safety"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1982, "materials": ["Germanium", "Vanadium Oxide", "Amorphous Silicon"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Edinburgh Instruments Ltd', 'Founded in 1971 in Livingston, Scotland, Edinburgh Instruments is one of the world''s largest manufacturers of molecular spectroscopy instrumentation, including fluorescence, Raman, transient absorption, FTIR, and photoluminescence spectrometers, as well as laser sources and gas detection systems. Part of the Techcomp Europe group, the company employs approximately 200 staff at its Livingston campus and serves academic research, pharmaceutical, semiconductor, and industrial markets globally.', '{"company_type": "Spectroscopy / Optical Measurement Equipment", "website_url": "https://www.edinst.com", "location": "Livingston, West Lothian, UK", "certifications": ["ISO 9001"], "capabilities": ["Fluorescence Spectrometers", "Raman Spectrometers", "Transient Absorption Spectroscopy", "FTIR Accessories", "Gas Detection Instruments", "Pulsed Laser Sources", "Photoluminescence Systems"], "industries": ["Pharmaceutical", "Academic Research", "Semiconductor", "Industrial", "Environmental"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1971, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Kratos Analytical Ltd', 'Established in 1956 and headquartered at Trafford Park, Manchester, Kratos Analytical is a wholly owned subsidiary of Shimadzu Corporation (Japan) and a world leader in X-ray photoelectron spectroscopy (XPS) surface analysis instruments, with a history spanning 50+ years of commercial XPS manufacturing. The company employs over 200 staff in Manchester and also develops MALDI time-of-flight mass spectrometry instruments, serving materials science, semiconductor, pharmaceutical, and advanced manufacturing sectors.', '{"company_type": "Spectroscopy / Optical Measurement Equipment", "website_url": "https://www.kratos.com", "location": "Manchester, Greater Manchester, UK", "certifications": ["ISO 9001"], "capabilities": ["X-ray Photoelectron Spectroscopy (XPS)", "MALDI-ToF Mass Spectrometry", "Surface Analysis Instruments", "Synchrotron Beamline Systems", "Custom Spectrometer Design"], "industries": ["Materials Science", "Semiconductor", "Pharmaceutical", "Advanced Manufacturing", "Academic Research"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1956, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Helia Photonics Ltd', 'Based at Rosebank Technology Park in Livingston, West Lothian, Helia Photonics is a specialist thin film optical coating company focused on III-V and silicon photonics back-end-of-line processes, with over 15 years of trading. The company operates 14 on-site deposition systems including plasma-assisted electron beam evaporation, ion beam sputtering, and magnetron sputtering, serving customers in telecommunications, automotive, satellite, and scientific instrument sectors. Helia produces ultra-low anti-reflection coatings, high-reflection coatings, and protective facet coatings for laser components.', '{"company_type": "Precision Optics", "website_url": "https://www.helia-photonics.com", "location": "Livingston, West Lothian, UK", "certifications": ["ISO 9001"], "capabilities": ["Anti-Reflection Coatings", "High-Reflection Coatings", "Laser Facet Coatings", "Fibre End Coatings", "Semiconductor Device Coatings", "Ion Beam Sputtering", "Magnetron Sputtering", "Plasma-Assisted Electron Beam Evaporation"], "industries": ["Telecommunications", "Automotive", "Space", "Scientific Instruments", "Consumer Electronics"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2006, "materials": ["Optical Glass", "Silicon", "III-V Semiconductors", "Optical Fibre"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Vortex Optical Coatings Ltd', 'Founded in 2008 and located in Hinckley, Leicestershire, Vortex Optical Coatings designs and manufactures visible and infrared optical filters, dichroic filters, and IR linear variable filters using 10 fully automated high-energy sputter deposition coating machines. The ISO 9001:2015-accredited company offers a fast-turnaround anti-reflection coating service and supplies filters for machine vision, spectroscopy, fluorescence imaging, and scientific instrumentation markets.', '{"company_type": "Precision Optics", "website_url": "https://vortexopticalcoatings.co.uk", "location": "Hinckley, Leicestershire, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Bandpass Filters", "Dichroic Filters", "Infrared Filters", "Linear Variable Filters", "Anti-Reflection Coatings", "Hard-Sputtered Thin Film Coatings"], "industries": ["Machine Vision", "Spectroscopy", "Life Sciences", "Scientific Instruments", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2008, "materials": ["Optical Glass", "Fused Silica"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Thin Metal Films Ltd', 'Based in Basingstoke, Hampshire, Thin Metal Films Ltd is a precision thin film optical coating contractor with over 30 years of experience applying vacuum optical coating technologies for advanced optical, laser, and electro-optic systems. The company applies oxide coatings including mirrors, anti-reflection coatings, neutral-density filters, and beamsplitters, as well as metallic mirror coatings, covering wavelengths from UV through to infrared. They serve defense, security, fibre optics, solar, and touchscreen sectors.', '{"company_type": "Precision Optics", "website_url": "https://www.tmf.uk.com", "location": "Basingstoke, Hampshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Anti-Reflection Coatings", "Mirror Coatings", "Beamsplitter Coatings", "Neutral Density Filters", "Fibre Optic Coatings", "UV-IR Range Coatings", "Contract Optical Coating"], "industries": ["Defense", "Security", "Fibre Optics", "Solar Energy", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Optical Glass", "Fused Silica", "Optical Fibre"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Kingsview Optical Ltd', 'Founded in 1993 and based in Rye, East Sussex, Kingsview Optical is a precision optics manufacturer offering a complete in-house service from optical design through to manufacture, vacuum coating, and assembly. The company produces lenses from 0.8 mm micro-optics to 200 mm diameter, and prisms from 0.5 mm, serving aerospace, defence, medical, and research sectors. It operates multiple CNC lens polishing machines and four optical vacuum coating chambers.', '{"company_type": "Precision Optics", "website_url": "https://www.kingsviewoptical.com", "location": "Rye, East Sussex, UK", "certifications": ["ISO 9001"], "capabilities": ["CNC Lens Manufacture", "Prism Fabrication", "Optical Vacuum Coating", "Opto-Mechanical Assemblies", "Optical Design", "Micro-Optics"], "industries": ["Aerospace", "Defense", "Medical", "Research"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1993, "materials": ["Optical Glass", "Fused Silica", "BK7", "Sapphire"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Specac Ltd', 'Originally founded in 1971 as Spectroscopic Accessories Ltd and based in Orpington, Kent, Specac is a global market-leading manufacturer of spectroscopy accessories, infrared sample preparation cells, ATR accessories, optical components, and hydraulic presses for sample preparation. With over 400 employees across three continents and 90% of sales exported, Specac holds the Queen''s Award for International Trade and is ISO 14001 certified. The company serves pharmaceutical, chemical, polymer, and research laboratory markets worldwide.', '{"company_type": "Spectroscopy / Optical Measurement Equipment", "website_url": "https://specac.com", "location": "Orpington, Kent, UK", "certifications": ["ISO 9001", "ISO 14001:2015"], "capabilities": ["ATR Accessories", "FTIR Sample Cells", "Infrared Windows & Optics", "Hydraulic Presses", "Process Cells", "Optical Components for Spectroscopy"], "industries": ["Pharmaceutical", "Chemical", "Polymer", "Academic Research", "Food & Beverage", "Industrial"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1971, "materials": ["Calcium Fluoride", "Zinc Selenide", "Potassium Bromide", "Barium Fluoride", "Diamond"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Andor Technology Ltd (Oxford Instruments)', 'Founded in 1989 as a spin-out from Queen''s University Belfast, Andor Technology is a globally recognised manufacturer of scientific cameras, spectrographs, and microscopy systems, acquired by Oxford Instruments in 2013. Operating from a purpose-built 50,000 sq ft facility in Belfast, Northern Ireland, Andor employs over 400 staff and serves 10,000+ customers in 55 countries. Products include EMCCD, sCMOS, and intensified cameras used in life sciences, astronomy, quantum research, and materials characterisation.', '{"company_type": "Photonics", "website_url": "https://andor.oxinst.com", "location": "Belfast, Northern Ireland, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["EMCCD Cameras", "sCMOS Cameras", "Intensified Cameras", "Spectrographs", "Fluorescence Microscopy Systems", "Photon Counting", "Super-Resolution Microscopy"], "industries": ["Life Sciences", "Astronomy", "Quantum Research", "Materials Science", "Academic Research"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1989, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Photek Ltd', 'Based in St Leonards-on-Sea, East Sussex, Photek is the world''s leading specialist manufacturer of ultra-fast vacuum-based photomultiplier tubes (PMTs), image intensifiers, UV detectors, and neutron detection camera systems. The company''s PMTs are the fastest commercially available, with pulse rise times to 50 ps, making them critical for LIDAR, nuclear physics, time-correlated photon counting, and streak camera applications. Photek designs and manufactures all products at its Sussex facility for defence, scientific, and medical markets.', '{"company_type": "Photonics", "website_url": "https://www.photek.com", "location": "St Leonards-on-Sea, East Sussex, UK", "certifications": ["ISO 9001"], "capabilities": ["Photomultiplier Tubes", "Image Intensifiers", "UV Solar Blind Detectors", "Neutron Imaging Systems", "Streak Camera Systems", "Photon Counting Cameras", "Microchannel Plate Detectors"], "industries": ["Defense", "Nuclear", "Medical", "Scientific Research", "LIDAR"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Raptor Photonics Ltd', 'Established in 2006 and based in Larne, County Antrim, Northern Ireland, Raptor Photonics is a manufacturer of high-performance ultra-low-light digital cameras using CCD, EMCCD, and SWIR (InGaAs) sensor technologies, covering UV, visible, and shortwave infrared wavebands. The company operates a 6,000 sq ft facility with cleanroom and vacuum capabilities, supplying rugged camera solutions to special forces, national defence forces, law enforcement, scientific research, and space surveillance customers globally.', '{"company_type": "Photonics", "website_url": "https://www.raptorphotonics.com", "location": "Larne, County Antrim, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["EMCCD Cameras", "SWIR InGaAs Cameras", "Scientific CMOS Cameras", "Night Vision Cameras", "Camera Core Engines", "UV-SWIR Imaging"], "industries": ["Defense", "Security", "Space", "Scientific Research", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2006, "materials": ["Silicon", "Indium Gallium Arsenide"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'WIKA Optical Sensing Ltd (formerly Oxsensis Ltd)', 'Originally founded in 2003 as a spin-out from the STFC Rutherford Appleton Laboratory and acquired by WIKA Group in 2023, this Harwell Campus-based company specialises in Fabry-Perot-based optical sensors for measuring pressure, temperature, and vibration in extreme environments exceeding 1,000°C. The company has two decades of experience applying optical sensing to power generation, aerospace turbomachinery, and petrochemical industries, and holds both ISO 9001 and AS9100 Rev D accreditation.', '{"company_type": "Sensor Manufacturing", "website_url": "https://www.wika.com/en-gb/lp_oxsensis.WIKA", "location": "Didcot, Oxfordshire, UK", "certifications": ["ISO 9001", "AS9100 Rev D"], "capabilities": ["Optical Pressure Sensors", "Optical Temperature Sensors", "Fabry-Perot Interferometry", "Fibre Bragg Grating Sensing", "Distributed Acoustic Sensing", "Harsh Environment Instrumentation"], "industries": ["Aerospace", "Power Generation", "Oil & Gas", "Defense", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2003, "materials": ["Fused Silica", "Optical Fibre", "Sapphire"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Instro Precision Ltd', 'Founded in 1964 and based in Sandwich, Kent, Instro Precision is a wholly owned subsidiary of Elbit Systems UK serving as the group''s Centre of Excellence for electro-optics. The company designs, manufactures, and integrates electro-optical and target acquisition systems for military customers in over 50 countries, operating from a 2,200 m² facility. Product lines include laser rangefinders, sight systems, LIDAR-based target acquisition, and night-vision support equipment, with ISO 9001 and ISO 14001 certification.', '{"company_type": "Sensor Manufacturing", "website_url": "https://instro.com", "location": "Sandwich, Kent, UK", "certifications": ["ISO 9001:2015", "ISO 14001:2015"], "capabilities": ["Electro-Optical System Integration", "Laser Rangefinders", "Target Acquisition Systems", "Night Vision Support Equipment", "LIDAR Systems", "Precision Engineering"], "industries": ["Defense", "Security", "Aerospace"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1964, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'G&H | Phoenix (formerly Phoenix Optical Technologies Ltd)', 'Founded in 1991 and based in St. Asaph, North Wales — at the heart of the UK''s largest optical manufacturing cluster — Phoenix Optical Technologies was acquired by Gooch & Housego in 2024 and now operates as G&H | Phoenix. The company offers a full in-house service from raw glass through to finished polished and coated optical parts, prisms, domes, and assemblies, with specialisms including Single Point Diamond Turning (SPDT) and specialist machining for aerospace and defence customers.', '{"company_type": "Precision Optics", "website_url": "https://gandh.com/phoenix", "location": "St. Asaph, Denbighshire, UK", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Single Point Diamond Turning", "Prism Manufacture", "Dome Fabrication", "Optical Polishing", "Optical Coatings", "Opto-Mechanical Assemblies", "Specialist Glass Machining"], "industries": ["Aerospace", "Defense", "Space", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1991, "materials": ["Optical Glass", "Germanium", "Silicon", "Zinc Selenide", "Fused Silica", "Sapphire"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
