INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Photonic Solutions Ltd', 'Incorporated in 1999 and based at Heriot-Watt University Research Park in Edinburgh, Photonic Solutions is an independent UK supplier and distributor of optoelectronic products, representing over 40 premier global manufacturers exclusively for the UK and Ireland market. The company covers lasers, imaging cameras, modular spectroscopy instrumentation, detectors, microscopy systems, and optical components, and is regarded as Europe''s leading independent distributor for the photonics sector. It serves research institutes, universities, and industrial photonics companies.', '{"company_type": "Photonics", "website_url": "https://photonicsolutions.co.uk", "location": "Edinburgh, Midlothian, UK", "certifications": ["ISO 9001"], "capabilities": ["Laser Systems Distribution", "Spectroscopy Instruments", "Scientific Cameras", "Optical Components", "Detectors", "Microscopy Systems", "Technical Sales & Support"], "industries": ["Academic Research", "Life Sciences", "Industrial", "Defense", "Semiconductor"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1999, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Glass Perfection Ltd', 'A Cambridgeshire-based precision optical components manufacturer with over 20 years of experience, Glass Perfection specialises in custom optical windows, filters, lenses, prisms, and mirrors for research, military, and specialist industrial applications. The company produces components from high-quality materials including BK7 optical glass and fused silica to exact customer specifications, with rigorous in-house quality control and metrology. It serves defence, security, scientific research, and specialist engineering markets.', '{"company_type": "Precision Optics", "website_url": "https://www.glassperfection.co.uk", "location": "Cambridgeshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Custom Optical Windows", "Prism Fabrication", "Mirror Manufacture", "Custom Lenses", "Optical Filters", "Precision Metrology"], "industries": ["Defense", "Research", "Industrial", "Security"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["BK7 Optical Glass", "Fused Silica", "N-BK7"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Global Optics (UK) Ltd', 'Established in 1995 and based in Poole, Dorset, Global Optics (UK) Ltd manufactures and supplies custom precision optical components including lenses, windows, prisms, filters, and coated mirrors for ultraviolet through infrared spectral ranges. The company offers in-house fabrication services including dicing, lapping, polishing, edge grinding, and protective coatings, serving scientific, defence, and industrial optical system integrators with components in a wide range of substrate materials.', '{"company_type": "Precision Optics", "website_url": "https://www.globalopticsuk.com", "location": "Poole, Dorset, UK", "certifications": ["ISO 9001"], "capabilities": ["Optical Windows", "Custom Lenses", "Prisms", "Optical Filters", "Coated Mirrors", "Dicing & Slicing", "Lapping & Polishing", "Edge Grinding"], "industries": ["Defense", "Scientific Research", "Industrial", "Medical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1995, "materials": ["Optical Glass", "Germanium", "Silicon", "Calcium Fluoride", "Fused Silica", "Zinc Selenide"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cairn Research Ltd', 'Founded in 1985 and headquartered in Faversham, Kent, Cairn Research is an independent, employee-owned precision optical instrument manufacturer specialising in fluorescence microscopy and electrophysiology systems for biological research. The company designs, manufactures, and supports modular fluorescence illumination, multi-channel imaging, and optogenetics systems used in laboratories worldwide. Cairn Research established a spinout, Cairn Imaging Solutions near Cambridge, focused on wider imaging solutions for life science customers.', '{"company_type": "Precision Optics", "website_url": "https://cairn-research.co.uk", "location": "Faversham, Kent, UK", "certifications": ["ISO 9001"], "capabilities": ["Fluorescence Illumination Systems", "Multi-Channel Imaging", "Optogenetics Systems", "Custom Microscopy", "Electrophysiology Integration", "Optical Filter Supply"], "industries": ["Life Sciences", "Academic Research", "Pharmaceutical", "Medical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1985, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Renishaw plc', 'Founded in 1973 and headquartered in Wotton-under-Edge, Gloucestershire, Renishaw is a FTSE-250-listed engineering and scientific technology company that designs and manufactures precision measurement instruments including laser interferometers, optical encoders, Raman spectroscopy systems, and co-ordinate measuring machine (CMM) probes. The company serves machine tool, metrology, additive manufacturing, healthcare, and semiconductor manufacturing markets globally with over 5,000 employees across multiple UK sites in Gloucestershire and Wiltshire.', '{"company_type": "Sensor Manufacturing", "website_url": "https://www.renishaw.com", "location": "Wotton-under-Edge, Gloucestershire, UK", "certifications": ["ISO 9001", "ISO 13485"], "capabilities": ["Laser Interferometers", "Optical Encoders", "Raman Spectroscopy Systems", "CMM Probes", "Inertial Measurement", "Additive Manufacturing Systems", "Gauging Systems"], "industries": ["Aerospace", "Defense", "Semiconductor", "Medical", "Automotive", "Scientific Research"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1973, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Laser Components (UK) Ltd', 'Founded in 1993 as the UK subsidiary of the German LASER COMPONENTS Group, and based in Chelmsford, Essex, Laser Components (UK) is a specialist distributor and partial manufacturer of optoelectronic components including photodiodes, avalanche photodiodes, laser diodes, fibre optic components, optical sensors, and detector modules. The company serves defence, aerospace, scientific, and industrial markets with ISO 9001-certified products drawn from the group''s seven global locations employing over 260 people in total.', '{"company_type": "Photonics", "website_url": "https://www.lasercomponents.com/uk/", "location": "Chelmsford, Essex, UK", "certifications": ["ISO 9001"], "capabilities": ["Photodiode Supply", "Avalanche Photodiodes", "Laser Diode Modules", "Fibre Optic Components", "Optical Detector Modules", "Custom Optoelectronic Components"], "industries": ["Defense", "Aerospace", "Scientific Research", "Industrial", "Medical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1993, "materials": ["Silicon", "Indium Gallium Arsenide", "Germanium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Diamond Coatings Ltd', 'Established in 2002 and operating from premises in the Midlands, Diamond Coatings Ltd is an industry-leading manufacturer of Indium Tin Oxide (ITO) and specialist optical coatings, operating state-of-the-art magnetron sputtering plants in the UK and USA with integrated cleanroom facilities. The company produces ITO glass, anti-reflection coatings on glass and plastic, RFI shielding filters, and beamsplitter coatings, serving touchscreen, display, photonics, defence, and scientific markets. It won ''Best ITO & Optical Coatings Company 2019'' at the Business Innovation Awards.', '{"company_type": "Precision Optics", "website_url": "https://diamondcoatings.co.uk", "location": "Midlands, UK", "certifications": ["ISO 9001"], "capabilities": ["ITO Coatings", "Anti-Reflection Coatings", "RFI Shielding Filters", "Beamsplitter Coatings", "Transparent Conductive Coatings", "Magnetron Sputtering"], "industries": ["Touchscreens", "Defense", "Photonics", "Scientific Instruments", "Display Technology"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2002, "materials": ["Optical Glass", "Plastics", "Indium Tin Oxide"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Armstrong Optical Ltd', 'Incorporated in 1997 and based in Northampton, Armstrong Optical is a specialist supplier of optical metrology instruments and systems to research, development, and production environments across the UK. The company represents leading manufacturers including Trioptics, SIOS, and Precitec Optronik, and supplies interferometers, autocollimators, chromatic confocal sensors, and instruments for measuring MTF, centration, focal length, and wavefront error. It serves aerospace, defence, optics manufacturing, and research sectors.', '{"company_type": "Spectroscopy / Optical Measurement Equipment", "website_url": "https://armstrongoptical.co.uk", "location": "Northampton, Northamptonshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Laser Interferometry", "Autocollimators", "Chromatic Confocal Sensors", "MTF Measurement", "Optical Centration Measurement", "Focal Length Measurement", "Wavefront Analysis"], "industries": ["Aerospace", "Defense", "Optics Manufacturing", "Scientific Research", "Semiconductor"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1997, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Photon Lines Ltd', 'Founded in 2003 and based in Banbury, Oxfordshire, Photon Lines Ltd is a specialist photonics distributor serving the UK and Ireland, representing leading manufacturers across physical sciences and life sciences market segments. The company''s portfolio covers intensified high-speed cameras, scientific imaging systems, laser diagnostics, and photonics components including sources used in ballistics, laser-induced fluorescence, and combustion research. Photon Lines is part of the wider international Photon Lines Group.', '{"company_type": "Photonics", "website_url": "https://photonlines.co.uk", "location": "Banbury, Oxfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Intensified Camera Systems", "High-Speed Imaging", "Scientific Cameras", "Laser Diagnostics", "Photonics Components Distribution", "Technical Application Support"], "industries": ["Defense", "Academic Research", "Life Sciences", "Industrial", "Ballistics"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2003, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


