INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Star Hydraulics Ltd', 'Star Hydraulics Ltd is a Tewkesbury, Gloucestershire-based manufacturer of electro-hydraulic servo valves, founded in 1983. They are internationally recognised for their proprietary sapphire nozzle technology used in pilot-operated servo valves, direct-drive proportional valves, servo actuators, integrated manifolds, and drive electronics. They serve aerospace, industrial testing, steel, plastics, and simulation sectors globally.', '{"company_type": "Proportional / Servo Valve Manufacturer", "website_url": "https://www.star-hydraulics.co.uk/", "location": "Tewkesbury, Gloucestershire, UK", "certifications": ["ISO 9001"], "capabilities": ["Servo Valve Manufacturing", "Proportional Valve Design", "Valve Repair & Overhaul", "Drive Electronics", "Manifold Block Manufacturing"], "industries": ["Aerospace", "Steel", "Plastics Processing", "Industrial Testing", "Simulation"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1983, "materials": ["Steel", "Stainless Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Domin Ltd', 'Domin (formerly Domin Fluid Power) is a Bristol-based manufacturer of advanced hydraulic servo and proportional valves, founded in 2012. The company uses metal additive manufacturing via Renishaw RenAM systems to produce lighter, higher-performance valves from its Pucklechurch Technology Centre. Their products target automotive testing, aerospace, industrial robotics, and renewable energy, with a stated mission to reduce hydraulic system energy waste by up to 90%.', '{"company_type": "Proportional / Servo Valve Manufacturer", "website_url": "https://domin.com/", "location": "Pucklechurch, Bristol, UK", "certifications": ["ISO 9001"], "capabilities": ["Additive Manufactured Valve Production", "Servo Valve Design", "Proportional Valve Manufacturing", "Motion Control Systems"], "industries": ["Aerospace", "Automotive", "Robotics", "Industrial Manufacturing", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 2012, "materials": ["Steel", "Stainless Steel", "Additive Manufactured Alloys"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Rotary Power Ltd', 'Rotary Power is a Newcastle-upon-Tyne manufacturer of hydraulic radial piston motors and pumps, part of the British Engines Group. The company has designed and manufactured hydraulic motors for over 40 years at its purpose-built Simonside facility in Newcastle, exporting over 80% of output globally. They serve construction, oil and gas, marine, and industrial sectors, and supply major OEMs worldwide.', '{"company_type": "Hydraulic Pump and Motor Manufacturer", "website_url": "https://rotarypower.com/", "location": "Newcastle upon Tyne, Tyne and Wear, UK", "certifications": ["ISO 9001"], "capabilities": ["Radial Piston Motor Manufacturing", "Hydraulic Pump Design & Manufacture", "Custom Motor Development", "OEM Supply"], "industries": ["Construction", "Oil & Gas", "Marine", "Industrial Machinery", "Forestry"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Steel", "Cast Iron", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Hydreco Hydraulics Ltd', 'Hydreco Hydraulics Ltd is headquartered in Poole, Dorset, and is the UK base of the Hydreco Group, with over 100 years of heritage in hydraulic technology through predecessor companies including Hamworthy Hydraulics and David Brown Hydraulics. They design, manufacture, and distribute helical gear pumps, spur gear pumps, and hydraulic motors for the agricultural, construction, transport, and marine sectors. Since 2019 they have been part of the Duplomatic MS / Daikin Industries group.', '{"company_type": "Hydraulic Pump and Motor Manufacturer", "website_url": "https://hydreco.com/", "location": "Poole, Dorset, UK", "certifications": ["ISO 9001"], "capabilities": ["Gear Pump Manufacturing", "Hydraulic Motor Manufacturing", "Mobile Hydraulic Component Supply", "Agricultural Hydraulics"], "industries": ["Agriculture", "Construction", "Transport", "Marine", "Mining"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Cast Iron", "Aluminium", "Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Hydraproducts Ltd', 'Hydraproducts is a UK hydraulic power pack manufacturer based in Witham St Hughs, Lincolnshire, specialising in power packs up to 90 kW for OEM applications. Their design and manufacturing capabilities include CAD/SolidWorks development, prototype testing, and electro-hydraulic assembly, with a growing distributor network spanning Germany, Australia, Finland, and beyond. They primarily serve industrial OEMs in sectors such as waste, tippers, dock levellers, and scissor lifts.', '{"company_type": "Hydraulic Power Pack Manufacturer", "website_url": "https://hydraproducts.co.uk/", "location": "Witham St Hughs, Lincolnshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Hydraulic Power Pack Design", "Power Pack Assembly & Test", "Electro-Hydraulic Integration", "OEM Power Pack Supply"], "industries": ["Waste Management", "Transport", "Industrial Machinery", "Construction"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Zeus Hydratech Limited', 'Zeus Hydratech Limited is a Bristol-based hydraulic power unit manufacturer and system builder, accredited to ISO 9001 and a member of the British Fluid Power Distributors Association. They hold a large inventory of hydraulic pumps, valves, and power packs and are UK distributors for Daikin, Continental Hydraulics, Oilgear, and Duplomatic. They build standard power packs from stock in as little as three days and design bespoke units for industrial, marine, aerospace, and motorsport applications.', '{"company_type": "Hydraulic Power Pack Manufacturer", "website_url": "https://www.zeushydratech.com/", "location": "Bristol, Somerset, UK", "certifications": ["ISO 9001"], "capabilities": ["Hydraulic Power Pack Design & Build", "Bespoke HPU Manufacture", "Valve & Pump Supply", "System Integration"], "industries": ["Industrial", "Marine", "Aerospace", "Motorsport"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Steel", "Aluminium", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quality Hydraulic Power Ltd (QHP)', 'QHP (Quality Hydraulic Power Limited), based in Chester, is one of the world''s leading manufacturers of bespoke bladder and piston hydraulic accumulators, founded in 1987 and now part of the HYDAC Group. Their products are used globally in offshore, subsea, petrochemical, mining, mobile, and defence applications, with stainless steel fabricated bladder accumulators rated to 690 bar and subsea-qualified designs for depths to 3,000 metres. They are assessed to IEC 61508 for functional safety applications.', '{"company_type": "Accumulator Manufacturer", "website_url": "https://qhp.co.uk/", "location": "Chester, Cheshire, UK", "certifications": ["ISO 9001", "IEC 61508", "ATEX"], "capabilities": ["Bladder Accumulator Manufacturing", "Piston Accumulator Manufacturing", "Subsea Accumulator Design", "Custom Safety Block Assembly"], "industries": ["Oil & Gas", "Offshore & Subsea", "Defence", "Mining", "Petrochemical"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1987, "materials": ["Stainless Steel", "Carbon Steel", "Duplex Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
