INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'IMI Norgren Ltd', 'IMI Norgren, headquartered at Wall Island, Lichfield, Staffordshire, is a major manufacturer of pneumatic and electro-pneumatic motion control products and is part of IMI plc. Their product range spans linear actuators, air preparation units, valve islands, proportional pressure valves, pressure switches, and pneumatic fittings under the Norgren, Buschjost, Herion, and Watson Smith brands. They serve automation, food and beverage, life sciences, rail, and energy sectors globally.', '{"company_type": "Pneumatic Components Manufacturer", "website_url": "https://www.norgren.com/en", "location": "Lichfield, Staffordshire, UK", "certifications": ["ISO 9001", "ATEX", "CE"], "capabilities": ["Pneumatic Actuator Manufacture", "Air Preparation Equipment", "Proportional Valve Production", "Valve Island Assembly", "Pneumatic System Design"], "industries": ["Automation", "Food & Beverage", "Life Sciences", "Rail", "Energy"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1956, "materials": ["Aluminium", "Stainless Steel", "Brass", "Composite"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Bosch Rexroth Ltd (Glenrothes)', 'Bosch Rexroth''s Glenrothes, Fife facility is a UK manufacturing plant employing approximately 400 people, producing hydraulic motors for mobile applications including forklift trucks, mini excavators, and other plant machinery for major OEMs such as JCB and Caterpillar. The site is part of Bosch Rexroth''s global Drive & Control technology division. It is a key centre for mobile hydraulics development and manufacturing in the UK.', '{"company_type": "Hydraulic Pump and Motor Manufacturer", "website_url": "https://www.boschrexroth.com/en/gb/", "location": "Glenrothes, Fife, Scotland, UK", "certifications": ["ISO 9001", "ISO 14001", "ISO 45001"], "capabilities": ["Hydraulic Motor Manufacturing", "Mobile Hydraulic Systems", "OEM Supply", "Drive & Control Systems"], "industries": ["Construction", "Materials Handling", "Agriculture", "Industrial Machinery"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": ["Cast Iron", "Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Hunger Hydraulic UK Ltd', 'Hunger Hydraulic UK Ltd, based in Edinburgh and established in 1973, is the UK representative and sales engineering arm of the German Hunger Group, supplying and specifying heavy-duty and special hydraulic cylinders for demanding industrial applications. They have deep heritage in supplying large-bore cylinders for steelworks and have since expanded into offshore, marine, and industrial markets. The Hunger Group has manufactured hydraulic cylinders since 1945.', '{"company_type": "Hydraulic Cylinder Manufacturer", "website_url": "https://hunger-hydraulic.co.uk/", "location": "Edinburgh, Scotland, UK", "certifications": ["ISO 9001"], "capabilities": ["Large-Bore Cylinder Supply", "Special Cylinder Engineering", "High-Pressure Cylinder Design", "Technical Sales & Support"], "industries": ["Steel", "Offshore", "Marine", "Heavy Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1973, "materials": ["Steel", "Stainless Steel", "Chrome-Plated Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Phoenix Fluid Power Ltd', 'Phoenix Fluid Power (formerly Phoenix Hydraulic & Electrical Services) is a Peterborough-based manufacturer of bespoke fluid power systems operating from a 20,000 sqft facility. They design and manufacture fluid control units, hydraulic power packs, electrical control systems, cylinders, and hose kits using in-house CNC machining, waterjet cutting, shot-blasting, and precision welding. They serve aerospace, defence, marine, nuclear, oil and gas, and renewable energy sectors.', '{"company_type": "Fluid Power System Integrator", "website_url": "https://phoenixfluidpower.co.uk/", "location": "Peterborough, Cambridgeshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Hydraulic Power Pack Manufacture", "Fluid Control Unit Design", "CNC Machining", "Hydraulic Cylinder Manufacturing", "Hose Assembly", "Electrical Panel Build"], "industries": ["Aerospace", "Defence", "Marine", "Nuclear", "Oil & Gas", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Steel", "Stainless Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Hydraulic System Products Ltd (HSP)', 'Hydraulic System Products Ltd (HSP), trading since 1972, is a UK manufacturer of hydraulic components including inline and cartridge valves, diagnostic components, and microbore hose assemblies at their West Yorkshire facility. All manufacturing is conducted in-house, including an extensive CNC machine shop, assembly workshop, and hydraulic test area. They supply the offshore, industrial, and mobile sectors and hold ISO 9001 certification.', '{"company_type": "Hydraulic Components Manufacturer", "website_url": "https://h-s-p.co.uk/", "location": "West Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Cartridge Valve Manufacturing", "Inline Valve Production", "CNC Machining", "Hydraulic Test & Validation", "Microbore Hose Assembly"], "industries": ["Offshore", "Industrial Machinery", "Mobile Hydraulics"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1972, "materials": ["Steel", "Stainless Steel", "Aluminium", "Brass"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sarum Hydraulics Ltd', 'Sarum Hydraulics Ltd is a Salisbury-based manufacturer of Micropac brand manual hydraulic hand pumps and associated components, with over 40 years of product development history. They supply industry-standard cartridge hand pumps, pressure testing equipment, and filling solutions to oil and gas, aerospace, and marine customers worldwide. The company is ISO 9001 certified and is a member of Made in Britain.', '{"company_type": "Hydraulic Components Manufacturer", "website_url": "https://sarum-hydraulics.co.uk/", "location": "Old Sarum, Salisbury, Wiltshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Manual Hydraulic Pump Manufacturing", "Pressure Test Equipment Supply", "Hydraulic Filling Systems", "Custom Cartridge Pump Production"], "industries": ["Oil & Gas", "Aerospace", "Marine", "Defence"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1995, "materials": ["Steel", "Stainless Steel", "Aluminium", "Brass"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Staffordshire Hydraulic Services Ltd', 'Staffordshire Hydraulic Services Ltd, founded in 1972 and based in Stoke-on-Trent, is an independent manufacturer and supplier of high-pressure instrumentation fittings, valves, tubing, and manifolds rated to 150,000 psi. They hold sole UK distribution rights for HIP, SC Hydraulics, and DK-Lok high-pressure products and manufacture custom high-pressure assemblies in-house. They serve the energy, petrochemical, test and measurement, and research sectors globally.', '{"company_type": "High-Pressure Fittings and Valve Manufacturer", "website_url": "https://www.staffshydraulics.co.uk/", "location": "Stoke-on-Trent, Staffordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["High-Pressure Fitting Manufacture", "Valve Manufacturing", "Custom Manifold Production", "High-Pressure Tubing Supply"], "industries": ["Oil & Gas", "Petrochemical", "Nuclear", "Test & Measurement", "Research"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1972, "materials": ["Stainless Steel", "Duplex Steel", "Carbon Steel", "Brass"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Custom Fittings Ltd', 'Custom Fittings Ltd is a West Yorkshire manufacturer of stainless steel hydraulic hose fittings, pipe fittings, and adaptors, established in 1982 and operating an AS9100 and ISO 9001-certified facility. They manufacture fittings to BSP, JIS, SAE, and DIN standards in 316 stainless steel and exotic metals, exporting to over 50 countries and having supplied over 25 million fittings to more than 35,000 customers. They serve oil and gas, aerospace, marine, and general fluid power markets.', '{"company_type": "Hydraulic Hose and Fittings Supplier", "website_url": "https://customfittings.com/", "location": "West Yorkshire, UK", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Hose Fitting Manufacture", "Pipe Fitting Production", "Adaptor Manufacturing", "Custom Exotic Metal Fittings"], "industries": ["Oil & Gas", "Aerospace", "Marine", "General Fluid Power"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1982, "materials": ["Stainless Steel 316", "Carbon Steel", "Brass", "Exotic Alloys"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
