INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Trident Hydraulics Ltd', 'Trident Hydraulics Ltd is a Southam, Warwickshire-based designer, manufacturer, and supplier of hydraulic systems and components, including custom manifold blocks produced in-house via their Trident Machining division. They design high-specification bespoke hydraulic circuits using SolidWorks CAD and FEA and supply hydraulic pumps, valves, motors, and power packs. They serve marine, subsea, wind turbine, forestry, and automation markets.', '{"company_type": "Fluid Power System Integrator", "website_url": "https://www.tridenthydraulics.co.uk/", "location": "Southam, Warwickshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Hydraulic Circuit Design", "Manifold Block Manufacturing", "Power Pack Assembly", "Valve & Pump Supply", "3D CAD Design"], "industries": ["Marine", "Subsea", "Renewable Energy", "Forestry", "Automation", "Mobile Machinery"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Steel", "Stainless Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AB Fluid Power Ltd', 'AB Fluid Power Ltd is a Bristol-based fluid power system integrator and authorised distributor, founded in 1985. They design and build complete hydraulic and pneumatic turnkey systems using products from Bosch Rexroth, HYDAC, Parker, ASCO, and Aventics, covering the full scope from system design and simulation through to installation and commissioning. They serve industrial, marine, and process sectors across the UK.', '{"company_type": "Fluid Power System Integrator", "website_url": "https://abfluidpowerltd.co.uk/", "location": "Bristol, UK", "certifications": ["ISO 9001"], "capabilities": ["Hydraulic System Design & Build", "Pneumatic System Integration", "Power Unit Manufacture", "System Commissioning", "Panel Build"], "industries": ["Industrial Machinery", "Marine", "Process Industry", "Construction"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1985, "materials": ["Steel", "Stainless Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Flowfit Ltd', 'Flowfit is a Ludlow, Shropshire-based hydraulic component supplier and bespoke power unit manufacturer, trading since 1996 and operating from a 47,000 sqft warehouse facility. They supply hydraulic cylinders, hand pumps, motors, pumps, valves, hoses, and fittings with next-day delivery and also design and build bespoke hydraulic power units. They serve a wide range of industries globally including construction, agriculture, marine, and industrial manufacturing.', '{"company_type": "Hydraulic Systems", "website_url": "https://www.flowfitonline.com/", "location": "Ludlow, Shropshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Hydraulic Component Distribution", "Bespoke Power Unit Manufacture", "Hydraulic Cylinder Supply", "Hose Assembly"], "industries": ["Construction", "Agriculture", "Marine", "Industrial Manufacturing"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1996, "materials": ["Steel", "Aluminium", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'LIJ Fluid Power Ltd', 'LIJ Fluid Power Ltd is a Leyland, Lancashire-based hydraulic engineering specialist with over 30 years of experience in manufacturing, installing, and servicing hydraulic systems and lubrication components. They work with transport, commercial, and emergency services organisations, as well as renewable energy operators utilising geothermal, wind, wave, and hydro power systems. They provide both standard and bespoke hydraulic solutions for UK and international clients.', '{"company_type": "Fluid Power System Integrator", "website_url": "https://www.lijfluidpowerlimited.co.uk/", "location": "Leyland, Lancashire, UK", "certifications": ["ISO 9001"], "capabilities": ["Hydraulic System Manufacture", "System Installation & Commissioning", "Hydraulic Servicing & Repair", "Lubrication System Design"], "industries": ["Transport", "Emergency Services", "Renewable Energy", "Commercial Vehicles"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Steel", "Stainless Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Enerpac (HTL Group Ltd)', 'HTL Group, headquartered in Cramlington, Northumberland and acquired by Enerpac Tool Group in 2020, is the UK''s leading provider of controlled bolting and high-pressure hydraulic tools, operating as Enerpac''s Bolting Centre of Excellence. They offer sales, rental, calibration, repair, and training for hydraulic torque wrenches, tensioners, nut splitters, and associated high-pressure equipment. They serve oil and gas, petrochemical, power generation, and offshore industries across the UK and internationally.', '{"company_type": "High-Pressure Hydraulic Systems", "website_url": "https://www.htlgroup.com/", "location": "Cramlington, Northumberland, UK", "certifications": ["ISO 9001", "ISO 17025"], "capabilities": ["Hydraulic Bolt Tensioning", "Hydraulic Torque Tool Supply", "High-Pressure Tool Calibration", "Rental & Service Operations"], "industries": ["Oil & Gas", "Petrochemical", "Offshore", "Power Generation", "Nuclear"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Alloy Steel", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Apex Hydraulics Ltd', 'Apex Hydraulics is a UK-based manufacturer and supplier of hydraulic cylinders and associated equipment, offering design and development services across multiple industrial sectors. They manufacture standard and non-standard hydraulic cylinders including diaphragm and piston accumulators on request, and provide cylinder repair and refurbishment alongside new supply. Their customer base includes agriculture, construction, waste management, and marine markets.', '{"company_type": "Hydraulic Cylinder Manufacturer", "website_url": "https://www.apexhydraulics.co.uk/", "location": "UK", "certifications": ["ISO 9001"], "capabilities": ["Hydraulic Cylinder Manufacture", "Cylinder Design & Development", "Accumulator Supply", "Cylinder Repair & Refurbishment"], "industries": ["Agriculture", "Construction", "Waste Management", "Marine"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Steel", "Stainless Steel", "Chrome-Plated Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
