INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nidec Control Techniques Ltd', 'Founded in 1973 in Newtown, Powys, Wales, Control Techniques is the UK''s largest variable speed drive manufacturer and one of the largest in the world, now owned by Japan''s Nidec Corporation. The company designs and manufactures AC drives, DC drives, servo drives, soft starters, and motion controllers from its mid-Wales headquarters, producing around 60,000 PCBs per month. Products serve industrial automation, HVAC, water treatment, and renewable energy sectors globally across more than 100 countries.', '{"company_type": "Variable Speed Drives / Servo Drives", "website_url": "https://acim.nidec.com/drives/control-techniques", "location": "Newtown, Powys, Wales, UK", "certifications": ["ISO 9001", "ISO 14001", "ISO 45001"], "capabilities": ["AC Drive Design", "DC Drive Design", "Servo Drive Design", "Motion Control", "Soft Starters", "PCB Manufacturing"], "industries": ["Industrial Automation", "HVAC", "Water Treatment", "Renewable Energy", "Packaging", "Food & Beverage"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1973, "materials": ["Copper", "Laminated Steel", "Silicon IGBT", "PCB Substrates"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Invertek Drives Ltd', 'Invertek Drives is an independent UK manufacturer of variable frequency drives (VFDs) headquartered in Welshpool, Powys, Wales, founded in 1998. The company employs over 420 people and exports to more than 80 countries, with exports accounting for 95% of sales. Its Optidrive product family controls the speed and torque of AC motors for industrial, HVAC, and pump applications, and the company received the King''s Award for Enterprise in International Trade in 2025.', '{"company_type": "Variable Frequency Drives", "website_url": "https://www.invertekdrives.com", "location": "Welshpool, Powys, Wales, UK", "certifications": ["ISO 9001", "CE", "UL"], "capabilities": ["VFD Design & Manufacture", "Motor Speed Control", "Energy Optimisation", "Pump & Fan Control", "HVAC Control"], "industries": ["Industrial Automation", "HVAC", "Water & Wastewater", "Agriculture", "Food & Beverage"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1998, "materials": ["IGBT Modules", "Copper", "PCB Substrates", "Aluminium Heatsinks"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Turntide Technologies (UK) Ltd', 'Turntide Technologies operates its principal UK engineering and manufacturing campus at Team Valley, Gateshead, having consolidated three North East England sites in 2025. The company designs and manufactures axial flux electric motors, power electronics (inverters), energy storage systems, and thermal management products for heavy transport, rail, construction, and agricultural machinery. As the preferred motor supplier to Hitachi Rail for its intercity battery train programme, Turntide has a strong UK industrial base serving EV and off-highway markets.', '{"company_type": "Electric Motors / Power Electronics", "website_url": "https://turntide.com", "location": "Gateshead, Tyne and Wear, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Axial Flux Motor Design", "Inverter Manufacturing", "Battery System Integration", "Thermal Management", "Power Electronics Assembly"], "industries": ["Rail", "Heavy Vehicles", "Construction & Agricultural Machinery", "Materials Handling", "Urban Transport"], "lead_time": null, "min_order": null, "employees": "250+", "established": 2019, "materials": ["Rare Earth Magnets", "Copper", "Silicon Carbide", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'YASA Ltd', 'YASA (Yokeless and Segmented Armature) was founded in 2009 as a spin-out from the University of Oxford to commercialise a high-power-density axial flux electric motor technology. Acquired by Mercedes-Benz in 2021, the company continues to operate from its facility in Yarnton, near Oxford, which underwent a £12 million upgrade in 2025 to increase production capacity beyond 25,000 units per year. YASA motors are used in Ferrari and AMG hybrid hypercars and are designed for ultra-high-performance automotive and aerospace applications.', '{"company_type": "Axial Flux Electric Motors", "website_url": "https://yasa.com", "location": "Yarnton, Oxfordshire, UK", "certifications": ["ISO 9001", "IATF 16949"], "capabilities": ["Axial Flux Motor Design", "High Power Density Motor Manufacturing", "Yokeless Architecture", "Motorsport & Automotive OEM Supply"], "industries": ["Automotive", "Motorsport", "Aerospace", "High-Performance EVs"], "lead_time": null, "min_order": null, "employees": "250+", "established": 2009, "materials": ["Rare Earth Permanent Magnets", "Copper", "Laminated Steel", "Carbon Fibre Composites"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Magtec Ltd (Magnetic Systems Technology Ltd)', 'Magtec has been designing and manufacturing electric and hybrid drivetrain systems from its Sheffield headquarters since 1992, making it one of the UK''s longest-established traction motor manufacturers. The company produces traction motors, motor controllers, and battery systems for HGVs, buses, off-road vehicles, and tracked defence vehicles, all manufactured in-house at its Newhall Road, Sheffield facility. Magtec is recognised as the UK''s largest supplier of hybrid and electric drive systems for commercial vehicles over 7.5 tonnes.', '{"company_type": "Traction Motors / Drive Systems", "website_url": "https://magtec.co.uk", "location": "Sheffield, South Yorkshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Traction Motor Design & Manufacture", "Motor Controller Design", "Battery System Integration", "EV Drivetrain Integration", "Vehicle Repowering"], "industries": ["Heavy Vehicles", "Defence", "Buses & Coaches", "Off-Highway", "Construction"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1992, "materials": ["Rare Earth Permanent Magnets", "Copper", "Laminated Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Equipmake Ltd', 'Founded in 1997 and based in Snetterton, Norfolk, Equipmake designs and manufactures high-power-density electric motors, SiC inverters, and complete electric drivetrains for automotive, aerospace, marine, bus, and construction sectors. Its APM200 motor is one of the highest power-to-torque-density production automotive motors in the world. The company has supplied electric propulsion systems for Vertical Aerospace''s eVTOL prototype and has opened a dedicated electric bus factory at its Snetterton site.', '{"company_type": "Electric Motors / Inverters / Drive Systems", "website_url": "https://equipmake.co.uk", "location": "Snetterton, Norfolk, UK", "certifications": ["ISO 9001"], "capabilities": ["High Power Density Motor Design", "SiC Inverter Design", "E-Axle Integration", "Bus Repowering", "Aerospace Propulsion", "Motorsport Drive Systems"], "industries": ["Automotive", "Aerospace", "Marine", "Bus & Coach", "Construction", "Motorsport"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1997, "materials": ["Rare Earth Permanent Magnets", "Silicon Carbide", "Copper", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Dynex Semiconductor Ltd', 'Dynex Semiconductor, based in Lincoln, is one of the UK''s only remaining silicon fabrication facilities for high-power semiconductors, with roots going back over 50 years to AEI Semiconductors. The company designs and manufactures IGBT modules, fast diodes, thyristors, gate turn-off thyristors, and power assemblies for traction, renewable energy, marine, industrial, and EV applications, supplying customers in over 60 countries. Dynex is owned by Zhuzhou CRRC Times Electric, the leading Chinese railway power electronics provider, which acquired it in 2008.', '{"company_type": "Power Semiconductors (IGBT / Thyristors)", "website_url": "https://www.dynexsemi.com", "location": "Lincoln, Lincolnshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["IGBT Module Fabrication", "Thyristor Manufacturing", "Power Assembly Design", "Silicon Device Testing", "High Voltage Semiconductor Design"], "industries": ["Rail Traction", "Renewable Energy", "Marine", "Industrial Drives", "Power Transmission", "Electric Vehicles"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1970, "materials": ["Silicon", "Copper", "Aluminium Oxide", "Solder Alloys"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Turbo Power Systems Ltd (TPS)', 'Turbo Power Systems, based in Gateshead, Tyne and Wear, designs and manufactures high-speed permanent magnet motors, generators, and grid-tied power electronics for distributed generation, waste heat recovery, industrial compression, and rail applications. The company''s axial flux technology originates from Turbo Genset, a spin-out from Imperial College London, and TPS has design and manufacturing capabilities for machines operating up to 160,000 rpm and 1 MW. Its inverters achieve system efficiency exceeding 96% across the operating range.', '{"company_type": "Permanent Magnet Generators / Power Electronics", "website_url": "https://www.turbopowersystems.com", "location": "Gateshead, Tyne and Wear, UK", "certifications": ["ISO 9001"], "capabilities": ["High-Speed PM Machine Design", "Axial Flux Generator Manufacturing", "Grid-Tied Inverter Design", "Waste Heat Recovery Systems", "Power Electronics Assembly"], "industries": ["Rail", "Distributed Generation", "Industrial Compression", "Waste Heat Recovery", "HVAC"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1986, "materials": ["Rare Earth Permanent Magnets", "Copper", "Laminated Steel", "Carbon Fibre"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'PMW Dynamics Ltd (formerly Printed Motor Works)', 'PMW Dynamics, headquartered in Alton, Hampshire, is Europe''s largest manufacturer of printed armature pancake servo motors and traces its lineage to the original Printed Motors Limited, founded in 1963. The company manufactures both brushed and brushless DC servo motors in axial and radial flux configurations, covering applications in robotics, medical devices, aerospace, automotive, and defence, and exports over 50% of its output to EMEA, APAC, and the Americas. Products range from ultra-thin printed armature motors to high-torque in-wheel and frameless motors.', '{"company_type": "Servo Motors / Pancake Motors", "website_url": "https://www.pmwdynamics.com", "location": "Alton, Hampshire, UK", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Printed Armature Motor Manufacturing", "Axial Flux Motor Design", "Brushless Servo Motor Design", "Custom Motor Development", "In-Wheel Motor Design"], "industries": ["Aerospace", "Defence", "Robotics", "Medical Devices", "Automotive", "Industrial Automation"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1963, "materials": ["Copper", "Rare Earth Permanent Magnets", "Aluminium", "Printed Armature Composites"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Brook Crompton UK Ltd', 'Brook Crompton is one of the UK''s oldest electric motor brands, tracing its history to Ernest Brook''s first AC motor made in Huddersfield in 1904. The company supplies a comprehensive range of low, medium, and high voltage induction motors for safe and hazardous-area applications across a broad range of industrial processes including mining, water treatment, and petrochemicals. Brook Crompton motors are distributed across the UK, Europe, Middle East, North America, and Asia Pacific from its Huddersfield headquarters.', '{"company_type": "Industrial Electric Motors (AC Induction)", "website_url": "https://www.brookcrompton.com", "location": "Huddersfield, West Yorkshire, UK", "certifications": ["ISO 9001", "ATEX", "IECEx"], "capabilities": ["LV Motor Supply", "MV Motor Supply", "HV Motor Supply", "Hazardous Area Motors", "Energy Efficient Motor Design"], "industries": ["Mining", "Water & Wastewater", "Petrochemical", "Oil & Gas", "Food & Beverage", "Industrial Processing"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1904, "materials": ["Copper", "Laminated Steel", "Cast Iron", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nidec SR Drives Ltd', 'Nidec SR Drives, headquartered in Harrogate, North Yorkshire, is the world pioneer in commercialising switched reluctance motor technology under the SR Drive trademark, having developed the technology since the early 1980s and joined Nidec Corporation in 2010. The company undertakes research, development, prototyping, and licensing of switched reluctance and other advanced electrical drive systems from a few watts to several megawatts. Its engineering capabilities span electromagnetic design, power electronics, mechanical and thermal design, and rapid prototyping.', '{"company_type": "Switched Reluctance Motors & Drives", "website_url": "https://acim.nidec.com/motors/trusted-brands/sr-drives", "location": "Harrogate, North Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Switched Reluctance Motor Design", "Power Electronics Design", "Drive System Licensing", "Electromagnetic Design", "Rapid Prototyping"], "industries": ["Industrial Automation", "HVAC", "Automotive", "Oil & Gas", "Aerospace", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1980, "materials": ["Laminated Steel", "Copper", "Silicon IGBT"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'STAMFORD | AvK (Cummins Generator Technologies)', 'STAMFORD | AvK, the market name for Cummins Generator Technologies, was founded in Stamford, Lincolnshire in 1904 and is one of the world''s leading manufacturers of AC alternators for power generation, covering 7.5 to 11,200 kVA. The company is headquartered in Peterborough and maintains its Alternator Technology Centre in Stamford, UK, serving as the global R&D and engineering hub for the brand. Its alternators are used worldwide in standby, prime, and continuous power generation for data centres, hospitals, utilities, and construction.', '{"company_type": "AC Alternators / Generators", "website_url": "https://www.stamford-avk.com", "location": "Peterborough / Stamford, Lincolnshire, UK", "certifications": ["ISO 9001", "ISO 14001", "UL", "CSA"], "capabilities": ["Alternator Design & Engineering", "Generator Testing", "High Voltage Winding", "Custom Alternator Configuration", "Aftermarket Support"], "industries": ["Power Generation", "Data Centres", "Healthcare", "Oil & Gas", "Marine", "Construction"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1904, "materials": ["Copper", "Laminated Steel", "Cast Iron", "Insulation Class H Materials"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Preformed Windings Ltd', 'Preformed Windings, based in Rotherham, South Yorkshire, manufactures precision high-voltage motor and generator coils and AC-DC armature traction coils for customers worldwide, with over 50 years of manufacturing experience. The company specialises in custom HV coils with the industry''s lowest partial discharge and tan delta performance levels, backed by a 10-year guarantee, serving motor rewind shops, OEM manufacturers, and rail traction operators. A second Rotherham facility opened in December 2024, expanding production capacity by 60%, and the company has received the AEMT Supplier of the Year award in 2021 and 2024.', '{"company_type": "Motor Coil / Winding Manufacturer", "website_url": "https://www.preformedwindings.com", "location": "Rotherham, South Yorkshire, UK", "certifications": ["ISO 9001", "AEMT Member", "EASA Member"], "capabilities": ["HV Coil Manufacturing", "Armature Coil Manufacturing", "Traction Motor Coil Supply", "Custom Winding Design", "Generator Coil Supply"], "industries": ["Rail Traction", "Power Generation", "Industrial Motors", "Marine", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1970, "materials": ["Copper", "Mica Insulation", "Epoxy Resin", "Polyimide Film"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Winder Power Ltd (incorporating Newton Derby)', 'Winder Power, based in Leeds with a history dating back to 1898, is a leading UK manufacturer of power and distribution transformers, with its rotating-machines division Newton Derby being the UK''s leading manufacturer of permanent magnet generators and synchronous machine exciters for the power generation industry. The company serves utilities, renewable energy operators, and industrial clients including SSE, Scottish Power, GE Energy, and Drax Power from its 80,000 square foot Leeds factory. Newton Derby has developed permanent magnet generation prototypes for wind, tidal, and pipeline generation applications.', '{"company_type": "Permanent Magnet Generators / Transformers", "website_url": "https://www.winderpower.co.uk", "location": "Leeds, West Yorkshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Permanent Magnet Generator Design & Manufacture", "Synchronous Exciter Manufacturing", "Transformer Manufacturing", "Tidal & Wind Generator Prototyping", "Generator Testing"], "industries": ["Power Generation", "Renewable Energy", "Utilities", "Industrial", "Marine"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1898, "materials": ["Copper", "Rare Earth Permanent Magnets", "Ferrite Magnets", "Laminated Steel", "Insulation Systems"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Deritend Group Ltd', 'Deritend was founded in Birmingham in 1898 and has grown into one of the UK''s leading providers of electric motor repair, rewind, and engineering services, serving over 3,500 customers across multiple sites. The company carries out overhaul, rewind, and repair of low and high voltage AC and DC motors, servo motors, alternators, generators, and transformers, complying with EASA and AEMT codes of practice. Its client base includes large blue-chip manufacturers across industrial, utilities, and process sectors across the UK.', '{"company_type": "Electric Motor Repair & Rewind", "website_url": "https://www.deritend.co.uk", "location": "Birmingham, West Midlands, UK", "certifications": ["ISO 9001", "EASA Accredited", "AEMT Member"], "capabilities": ["Motor Rewind", "HV Motor Overhaul", "Servo Motor Repair", "Generator Overhaul", "Dynamic Balancing", "Laser Alignment", "On-Site Services"], "industries": ["Manufacturing", "Utilities", "Water & Wastewater", "Petrochemical", "Food & Beverage", "Defence"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1898, "materials": ["Copper", "Insulation Systems", "Bearing Assemblies"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pektron Group Ltd', 'Pektron, headquartered on a seven-acre campus in Derby, is one of the largest privately owned electronics design and manufacturing companies in the UK, with over 60 years of experience. The company designs, develops, and manufactures electronic control units and power electronics modules for automotive OEMs and electric vehicle manufacturers, including body control modules, EV power management systems, and motor controllers. Pektron operates the UK''s largest privately owned EMC test chamber and serves customers across automotive, electric vehicles, HVAC, and agriculture sectors.', '{"company_type": "Power Electronics / EV Electronics Manufacturing", "website_url": "https://www.pektron.com", "location": "Derby, Derbyshire, UK", "certifications": ["ISO 9001", "IATF 16949", "ISO 14001"], "capabilities": ["Power Electronics Design", "ECU Manufacturing", "EV Electronics Development", "EMC Testing", "Injection Moulding", "PCB Assembly"], "industries": ["Automotive", "Electric Vehicles", "HVAC", "Agriculture", "Construction", "Consumer Electronics"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1964, "materials": ["Silicon IGBT", "GaN Semiconductors", "PCB Substrates", "Copper"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'GreenSpur Wind Ltd', 'GreenSpur Wind, based in Stockton-on-Tees, is an innovative SME developing axial flux permanent magnet generators for onshore and offshore wind turbines that use no rare earth magnets and no copper windings. The company''s modular generator design uses ferrite magnets and aluminium coils, eliminating supply chain risk from critical materials while achieving scalability from 10 kW to 20 MW. GreenSpur has demonstrated its technology at the Offshore Renewable Energy Catapult in Blyth and received an international generator order from US firm Wind Harvest in 2021.', '{"company_type": "Wind Turbine Generators", "website_url": "https://www.greenspur.co.uk", "location": "Stockton-on-Tees, Teesside, UK", "certifications": ["ISO 9001"], "capabilities": ["Axial Flux Generator Design", "Rare Earth-Free Magnet Technology", "Direct Drive Generator Design", "Modular Generator Architecture", "Wind Turbine Integration"], "industries": ["Onshore Wind", "Offshore Wind", "Tidal Energy", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2014, "materials": ["Ferrite Magnets", "Aluminium", "Composite Materials"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cambridge GaN Devices Ltd (CGD)', 'Cambridge GaN Devices is a fabless semiconductor company spun out from the University of Cambridge in 2016 by Professor Florin Udrea and Dr Giorgia Longobardi, developing GaN power transistors and ICs for electric vehicles, data centres, renewable energy, and industrial power conversion. The company''s ICeGaN platform offers a normally-off enhancement-mode GaN transistor that operates with standard silicon gate drivers without requiring negative voltages, making it compatible with existing motor drive and power converter designs. CGD closed a $32 million Series C funding round in February 2025.', '{"company_type": "GaN Power Semiconductors", "website_url": "https://camgandevices.com", "location": "Cambridge, Cambridgeshire, UK", "certifications": ["ISO 9001"], "capabilities": ["GaN Transistor Design", "Power IC Development", "Fabless Semiconductor", "Gate Driver Integration", "Power Converter Optimisation"], "industries": ["Electric Vehicles", "Data Centres", "Renewable Energy", "Industrial Power Conversion", "Consumer Electronics"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2016, "materials": ["Gallium Nitride", "Silicon", "Wide-Bandgap Semiconductors"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Protean Electric Ltd', 'Protean Electric, based in Farnham, Surrey, developed an in-wheel electric motor system that packages the motor, power electronics, and controls within the wheel itself, delivering 80 kW and 1,250 Nm per wheel. The company holds over 330 patents and has attracted automotive OEM interest for applications including the forthcoming Renault 5 Turbo 5E sportscar. After a series of ownership changes, Protean was acquired by Japanese manufacturer Exedy for approximately €30 million, continuing its UK-based engineering operations.', '{"company_type": "In-Wheel Electric Motors", "website_url": "https://www.proteanelectric.com", "location": "Farnham, Surrey, UK", "certifications": ["ISO 9001", "IATF 16949"], "capabilities": ["In-Wheel Motor Design", "Integrated Power Electronics", "Embedded Motor Control", "EV Drivetrain Integration", "IP Licensing"], "industries": ["Automotive", "Electric Vehicles", "Commercial Vehicles"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 2008, "materials": ["Rare Earth Permanent Magnets", "Copper", "Silicon IGBT", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Mawdsley''s BER Ltd', 'Mawdsley''s BER, based in Bristol, is a specialist electric motor overhaul and repair company with over 100 years of experience servicing high-voltage motors, generators, and transformers for heavy industry, petrochemical, and marine sectors. The company operates as an EASA and AEMT-accredited repair centre and carries out full rewinds, bearing replacements, shaft repairs, and balancing on AC and DC machines up to several megawatts. Its engineering team also provides on-site diagnostics, condition monitoring, and preventive maintenance services.', '{"company_type": "Electric Motor Repair & Rewind", "website_url": "https://www.mawdsleysber.co.uk", "location": "Bristol, UK", "certifications": ["ISO 9001", "EASA Accredited", "AEMT Member"], "capabilities": ["HV Motor Rewind", "AC/DC Motor Overhaul", "Generator Rewind", "Dynamic Balancing", "On-Site Diagnostics", "Condition Monitoring"], "industries": ["Petrochemical", "Marine", "Utilities", "Manufacturing", "Mining"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1900, "materials": ["Copper", "Mica Insulation", "Epoxy Systems", "Bearing Steels"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Napier Turbochargers Ltd', 'Napier Turbochargers, based in Lincoln, designs and manufactures high-efficiency industrial turbochargers for high-horsepower engines used in marine propulsion, rail traction, and power generation applications, with over 50,000 units produced over more than 60 years. The company supports a wide range of fuel types including marine diesel oil, natural gas, HFO, and landfill gas, and offers global on-site servicing and overhaul from its Lincoln headquarters. Napier was acquired by Wabtec Corporation in 2013 and continues to operate as a specialist engineering business within the group.', '{"company_type": "Turbochargers / Rotating Machinery", "website_url": "https://www.napier-turbochargers.com", "location": "Lincoln, Lincolnshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Turbocharger Design & Manufacture", "Marine Engine Turbocharging", "Rail Traction Turbocharging", "Power Generation Support", "Aftermarket Servicing"], "industries": ["Marine", "Rail", "Power Generation", "Oil & Gas"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1960, "materials": ["Nickel Superalloys", "Titanium", "Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Trident Engineering Ltd', 'Trident Engineering, based in Winnersh, Berkshire, has been a specialist UK distributor and sub-system builder for small DC, stepper, and brushless motors for over 50 years, growing into a multi-million pound operation serving the high-quality small motor market. From its 5,000 sq ft Winnersh premises, the company builds bespoke motor systems combining gearheads, encoders, tachometers, and electronic controllers to customer specifications, and holds over £600,000 of stock for rapid delivery. Products serve medical devices, robotics, automation, and instrumentation markets.', '{"company_type": "DC Motors / Servo Motor Systems", "website_url": "https://www.tridenteng.co.uk", "location": "Winnersh, Berkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Brushless DC Motor Supply", "Stepper Motor Systems", "Geared Motor Sub-assembly", "Encoder Integration", "Bespoke Motor System Building"], "industries": ["Medical Devices", "Robotics", "Automation", "Instrumentation", "Defence"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1970, "materials": ["Copper", "Rare Earth Permanent Magnets", "Laminated Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Bellwood Rewinds Ltd', 'Bellwood Rewinds is a UK electric motor repair and rewind specialist operating from Hartlepool, with nearly 30 years of experience servicing AC and DC motors, servo motors, and generators. The company operates an 8,000 sq ft workshop fully equipped for motor diagnosis, rewind, modification, dynamic balancing, and load testing, and provides on-site servicing and generator repair services covering a wide range of brands. Bellwood Rewinds services industries including food processing, pharmaceuticals, and heavy manufacturing across the North of England.', '{"company_type": "Electric Motor Repair & Rewind", "website_url": "https://www.bellwoodrewinds.co.uk", "location": "Hartlepool, County Durham, UK", "certifications": ["ISO 9001", "AEMT Member"], "capabilities": ["AC Motor Rewind", "DC Motor Rewind", "Servo Motor Repair", "Generator Overhaul", "Dynamic Balancing", "Load Testing"], "industries": ["Food Processing", "Pharmaceuticals", "Heavy Manufacturing", "Utilities", "Marine"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1996, "materials": ["Copper", "Insulation Systems", "Bearing Assemblies"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'GE Vernova Power Conversion (UK) Ltd', 'GE Vernova Power Conversion''s UK operations, based in Kidsgrove, Staffordshire (formerly Converteam UK), specialises in high-power variable speed drive systems, electric motors, and generators for marine, offshore, wind, and industrial applications. The business designs integrated power and propulsion systems for naval and commercial vessels, offshore platforms, and grid-connected industrial drives, with products covering low and medium voltage applications. The Kidsgrove facility is a global centre of excellence for marine power conversion within GE Vernova.', '{"company_type": "Variable Speed Drives / Industrial Motors / Marine Power Systems", "website_url": "https://www.gevernova.com/power-conversion", "location": "Kidsgrove, Staffordshire, UK", "certifications": ["ISO 9001", "ISO 14001", "DNV", "Lloyd''s Register"], "capabilities": ["Marine Propulsion Drive Design", "Medium Voltage Drive Systems", "Generator Design", "Offshore Power Systems", "Wind Power Electronics"], "industries": ["Marine", "Offshore Oil & Gas", "Naval Defence", "Wind Energy", "Industrial"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1962, "materials": ["Silicon IGBT", "Copper", "Laminated Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'IMAG Ltd (Industrial Motors and Gears)', 'IMAG, a UK industrial engineering company, provides a combined service covering electric motor rewind and repair, gearbox repair, and supply of industrial electric motors and geared motors from leading manufacturers. Operating with a 24-hour emergency service, the company uses a state-of-the-art pyrolysis oven and curing oven capable of handling motors up to 400 frame size, and provides machined parts, fabricated assemblies, and metal spraying services alongside rewind work. IMAG serves food processing, water treatment, and general manufacturing industries across the UK.', '{"company_type": "Electric Motor Repair & Rewind / Gearbox Repair", "website_url": "https://www.imag-uk.com", "location": "UK (multiple service locations)", "certifications": ["ISO 9001", "AEMT Member"], "capabilities": ["Motor Rewind & Repair", "Gearbox Overhaul", "Pyrolysis Winding Strip", "Machined Spares Manufacture", "24-Hour Emergency Response"], "industries": ["Food Processing", "Water & Wastewater", "Manufacturing", "Mining", "Petrochemical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Copper", "Insulation Systems", "Bearing Assemblies"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Power Jacks Ltd', 'Power Jacks, headquartered near Aberdeen, Aberdeenshire, Scotland, is the UK''s largest manufacturer of precision screw jacks, electric linear actuators, bevel gearboxes, and jacking systems, operating from a modern purpose-built facility in Westhill. With products deployed in over 80 countries across energy, industrial automation, transport, civil, and defence sectors, the company integrates electric motor drives with precision mechanical actuation. Power Jacks holds Made in Britain accreditation and has over 60 skilled engineers and production staff.', '{"company_type": "Electric Linear Actuators / Mechanical Power Transmission", "website_url": "https://www.powerjacks.com", "location": "Westhill, Aberdeenshire, Scotland, UK", "certifications": ["ISO 9001", "Made in Britain"], "capabilities": ["Screw Jack Manufacturing", "Electric Linear Actuator Design", "Bevel Gearbox Manufacturing", "Jacking System Integration", "Custom Actuator Engineering"], "industries": ["Energy", "Industrial Automation", "Defence", "Civil Engineering", "Transport"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1990, "materials": ["Steel", "Bronze", "Copper", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Dyson Technology Ltd', 'Dyson Technology, headquartered in Malmesbury, Wiltshire, is a global engineering company that designs and manufactures its own high-speed digital electric motors for use in its vacuum cleaners, hand dryers, hair care products, and air purifiers. The company has invested heavily in motor R&D through a research partnership at Newcastle University, and operates motor manufacturing at scale from its Singapore facility while its UK campus in Hullavington and Malmesbury houses core engineering and motor R&D teams. Dyson''s brushless DC motors operate at up to 125,000 rpm and are among the highest speed commercial motors produced at consumer scale.', '{"company_type": "High-Speed Brushless DC Motor Design", "website_url": "https://www.dyson.co.uk", "location": "Malmesbury, Wiltshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Brushless DC Motor Design", "High-Speed Motor R&D", "Motor Electronics Integration", "Consumer Product Motor Manufacturing", "Digital Motor Control"], "industries": ["Consumer Appliances", "HVAC", "Personal Care"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1991, "materials": ["Rare Earth Permanent Magnets", "Copper", "Carbon Fibre", "Polycarbonate"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


