INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'The Barden Corporation (UK) Ltd / HQW Aerospace UK', 'Barden Bearings has operated in Plymouth since 1942 and is a world leader in super-precision ball bearings for aerospace, defence, medical, and vacuum technology. The Plymouth factory contains a Class 7 cleanroom for contamination-free assembly and inspection. Now trading as HQW Aerospace UK following acquisition by Schaeffler Group''s HQW brand.', '{"company_type": "Precision Bearing Manufacturing", "website_url": "https://www.bardenbearings.co.uk", "location": "Plymouth, Devon, UK", "certifications": ["ISO 9001", "ISO 14001", "ISO 45001", "ISO 50001", "AS9100", "AS9120"], "capabilities": ["Super Precision Ball Bearing Manufacture", "Cleanroom Assembly", "Custom Bearing Design", "Spindle Bearing Manufacture", "Angular Contact Bearing Manufacture"], "industries": ["Aerospace", "Defence", "Medical", "Vacuum Technology", "Semiconductor"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1942, "materials": ["Chrome Steel", "Stainless Steel", "Ceramic", "PEEK"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'NSK Bearings Europe Ltd (Newark Plant)', 'NSK''s Newark, Nottinghamshire facility, originally the Ransome & Marles plant founded in 1900, manufactures high-precision angular-contact ball bearings and linear guides for the European market. The site, including manufacturing, logistics, and technology centre, employs approximately 500 people. NSK acquired the RHP Group in 1990, absorbing the historic RHP (Ransome Hoffmann Pollard) bearing manufacturing legacy.', '{"company_type": "Bearing Manufacturing", "website_url": "https://www.nsk.com/eu-en/", "location": "Newark, Nottinghamshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Angular Contact Ball Bearing Manufacture", "Linear Guide Manufacture", "Precision Grinding", "Bearing Testing", "R&D / Technology Centre"], "industries": ["Automotive", "Machine Tools", "Aerospace", "Industrial Machinery", "Robotics"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1900, "materials": ["Chrome Steel", "Stainless Steel", "Ceramic"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HB Bearings Ltd', 'HB Bearings is a UK bespoke bearing manufacturer based in Honley, Huddersfield, West Yorkshire, specialising in the manufacture of special metric and imperial bearings and standard bearings which are difficult to source. The company concentrates on low-volume production of specialist bearings and has been established for over 45 years. HB manufactures bespoke bearings for high-end supercar manufacturers and other niche applications.', '{"company_type": "Bespoke Bearing Manufacturing", "website_url": "https://www.hb-bearings.com", "location": "Honley, Huddersfield, West Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Custom Bearing Manufacture", "Imperial and Metric Bearing Production", "Low Volume Specialist Bearings", "Non-Standard Bearing Supply"], "industries": ["Automotive", "Motorsport", "Aerospace", "Defence", "Industrial Machinery"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Chrome Steel", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'James Walker & Co Ltd', 'James Walker is a privately owned international manufacturing group based in Cockermouth, Cumbria, and is the UK''s leading manufacturer of high-performance fluid sealing products. The company manufactures over 200,000 different products including compression packings, gaskets, hydraulic seals, O-rings, mechanical seals, and expansion joints. James Walker supplies virtually every sector of industry including nuclear power, oil and gas, marine propulsion, and offshore wind energy.', '{"company_type": "Seal Manufacturing", "website_url": "https://www.jameswalker.biz", "location": "Cockermouth, Cumbria, UK", "certifications": ["ISO 9001", "ISO 14001", "ISO 45001", "AS9100", "ASME", "JOSCAR"], "capabilities": ["Hydraulic Seal Manufacture", "Compression Packing Manufacture", "Gasket Manufacture", "O-Ring Manufacture", "Mechanical Seal Manufacture", "Custom Sealing Solutions"], "industries": ["Oil & Gas", "Nuclear", "Marine", "Aerospace", "Wind Energy", "Petrochemical", "Water Treatment"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": ["PTFE", "Elastomers", "FKM", "EPDM", "Nitrile", "Graphite", "PEEK"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Trelleborg Sealing Solutions UK Ltd (Bridgwater)', 'Trelleborg''s Bridgwater, Somerset facility was founded in 1935 as the Wills Pressure Filled Joint Company and has developed into a specialised manufacturing site producing high-performance seals in advanced PTFE materials, including the proprietary Variseal spring-energised PTFE seal and Wills Rings. The site serves aerospace, oil and gas, and industrial markets with precision engineered sealing products across all market segments.', '{"company_type": "Seal Manufacturing", "website_url": "https://www.trelleborg.com/en/seals", "location": "Bridgwater, Somerset, UK", "certifications": ["ISO 9001", "AS9100", "ISO 14001", "ISO/TS 16949"], "capabilities": ["PTFE Seal Manufacture", "Spring-Energised Seal Design", "Custom Seal Engineering", "Variseal Production", "Wills Ring Production"], "industries": ["Aerospace", "Oil & Gas", "Automotive", "Industrial Machinery", "Semiconductor"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1935, "materials": ["PTFE", "Spring Steel", "Stainless Steel", "Polyurethane"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Trelleborg Sealing Solutions UK Ltd (Tewkesbury)', 'Trelleborg''s Tewkesbury, Gloucestershire facility is one of the prime European production and development centres for standard and custom elastomer sealing products, primarily serving the aerospace and niche industrial market segments. The site manufactures bonded seals, radial oil seals, and gaskets and holds in-house elastomer compound development capabilities. Trelleborg Sealing Solutions operates 28 manufacturing plants worldwide.', '{"company_type": "Seal Manufacturing", "website_url": "https://www.trelleborg.com/en/seals", "location": "Tewkesbury, Gloucestershire, UK", "certifications": ["ISO 9001", "AS9100", "ISO/TS 16949"], "capabilities": ["Elastomer Seal Manufacture", "Bonded Seal Manufacture", "Radial Oil Seal Manufacture", "Custom Compound Development", "Gasket Manufacture"], "industries": ["Aerospace", "Automotive", "Defence", "Industrial Machinery"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": ["Nitrile (NBR)", "FKM (Viton)", "EPDM", "Silicone", "Elastomers"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Precision Polymer Engineering Ltd (PPE)', 'Founded in 1975 and headquartered in Blackburn, Lancashire, PPE is a leading provider of high-performance O-rings, technical rubber mouldings, and sealing solutions for demanding industrial environments. PPE is a business unit of IDEX Corporation and operates manufacturing facilities in both the UK and the US. The company holds NADCAP accreditation for aerospace elastomer seal manufacture and its proprietary Perlast perfluoroelastomer brand is well established in semiconductor and chemical processing applications.', '{"company_type": "Seal Manufacturing", "website_url": "https://www.prepol.com", "location": "Blackburn, Lancashire, UK", "certifications": ["ISO 9001", "NADCAP", "AS9100"], "capabilities": ["O-Ring Manufacture", "Custom Elastomer Moulding", "Perfluoroelastomer Seal Manufacture", "Cleanroom Seal Manufacture", "Rapid Prototyping"], "industries": ["Semiconductor", "Aerospace", "Oil & Gas", "Pharmaceutical", "Chemical Processing", "Life Sciences", "Nuclear"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1975, "materials": ["FFKM (Perfluoroelastomer)", "FKM (Viton)", "EPDM", "Nitrile", "Silicone", "PTFE"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'M Barnwell Services Ltd', 'Established in 1972 and headquartered in Birmingham, M Barnwell Services is the UK''s largest independent manufacturer, stockist, and distributor of fluid sealing products. Operating from a 56,000 sq ft headquarters with five UK distribution hubs, the company holds over 8 million stock items across 35,000 stock lines. The company has CNC seal-making machines on site and can produce emergency seals in under an hour.', '{"company_type": "Seal Manufacturing & Distribution", "website_url": "https://www.barnwell.co.uk", "location": "Birmingham, West Midlands, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["O-Ring Supply", "Hydraulic Seal Manufacture", "Pneumatic Seal Supply", "CNC Seal Making", "Emergency Seal Production", "Rotary Shaft Seal Supply"], "industries": ["Hydraulic Engineering", "Automotive", "Oil & Gas", "Pharmaceutical", "Food & Beverage", "Industrial Machinery"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1972, "materials": ["Nitrile (NBR)", "FKM (Viton)", "EPDM", "PTFE", "Polyurethane", "Silicone"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'FPE Seals Ltd', 'Founded in 1984 and based in Darlington, County Durham, FPE Seals is a worldwide distributor and manufacturer of sealing products with over 40 years of industry expertise. The company stocks and supplies over 35,000 hydraulic and pneumatic sealing products including hydraulic seals, mechanical seals, O-rings, and hydraulic cylinder components. FPE Seals operates multiple branches across the UK and also has a branch in the Netherlands.', '{"company_type": "Seal Distribution & Manufacturing", "website_url": "https://www.fpeseals.com", "location": "Darlington, County Durham, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Hydraulic Seal Supply", "Pneumatic Seal Supply", "O-Ring Supply", "Mechanical Seal Supply", "Cylinder Component Supply"], "industries": ["Hydraulic Engineering", "Automotive", "Agriculture", "Construction", "Industrial Machinery"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1984, "materials": ["Nitrile (NBR)", "FKM (Viton)", "Polyurethane", "PTFE", "EPDM"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Ashton Seals Ltd', 'With a trading history dating back to 1866, Ashton Seals is based at a purpose-built facility on Cortonwood Business Park, Barnsley, South Yorkshire. The company supplies O-rings, bonded seals, gaskets, FEP encapsulated seals, fasteners, and lubrication equipment. Ashton Seals is part of The Ashton Group and holds ISO 9001 accreditation.', '{"company_type": "Seal Distribution & Supply", "website_url": "https://www.ashtonseals.co.uk", "location": "Barnsley, South Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["O-Ring Supply", "Bonded Seal Supply", "Gasket Supply", "FEP Encapsulated Seal Supply", "Lubrication Equipment Supply"], "industries": ["Oil & Gas", "Petrochemical", "Hydraulic Engineering", "Automotive", "Industrial Machinery"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1866, "materials": ["Nitrile (NBR)", "FKM (Viton)", "EPDM", "Silicone", "PTFE", "FEP"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Carter Manufacturing Ltd', 'Based in Abingdon, Oxfordshire, Carter Manufacturing is the European Master Distributor for Silverthin precision thin-section bearings and holds ISO 9001 incorporating AS9120 certification. The company supplies thin-section bearings widely used in robot joints, gimbals, optical devices, and satellite systems due to their low mass and high rigidity. Carter also specialises in bearings for oil and gas subsea applications and ultra-high vacuum environments.', '{"company_type": "Precision Bearing Distribution & Engineering", "website_url": "https://www.carterbearings.co.uk", "location": "Abingdon, Oxfordshire, UK", "certifications": ["ISO 9001", "AS9120"], "capabilities": ["Thin Section Bearing Supply", "Aerospace Bearing Supply", "Custom Bearing Specification", "Oil & Gas Bearing Engineering", "Ultra-High Vacuum Bearing Supply"], "industries": ["Robotics", "Aerospace", "Defence", "Medical", "Semiconductor", "Oil & Gas", "Satellite"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2000, "materials": ["Chrome Steel", "Stainless Steel", "PEEK", "Ceramic"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'NBC Group Ltd', 'NBC Group is a family-owned business founded in 1958 and based in Telford, Shropshire, supplying bearings and mechanical power transmission components to UK and global trade and OEM customers. The company''s particular area of excellence is its own QCB brand of slewing rings and drives, ranging from 170 mm to 11,000 mm in diameter, as well as mounted ball bearings, thermoplastic housings, and screen bearings. NBC Group holds ISO 9001 certification.', '{"company_type": "Bearing & Slewing Ring Manufacturing/Distribution", "website_url": "https://nbcgroup.co.uk", "location": "Telford, Shropshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Slewing Ring Supply", "Slew Drive Supply", "Mounted Bearing Supply", "Large Diameter Bearing Engineering", "OEM Bearing Solutions"], "industries": ["Wind Energy", "Construction", "Mining", "Agriculture", "Industrial Machinery", "Material Handling"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1958, "materials": ["Chrome Steel", "Stainless Steel", "Thermoplastic"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HepcoMotion Ltd', 'Founded in 1969 and based in Tiverton, Devon, HepcoMotion is a UK manufacturer of linear motion systems and automation components that originated the V-guide and bearing slide technology widely used in automation worldwide. The company manufactures V-guide linear slides, PRT2 ring and track systems, ball screw actuators, linear guides, and cam followers. HepcoMotion serves packaging, robotics, automotive, and aerospace industries from its Devon headquarters.', '{"company_type": "Linear Motion Manufacturing", "website_url": "https://www.hepcomotion.com", "location": "Tiverton, Devon, UK", "certifications": ["ISO 9001"], "capabilities": ["V-Guide Linear Slide Manufacture", "Ring and Track System Manufacture", "Ball Screw Actuator Manufacture", "Linear Guide Manufacture", "Custom Linear System Design"], "industries": ["Packaging", "Robotics", "Automotive", "Aerospace", "Machine Tools", "Industrial Automation"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1969, "materials": ["Hardened Steel", "Stainless Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Linear Motion Systems Ltd', 'Based in Lancashire, Linear Motion Systems Ltd designs, manufactures, and supplies engineering bearing solutions across a wide range of industries including automotive, nuclear, food production, and aerospace. Their product range covers linear modules, linear guides, ball screws, miniature linear sliders, rotary tables, direct drives, wire race bearings, and 3D-printed PEEK bearings. The company has a collective knowledge base of over 30 years in the engineering industry.', '{"company_type": "Linear Motion & Bearing Manufacturing", "website_url": "https://linearmotionsystems.co.uk", "location": "Lancashire, UK", "certifications": ["ISO 9001"], "capabilities": ["Linear Module Manufacture", "Ball Screw Supply", "Wire Race Bearing Manufacture", "3D Printed Bearing Manufacture", "Rotary Table Supply", "Custom Motion System Design"], "industries": ["Automotive", "Nuclear", "Aerospace", "Food Production", "Industrial Automation", "Machine Tools"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Steel", "Aluminium", "Carbon", "PEEK", "Ceramic", "PTFE"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Reliance Precision Ltd', 'Based at Rowley Mills, Huddersfield, West Yorkshire, Reliance Precision was incorporated in 1920 and is a world-leading precision engineering manufacturer producing motion control components for demanding applications including space, defence, and medical devices. The company''s product catalogue includes lead screw and nut assemblies, worm gearboxes, stepper motor gearboxes (NeoSMG), and precision machined components. Reliance holds ISO 9001, ISO 14001, and AS9100 certifications.', '{"company_type": "Precision Motion Component Manufacturing", "website_url": "https://www.reliance.co.uk", "location": "Huddersfield, West Yorkshire, UK", "certifications": ["ISO 9001", "ISO 14001", "AS9100"], "capabilities": ["Lead Screw and Nut Manufacture", "Worm Gearbox Manufacture", "Stepper Motor Gearbox Manufacture", "Precision CNC Machining", "Gear Manufacture"], "industries": ["Space", "Aerospace", "Defence", "Medical Devices", "Scientific Instruments", "Robotics"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1920, "materials": ["Chrome Steel", "Stainless Steel", "Titanium", "Aluminium", "Bronze"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Kugel Motion Ltd', 'Based in Derbyshire, Kugel Motion is the UK''s only specialist company operating a precision internal thread grinder specifically for ball nut re-grinding, specialising in the manufacture, repair, and overhaul of ball screws and linear motion products. The company also has a sister brand, Kugel Aerospace & Defence, focused on precision miniature ball screws for aerospace and defence applications. Their ball screws achieve accuracy grades of at least IT5 (23 microns per 300 mm), with IT3 and IT1 available.', '{"company_type": "Ball Screw Manufacturing & Repair", "website_url": "https://www.kugelmotion.co.uk", "location": "Derbyshire, UK", "certifications": ["AS9100"], "capabilities": ["Ball Screw Manufacture", "Ball Screw Repair and Regrinding", "Satellite Roller Screw Manufacture", "Ball Nut Manufacture", "CMM Inspection"], "industries": ["Aerospace", "Defence", "Automotive", "Machine Tools", "Medical", "Industrial Automation"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Chrome Steel", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Moore International Ltd', 'Established in 1997 in Poole, Dorset, Moore International is the UK''s leading distributor of Swiss-made Eichenberger Gewinde cold-rolled ball screws and leadscrews, and is a key distributor of Schneeberger precision linear motion products. The company also carries out CNC machining in-house at its Dorset facility. Moore International holds ISO 9001 certification and serves defence, automation, and medical instrumentation industries.', '{"company_type": "Ball Screw & Linear Motion Distribution", "website_url": "https://www.mooreinternational.co.uk", "location": "Poole, Dorset, UK", "certifications": ["ISO 9001"], "capabilities": ["Ball Screw Supply", "Lead Screw Supply", "Linear Guide Supply", "CNC Machining", "Custom Screw Specification"], "industries": ["Defence", "Medical Instrumentation", "Industrial Automation", "Machine Tools", "Aerospace"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1997, "materials": ["Chrome Steel", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ABSSAC Ltd', 'Based in Evesham, Worcestershire, and trading since 1982, ABSSAC is a specialist supplier of precision lead screws, ball screws, machined springs, hydraulic clamping hubs, and Schmidt flexible disc couplings for rotary and linear power transmission applications. The company has an in-house machine shop enabling swift delivery of bespoke leadscrew programmes and a 40-year track record in the aerospace sector. ABSSAC holds ISO 9001 certification.', '{"company_type": "Lead Screw & Power Transmission Component Supply", "website_url": "https://www.abssac.co.uk", "location": "Evesham, Worcestershire, UK", "certifications": ["ISO 9001"], "capabilities": ["Precision Lead Screw Supply", "Ball Screw Supply", "Hydraulic Clamping Hub Supply", "Flexible Coupling Supply", "Machined Spring Supply"], "industries": ["Aerospace", "Medical", "Robotics", "Industrial Automation", "Defence", "Machine Tools"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1982, "materials": ["Chrome Steel", "Stainless Steel", "PTFE", "Bronze"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Huco Engineering Industries Ltd (Regal Rexnord)', 'Huco Engineering Industries, located in Hertford, Hertfordshire, is a world-recognised manufacturer of precision couplings and piston air motors with over 40 years of innovation. The company manufactures a comprehensive range of precision coupling types including beam, Oldham, Uni-Lat, bellows, rigid, flexible membrane, jaw, and double-loop designs. Huco became part of Altra Industrial Motion and subsequently Regal Rexnord in 2023.', '{"company_type": "Precision Coupling Manufacturing", "website_url": "https://www.huco.com", "location": "Hertford, Hertfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Beam Coupling Manufacture", "Bellows Coupling Manufacture", "Oldham Coupling Manufacture", "Air Motor Manufacture", "Custom Coupling Engineering"], "industries": ["Food Processing", "Medical", "Packaging", "Machine Tools", "Robotics", "Servo Drive Systems"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Aluminium", "Stainless Steel", "Polyurethane", "Acetal"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'R.A. Rodriguez (UK) Ltd', 'Trading since 1968 and based in Letchworth, Hertfordshire, R.A. Rodriguez is a UK representative and specialist distributor for precision bearing brands including Kaydon (SKF Group), Rodriguez GmbH, TGB, and McGill. The company''s range encompasses thin-section bearings, slewing rings, slew drives, super-precision bearings, conveyor bearings, and aerospace bearings, all supplied to ISO 9001 and AS9120 standards. Rodriguez supports customers in defence, aerospace, and robotics with application engineering.', '{"company_type": "Precision Bearing Distribution & Engineering", "website_url": "https://www.rarodriguez.co.uk", "location": "Letchworth, Hertfordshire, UK", "certifications": ["ISO 9001", "AS9120"], "capabilities": ["Thin Section Bearing Supply", "Slewing Ring Supply", "Super Precision Bearing Supply", "Custom Bearing Engineering", "Aerospace Bearing Supply"], "industries": ["Aerospace", "Defence", "Robotics", "Renewable Energy", "Industrial Machinery", "Oil & Gas"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1968, "materials": ["Chrome Steel", "Stainless Steel", "Ceramic"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SMB Bearings Ltd', 'Located in Carterton, Oxfordshire, SMB Bearings is a specialist distributor and bearing relubrication service provider focusing on miniature, stainless steel, ceramic, and plastic bearings. The company has been the UK and Ireland agent for EZO (Sapporo Precision) bearings for over 30 years. SMB also offers bespoke bearing cleaning, degreasing, and relubrication services for food, medical, and corrosive-environment applications.', '{"company_type": "Specialist Bearing Distribution & Services", "website_url": "https://www.smbbearings.com", "location": "Carterton, Oxfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Miniature Bearing Supply", "Stainless Steel Bearing Supply", "Ceramic Bearing Supply", "Bearing Relubrication", "Bearing Degreasing"], "industries": ["Food & Beverage", "Medical", "Pharmaceutical", "Semiconductor", "Robotics", "Scientific Instruments"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Stainless Steel", "Ceramic", "PTFE", "Polymer"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Loadpoint Ltd', 'Loadpoint is a UK manufacturer of precision air bearing spindles and dicing machines based in Ferndown, Dorset (air bearings division) and Cricklade, Swindon, Wiltshire (dicing solutions). With a 60-year history, the company designs, engineers, and manufactures all products entirely in-house, serving global markets from semiconductor wafer dicing to micro-machining. Loadpoint air bearing spindles are used in semiconductor manufacturing, PCB drilling, and ultra-precision machining.', '{"company_type": "Air Bearing Spindle Manufacturing", "website_url": "https://www.loadpoint.co.uk", "location": "Ferndown, Dorset / Cricklade, Wiltshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Air Bearing Spindle Manufacture", "Precision Dicing Machine Manufacture", "Linear Air Bearing Slideway Manufacture", "Grinding Spindle Manufacture", "Bespoke Spindle Engineering"], "industries": ["Semiconductor", "Electronics", "Aerospace", "Micro-Machining", "Scientific Instruments"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Granite", "Aluminium", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Fenner Precision Polymers Ltd (Michelin Group)', 'Founded in Hull, East Yorkshire in 1861 by J.H. Fenner, Fenner Precision Polymers is a British manufacturer of industrial belting and polymer-based power transmission products now operating as part of the Michelin Group following acquisition in 2018. The company manufactures V-belts, polyurethane timing belts, keyless locking devices, and low-friction guides from its UK and global facilities. Products are used in manufacturing, food processing, packaging, and material handling applications.', '{"company_type": "Power Transmission Belt & Coupling Manufacturing", "website_url": "https://www.fenner.com", "location": "Hessle, East Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["V-Belt Manufacture", "Polyurethane Timing Belt Manufacture", "Keyless Locking Device Supply", "Low Friction Guide Manufacture"], "industries": ["Manufacturing", "Food Processing", "Packaging", "Material Handling", "Automotive"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1861, "materials": ["Polyurethane", "Kevlar", "Rubber", "Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Lubrication UK Ltd', 'Based in the UK, Lubrication UK is the national distributor of the Memolub automatic lubrication system range and has been supplying single-point and multi-point automatic lubricators for approximately three decades. The company serves industries where bearing maintenance is critical, including manufacturing, food processing, and heavy industry. Their lubricator products are designed to extend the service life of bearings, chains, and mechanical components by ensuring consistent lubrication.', '{"company_type": "Lubrication System Distribution", "website_url": "https://www.lubricationuk.com", "location": "UK", "certifications": [], "capabilities": ["Automatic Lubricator Supply", "Single Point Lubricator Supply", "Multi-Point Lubrication System Supply", "Bearing Lubrication Consultancy"], "industries": ["Manufacturing", "Food & Beverage", "Mining", "Heavy Industry", "Steel", "Paper"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Grease", "Oil"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Fenner Power Transmission (FPT Group) Ltd', 'FPT Group was established in 1998 to acquire and continue the Fenner Power Transmission product division and is headquartered in Kingswinford, West Midlands. Following acquisition by ERIKS Group, FPT Group continues to manufacture and distribute the Fenner brand of V-belts, wedge belts, timing belts, pulleys, taper lock bushes, couplings, and gearboxes. Products are sold through a global network and are used in demanding manufacturing and maintenance applications.', '{"company_type": "Power Transmission Component Manufacturing", "website_url": "https://fptgroup.com/en/", "location": "Kingswinford, West Midlands, UK", "certifications": ["ISO 9001"], "capabilities": ["V-Belt Manufacture", "Timing Belt Supply", "Taper Lock Bush Manufacture", "Coupling Supply", "Gearbox Supply"], "industries": ["Manufacturing", "Mining", "Agriculture", "Construction", "Food Processing", "Material Handling"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1998, "materials": ["Rubber", "Polyurethane", "Chrome Steel", "Cast Iron"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'The Bearing Specialists Ltd', 'Based in the UK, The Bearing Specialists is the European distributor for RBC Bearings Incorporated, supplying high-precision bearings including thin-section, spherical plain, rod-end, and aerospace-grade bearings. The company provides application engineering support for precision machinery, aerospace structures, and industrial applications requiring high accuracy and rigidity. Products span a wide range of sizes and configurations including metric and inch series.', '{"company_type": "Precision Bearing Distribution & Engineering", "website_url": "https://thebearingspecialists.co.uk", "location": "UK", "certifications": ["ISO 9001", "AS9120"], "capabilities": ["Precision Bearing Supply", "Spherical Plain Bearing Supply", "Rod-End Bearing Supply", "Aerospace Bearing Supply", "Application Engineering"], "industries": ["Aerospace", "Defence", "Machine Tools", "Automotive", "Industrial Machinery"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Chrome Steel", "Stainless Steel", "Ceramic", "PTFE"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Norbar Torque Tools Ltd', 'Founded in Banbury, Oxfordshire, Norbar is the UK''s leading manufacturer of torque tightening, measuring, and calibration tools, and was the first UK torque tool manufacturer to receive NAMAS laboratory accreditation in 1989. Though not a bearing manufacturer per se, Norbar''s torque control tools and multipliers are integral to the assembly and maintenance of precision bearing systems across aerospace, oil and gas, automotive, and industrial sectors. The company exports globally from its Banbury facility.', '{"company_type": "Precision Assembly Tool Manufacturing", "website_url": "https://www.norbar.com", "location": "Banbury, Oxfordshire, UK", "certifications": ["ISO 9001", "UKAS Accreditation"], "capabilities": ["Torque Wrench Manufacture", "Torque Multiplier Manufacture", "Torque Calibration", "Electronic Torque Tool Manufacture"], "industries": ["Aerospace", "Oil & Gas", "Automotive", "Power Generation", "Rail", "Wind Energy"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Chrome Vanadium Steel", "Aluminium", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Fenner Drives (Regal Rexnord) – Leeds Facility', 'Fenner Drives, part of Regal Rexnord Corporation since 2023, operates a manufacturing facility in Leeds, West Yorkshire and is a world-class manufacturer of twist-link belting, extruded polymer belting, and HRC couplings for power transmission. Products are used globally in food processing, energy, textiles, medical, and packaging industries. Fenner Drives is known for its unique twist-link belt and custom polymer drive solutions.', '{"company_type": "Power Transmission Component Manufacturing", "website_url": "https://www.fenner.com/brands/fenner-drives", "location": "Leeds, West Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Twist-Link Belt Manufacture", "HRC Coupling Manufacture", "Tyre Coupling Manufacture", "Polyurethane Drive Belt Manufacture"], "industries": ["Food Processing", "Packaging", "Medical", "Energy", "Textiles", "Material Handling"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1861, "materials": ["Polyurethane", "Rubber", "Hytrel", "Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


