INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Fabdec Ltd (BRITANX Process)', 'Fabdec manufactures premium stainless steel process vessels under the BRITANX brand from a 65,000 sq ft facility in Whitchurch, Shropshire. With over 60 years of manufacturing experience, the company supplies hygienic process vessels, pressure vessels, and thermal transfer vessels for the pharmaceutical, food and beverage, cosmetics, and chemical industries. All vessels are ISO 9001 certified and comply with BS EN 13445 pressure vessel standards.', '{"company_type": "Process Vessel Manufacturing", "website_url": "https://fabdec.com", "location": "Whitchurch, Shropshire, UK", "certifications": ["ISO 9001", "BS EN 13445", "PED"], "capabilities": ["Pressure Vessel Design", "Hygienic Vessel Manufacture", "Thermal Transfer Vessels", "Jacketed Vessels", "Storage Tanks", "Custom Fabrication"], "industries": ["Pharmaceutical", "Food & Beverage", "Cosmetics", "Chemical"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1962, "materials": ["316L Stainless Steel", "304 Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Stekko Company Ltd', 'Stekko is a UK manufacturer of bespoke stainless steel pressure vessels, process equipment, storage vessels, and tanks based in Stokenchurch, Buckinghamshire. Established in 1991, the company serves the pharmaceutical, biotech, food, process, and architectural sectors. Stekko is BS EN ISO 9001 compliant and specialises in custom-built equipment to exact client specifications.', '{"company_type": "Process Vessel Manufacturing", "website_url": "https://www.stekko.co.uk", "location": "Stokenchurch, Buckinghamshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Pressure Vessel Manufacture", "Process Vessel Fabrication", "Storage Tanks", "Bespoke Stainless Steel Fabrication", "General Fabrication"], "industries": ["Pharmaceutical", "Biotechnology", "Food & Beverage", "Process"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1991, "materials": ["316L Stainless Steel", "304 Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Gilwood Ltd', 'Gilwood is a specialist pressure vessel and mechanical systems manufacturer based in Heywood, Greater Manchester, with over 60 years of engineering heritage. The company designs and manufactures bespoke stainless steel pressure vessels for the food, beverage, pharmaceutical, and chemical industries from its purpose-built factory. All vessels are PED compliant, and welders are certified to ASME IX and BS EN 287/288 standards.', '{"company_type": "Process Vessel Manufacturing", "website_url": "https://www.gilwood.co.uk", "location": "Heywood, Greater Manchester, UK", "certifications": ["ISO 9001", "PED", "ASME IX"], "capabilities": ["Pressure Vessel Manufacture", "Bespoke Stainless Fabrication", "Laser Cutting", "Certified Welding", "Custom Process Vessels"], "industries": ["Pharmaceutical", "Food & Beverage", "Chemical", "Beverage"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["316L Stainless Steel", "304 Stainless Steel", "Carbon Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Suncombe Ltd', 'Founded in 1961, Suncombe designs and manufactures critical automatic processing systems for the pharmaceutical, biotechnology, and research sectors from their facility in Bishop''s Stortford, Hertfordshire. The company specialises in CIP (Clean-in-Place) systems, biowaste effluent treatment, GMP washers, GMP vessels, and sterile liquid processing skids. Trusted by 17 of the top 20 biopharma companies worldwide, Suncombe designs to CE, cGMP, ASME BPE, EHEDG, and GAMP standards.', '{"company_type": "Pharma Equipment / CIP Systems", "website_url": "https://suncombe.com", "location": "Bishop''s Stortford, Hertfordshire, UK", "certifications": ["ISO 9001", "CE", "ASME BPE", "EHEDG", "GAMP", "UKCA"], "capabilities": ["CIP System Design & Manufacture", "GMP Vessel Manufacture", "Biowaste Effluent Treatment", "GMP Washers", "Sterile Liquid Processing Skids", "SIP Systems"], "industries": ["Pharmaceutical", "Biotechnology", "Biopharmaceutical", "Research"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1961, "materials": ["316L Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Adelphi Group of Companies', 'The Adelphi Group is a UK manufacturer of pharmaceutical packaging machinery and stainless steel vessels, headquartered in Haywards Heath, West Sussex, incorporated in 1947. The group includes Adelphi Manufacturing (filling and capping machinery) and Coldstream Engineering (stainless steel vessels and holloware). The group is ISO 9001:2015 certified and serves the pharmaceutical, cosmetics, food, and chemical industries.', '{"company_type": "Pharma Equipment / Process Vessel Manufacturing", "website_url": "https://www.adelphi.uk.com", "location": "Haywards Heath, West Sussex, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Filling & Capping Machinery", "Stainless Steel Vessel Manufacture", "Mixing Vessels", "Pressure Vessels", "Holloware", "Capsule Filling"], "industries": ["Pharmaceutical", "Cosmetics", "Food & Beverage", "Chemical"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1947, "materials": ["316L Stainless Steel", "304 Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
