INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Orbital Fabrications Ltd', 'Orbital Fabrications is a leading designer, manufacturer, and installer of high-purity gas and fluid handling equipment for the pharmaceutical, biopharmaceutical, and medical industries, based in St Ives, Cambridgeshire. The company has over 35 years of experience in orbital TIG welding of stainless steel, Hastelloy, Inconel, and Monel, operating from a 37,000 sq ft manufacturing facility with a 6,000 sq ft clean room for high-purity fabrication. Full weld NDT, leak testing, and 3.1 material certification are provided.', '{"company_type": "Pharmaceutical Process Equipment / High-Purity Fabrication", "website_url": "https://www.orbitalfabrications.co.uk", "location": "St Ives, Cambridgeshire, UK", "certifications": ["ISO 9001", "CHAS"], "capabilities": ["Orbital TIG Welding", "High-Purity Pipework", "Process Vessel Fabrication", "On-site Installation", "Leak Testing", "NDT", "Clean Room Fabrication"], "industries": ["Pharmaceutical", "Biopharmaceutical", "Medical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["316L Stainless Steel", "Hastelloy", "Inconel", "Monel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Studley Ltd', 'Founded in Liverpool over 40 years ago, Studley is a mechanical, electrical, and instrumentation contractor operating from a 60,000 sq ft workshop in Knowsley, Merseyside, with a 250-strong workforce. The company fabricates and installs bespoke tanks and pressure vessels in stainless and carbon steel for the pharmaceutical, food, petrochemical, and chemical industries. Quality systems are certified to ISO 9001 with PED compliance (modules D, DI, and EI Annex III) and welding procedures to BS EN ISO 15614-1 and ASME IX.', '{"company_type": "Process Vessel Manufacturing / Mechanical & Electrical Contractor", "website_url": "https://studleyltd.com", "location": "Knowsley, Merseyside, UK", "certifications": ["ISO 9001", "PED", "ASME IX", "BS EN ISO 15614-1"], "capabilities": ["Tank & Pressure Vessel Fabrication", "High-Integrity Pipework", "Modular Skid Build", "On-site Installation", "Hygienic Welding"], "industries": ["Pharmaceutical", "Food & Beverage", "Chemical", "Petrochemical", "Nuclear", "Energy"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1983, "materials": ["316L Stainless Steel", "304 Stainless Steel", "Carbon Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Langfields Ltd', 'Langfields is a Salford-based specialist with a manufacturing history stretching back to the 1800s and over 100 years of pressure vessel design and fabrication experience. The company designs and manufactures process skids and pressure vessels in stainless, duplex, and carbon steels for the pharmaceutical, chemical, offshore, oil and gas, marine, defence, and nuclear sectors. With facilities across Salford, Dunfermline, Tamworth, Warrington, and Deephaven, the company applies Level 3 NDT inspection and qualifies welding procedures to the most stringent industry codes.', '{"company_type": "Process Skid Builder / Pressure Vessel Manufacturing", "website_url": "https://www.langfields.com", "location": "Salford, Greater Manchester, UK", "certifications": ["ISO 9001", "PED", "ASME"], "capabilities": ["Process Skid Design & Manufacture", "Pressure Vessel Fabrication", "NDT Inspection", "Specialist Welding", "Modular Systems"], "industries": ["Pharmaceutical", "Chemical", "Oil & Gas", "Marine", "Nuclear", "Defence"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["316L Stainless Steel", "Duplex Stainless Steel", "Carbon Steel", "Hastelloy"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Puretech Systems Limited', 'Puretech Systems has served the pharmaceutical, healthcare, and process industries since 1988 and specialises in the design, installation, and maintenance of pharmaceutical-grade water and steam systems, including WFI generation, purified water, pure steam generation, storage and distribution skids, and medical gas systems. Headquartered in Redhill, Surrey with a manufacturing facility in London and a regional office in the North East, the company operates under cGMP validation frameworks.', '{"company_type": "Pharma Equipment / Process Skid Builder", "website_url": "https://puretech.uk.com", "location": "Redhill, Surrey, UK", "certifications": ["ISO 9001", "cGMP"], "capabilities": ["WFI System Design & Build", "Pure Steam Generation", "Purified Water Systems", "Medical Gas Systems", "Skid Manufacture", "Validation Support"], "industries": ["Pharmaceutical", "Biotechnology", "Healthcare"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1988, "materials": ["316L Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Watson-Marlow Fluid Technology Solutions (Flexicon)', 'Watson-Marlow, headquartered in Falmouth, Cornwall and founded in 1956, is a world leader in peristaltic pumps and fluid path technologies for pharmaceutical and biotech applications, operating as a Spirax Group business. The Flexicon brand within the group manufactures aseptic liquid filling and capping systems for pharmaceutical vials, syringes, and bottles. With over 1,960 employees globally and 47 operating units, Watson-Marlow serves pharmaceutical, biotech, food, and industrial sectors.', '{"company_type": "Pharma Equipment / Liquid Filling Systems", "website_url": "https://www.wmfts.com", "location": "Falmouth, Cornwall, UK", "certifications": ["ISO 9001", "cGMP", "21 CFR Part 11"], "capabilities": ["Peristaltic Pump Manufacture", "Aseptic Liquid Filling", "Capping Systems", "Single-Use Fluid Path", "Bioprocessing Equipment"], "industries": ["Pharmaceutical", "Biotechnology", "Biopharmaceutical", "Food & Beverage", "Industrial"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1956, "materials": ["316L Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Biopharma Process Systems Ltd', 'Biopharma Process Systems, part of Biopharma Group, has been a specialist in lyophilisation and bioprocessing equipment since 1989, based in Winchester, Hampshire. The company is the exclusive UK and Ireland distributor of Gellert industrial freeze dryers and maintains an installed base of over 400 freeze dryers. In addition to equipment supply and maintenance, the group offers CDMO services including GMP freeze-drying, formulation development, and lyophilisation cycle development.', '{"company_type": "Lyophiliser / Pharma Equipment", "website_url": "https://biopharma.co.uk", "location": "Winchester, Hampshire, UK", "certifications": ["ISO 9001", "GMP"], "capabilities": ["Freeze Dryer Supply & Maintenance", "Lyophilisation Cycle Development", "Bioreactor Supply", "Contract Freeze-Drying", "Formulation Development", "Validation Support"], "industries": ["Pharmaceutical", "Biotechnology", "Food & Beverage"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1989, "materials": ["316L Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Teknomek Ltd', 'Founded in 1987 and based in Norwich, Norfolk, Teknomek is the UK''s leading manufacturer of hygienic stainless steel furniture and equipment for cleanrooms, pharmaceutical manufacturing, laboratories, food processing, and healthcare environments. With over 35 years of expertise and a 47-person team, the company designs and manufactures non-particle-shedding furniture compliant with ISO 14644 and GMP requirements. All products are manufactured in-house at their Norwich facility in 304 or 316 grade stainless steel.', '{"company_type": "Clean Room Equipment / Hygienic Stainless Steel Furniture", "website_url": "https://teknomek.co.uk", "location": "Norwich, Norfolk, UK", "certifications": ["ISO 9001", "ISO 14644"], "capabilities": ["Cleanroom Furniture Manufacture", "Hygienic Workbenches", "Stainless Steel Shelving", "Custom Fabrication", "GMP-Compliant Equipment"], "industries": ["Pharmaceutical", "Food & Beverage", "Healthcare", "Biotechnology", "Laboratory"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1987, "materials": ["316L Stainless Steel", "304 Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SYSPAL Ltd', 'SYSPAL is a UK manufacturer of stainless steel and aluminium production furniture based in Broseley, Shropshire, with over 40 years of manufacturing experience. The company specialises in cleanroom-grade furniture, hygienic workstations, sinks, washroom equipment, and chemical storage solutions for the pharmaceutical, medical, cleanroom, food processing, and mortuary industries. All products are manufactured to ISO 9001 and British Standards quality marks.', '{"company_type": "Clean Room Equipment / Hygienic Stainless Steel Furniture", "website_url": "https://www.syspal.com", "location": "Broseley, Shropshire, UK", "certifications": ["ISO 9001", "British Standards"], "capabilities": ["Cleanroom Furniture Manufacture", "Hygienic Workstations", "Stainless Steel Sinks", "Chemical Storage", "Custom Stainless Fabrication"], "industries": ["Pharmaceutical", "Medical", "Food & Beverage", "Cleanroom"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["316L Stainless Steel", "304 Stainless Steel", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Clean Room Equipment Ltd', 'Clean Room Equipment Ltd is a UK manufacturer of bespoke stainless steel cleanroom furniture and equipment based in Burnley, Lancashire, with over 50 years of combined workforce experience in the cleanroom sector. The company designs, fabricates, and assembles stainless steel cleanroom products entirely in-house and supplies to pharmaceutical manufacturers, laboratories, and hospitals across the UK. Their skilled team of sheet metal fabricators, welders, and CNC operators handle all aspects of fabrication including framework structures.', '{"company_type": "Clean Room Equipment", "website_url": "https://www.clean-room-equipment.co.uk", "location": "Burnley, Lancashire, UK", "certifications": ["ISO 9001"], "capabilities": ["Cleanroom Furniture Manufacture", "Sheet Metal Fabrication", "CNC Operation", "Bespoke Stainless Fabrication", "Maintenance Contracts"], "industries": ["Pharmaceutical", "Medical", "Laboratory", "Healthcare"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["316L Stainless Steel", "304 Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sepha Ltd', 'Established in 1980, Sepha is a Belfast-based specialist engineering company that designs and manufactures pharmaceutical packaging integrity testing equipment and blister packaging solutions. The company produces non-destructive leak testing systems for blister packs, vials, ampoules, and sachets compliant with ASTM F2338, USP 1207, and 21 CFR Part 11. Sepha is currently constructing a new 21,000 sq ft purpose-built headquarters in Dundonald, Belfast.', '{"company_type": "Pharmaceutical Packaging Machinery", "website_url": "https://sepha.com", "location": "Dundonald, Belfast, Northern Ireland, UK", "certifications": ["ISO 9001", "21 CFR Part 11", "ASTM F2338"], "capabilities": ["Blister Packaging Equipment", "Non-Destructive Leak Testing", "Packaging Integrity Testing", "Deblistering Equipment", "Clinical Trial Packaging"], "industries": ["Pharmaceutical", "Medical Devices", "Healthcare"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1980, "materials": ["316L Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'IMA Swiftpack Ltd', 'IMA Swiftpack, founded in 1985 and acquired by Italian pharma machinery group IMA in 2004, is based in Alcester, Warwickshire and manufactures electronic tablet and capsule counting and bottle filling equipment for the pharmaceutical and healthcare industry. The company is the worldwide leader in tablet and capsule counting technology, supplying high-accuracy systems to major pharmaceutical manufacturers including Wasdell. Products comply with pharmaceutical GMP requirements and are exported globally.', '{"company_type": "Pharmaceutical Packaging Machinery", "website_url": "https://ima.it/pharma/brands/ima-safe", "location": "Alcester, Warwickshire, UK", "certifications": ["ISO 9001", "GMP", "CE"], "capabilities": ["Tablet Counting Equipment", "Capsule Counting Equipment", "Bottle Filling Systems", "Capping Machines", "Pharmaceutical Packaging Lines"], "industries": ["Pharmaceutical", "Healthcare", "Nutraceuticals"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1985, "materials": ["316L Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Hosokawa Micron Ltd', 'Hosokawa Micron Ltd is the UK subsidiary of the global Hosokawa Micron Group, based in Runcorn, Cheshire, and formed in 1989 through the merger of Alpine Process Technology and Hosokawa Mikropul. From their Runcorn facility, the company designs and manufactures powder and particle processing equipment, high-containment isolators and glove boxes, hygienic filling and weighing systems, and size reduction equipment for the pharmaceutical, food, and chemical industries. The group holds ISO 9001 and ISO 14001 certifications.', '{"company_type": "Pharmaceutical Process Equipment / Containment Equipment", "website_url": "https://www.hosokawa.co.uk", "location": "Runcorn, Cheshire, UK", "certifications": ["ISO 9001", "ISO 14001", "ATEX"], "capabilities": ["High-Containment Isolators", "Gloveboxes", "Powder Processing Equipment", "Hygienic Filling & Weighing", "Size Reduction Equipment", "Downflow Booths"], "industries": ["Pharmaceutical", "Food & Beverage", "Chemical", "Biotechnology"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1989, "materials": ["316L Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Onfab Ltd', 'Founded in 2004 and based in Middlewich, Cheshire, Onfab is a specialist designer and manufacturer of flexible containment isolators for pharmaceutical manufacturing, particularly for handling high-potency APIs (HPAPIs) and potent powders. The company manufactures flexible process isolators, weighing and dispensing isolators, and standalone isolators achieving containment performance typically below 30 ng/m3. Onfab is ISO 9001 certified and GMP and ATEX compliant, and is now part of the Savillex group.', '{"company_type": "Pharma Equipment / Containment Equipment", "website_url": "https://onfab.co.uk", "location": "Middlewich, Cheshire, UK", "certifications": ["ISO 9001", "GMP", "ATEX"], "capabilities": ["Flexible Containment Isolators", "HPAPI Containment", "Weighing & Dispensing Isolators", "Process Isolators", "Single-Use Containment"], "industries": ["Pharmaceutical", "Biopharmaceutical", "Chemical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2004, "materials": ["Flexible Film", "316L Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Dairy Pipe Lines Ltd (DPL UK)', 'Dairy Pipe Lines Ltd, founded in 1890 and based in Dudley, West Midlands, is the UK''s largest manufacturer and distributor of hygienic stainless steel tubes, valves, and fittings for the food, pharmaceutical, dairy, brewing, and cosmetics industries. The company operates a Midlands manufacturing site producing bespoke high-purity fabrications including borescoped and NDT-tested assemblies to ISO 9001:2015, and to welding standards ISO EN 1418, EN 287-1, and ASME IX.', '{"company_type": "Hygienic Stainless Steel Fabrication / Components", "website_url": "https://www.dpluk.co.uk", "location": "Dudley, West Midlands, UK", "certifications": ["ISO 9001:2015", "ASME IX", "EN 287-1"], "capabilities": ["Hygienic Tube Manufacture", "Valve & Fitting Distribution", "High-Purity Fabrications", "Orbital Welding", "NDT Testing", "Borescope Inspection"], "industries": ["Pharmaceutical", "Dairy", "Food & Beverage", "Brewing", "Cosmetics"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1890, "materials": ["316L Stainless Steel", "304 Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SWS Engineering Ltd (Southwest Stainless)', 'SWS Engineering is a Westbury, Wiltshire-based specialist in hygienic stainless steel fabrication serving the pharmaceutical, life science, food processing, medical, and aerospace sectors. The company provides on-site and off-site fabrication of pharmaceutical process equipment, pipework, and custom components, with welding procedures approved to ASME IX, BS EN ISO 9606-1:2017, and manufacturing to ASME BPE and PED standards. The team specialises in orbital welding and high-purity stainless systems.', '{"company_type": "Hygienic Stainless Steel Fabrication / Pharma Equipment", "website_url": "https://southwest-stainless.co.uk", "location": "Westbury, Wiltshire, UK", "certifications": ["ISO 9001", "PED", "ASME IX", "ASME BPE", "ATEX", "Safe Contractor"], "capabilities": ["Orbital Welding", "Hygienic Fabrications", "Pharmaceutical Pipework", "On-site & Off-site Fabrication", "High-Purity Systems"], "industries": ["Pharmaceutical", "Life Sciences", "Food & Beverage", "Medical", "Aerospace"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["316L Stainless Steel", "304 Stainless Steel", "Duplex Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'C H Barnett Fabrications Ltd', 'C H Barnett is a Birmingham-based stainless steel fabrication company established in 1948, with over 65 years of experience producing high-accuracy contact parts for the pharmaceutical and medical industries. Operating from Tyseley Industrial Estate, the company manufactures bespoke pharmaceutical fabrications, food-grade stainless components, and custom assemblies certified to BS EN ISO 9001:2015 with strict material traceability. Products meet stringent hygienic and safety guidelines for pharmaceutical and medical applications.', '{"company_type": "Stainless Steel Fabrication / Pharmaceutical Components", "website_url": "https://chbarnett.co.uk", "location": "Birmingham, West Midlands, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Pharmaceutical Stainless Fabrication", "Medical Grade Fabrication", "Bespoke Component Manufacture", "Sheet Metal Fabrication", "Material Traceability"], "industries": ["Pharmaceutical", "Medical", "Food & Beverage"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1948, "materials": ["316L Stainless Steel", "304 Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'G&S Stainless Services NI Ltd', 'G&S Stainless Services is a Northern Ireland-based stainless steel fabricator and vessel manufacturer established in 2001, operating from Newry with a specialisation in pipework installations and vessel manufacture for the pharmaceutical, chemical, food and dairy, oil and gas, and brewing industries. The company holds ISO 9001, ISO 45001, and EN 1090 Execution Class 3 certifications, with all welders coded to Pressure Equipment Directive standards for both workshop and on-site projects.', '{"company_type": "Process Vessel Manufacturing / Stainless Steel Fabrication", "website_url": "https://stainless-tanks.co.uk", "location": "Newry, Northern Ireland, UK", "certifications": ["ISO 9001", "ISO 45001", "EN 1090 Exec Class 3", "PED"], "capabilities": ["Vessel Manufacture", "Pipework Installation", "On-site Fabrication", "Workshop Fabrication", "Custom Stainless Tanks"], "industries": ["Pharmaceutical", "Chemical", "Food & Beverage", "Oil & Gas", "Brewing"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2001, "materials": ["316L Stainless Steel", "304 Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HpE Process Ltd', 'HpE Process Ltd, based in Gildersome, West Yorkshire, is a UK distributor and specialist fabricator of hygienic stainless steel process equipment with over 25 years of experience serving the pharmaceutical, food and beverage, dairy, and cosmetics industries. The company stocks hygienic tubes, valves, fittings, pumps, mixers, tank equipment, and product recovery systems, and carries out bespoke stainless steel fabrications from its Leeds facility. HpE Process supplies components meeting national and international hygienic standards.', '{"company_type": "Hygienic Process Equipment / Components Distribution & Fabrication", "website_url": "https://www.hpeprocess.com", "location": "Gildersome, Leeds, West Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Hygienic Stainless Fabrication", "Pump & Valve Supply", "Tube & Fitting Distribution", "Tank Equipment", "Product Recovery Systems", "Mixer Supply"], "industries": ["Pharmaceutical", "Food & Beverage", "Dairy", "Cosmetics"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["316L Stainless Steel", "304 Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Hartwell Manufacturing Ltd', 'Hartwell Manufacturing is a privately owned UK fabricator providing pressure vessel and custom stainless steel fabrication services since 1974, specialising in process vessels for the pharmaceutical, food, petrochemical, and chemical sectors. The company manufactures entirely bespoke vessels from 20 litres to 200,000 litres capacity to PD5500 and ASME VIII design codes, offering a wide range of steel grades, finishes, heating methods, and agitator options. PED compliance is standard for European pressure applications.', '{"company_type": "Process Vessel Manufacturing", "website_url": "https://hartwellmanufacturing.co.uk", "location": "UK", "certifications": ["ISO 9001", "PED", "PD5500", "ASME VIII"], "capabilities": ["Bespoke Pressure Vessel Manufacture", "Agitated Vessels", "Jacketed Vessels", "Custom Stainless Fabrication", "Large-Volume Vessel Manufacture"], "industries": ["Pharmaceutical", "Food & Beverage", "Chemical", "Petrochemical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1974, "materials": ["316L Stainless Steel", "304 Stainless Steel", "Carbon Steel", "Duplex Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


