INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Watson-Marlow Fluid Technology Solutions', 'Watson-Marlow, based in Falmouth, Cornwall and a subsidiary of Spirax Group, is the world''s leading manufacturer of peristaltic and sinusoidal pumps, founded in 1956. The company specialises in fluid path technologies for the life sciences, pharmaceutical, and process industries, including single-use fluid management systems and precision tubing. It has over 1,960 employees across 47 operating units worldwide.', '{"company_type": "Pump Manufacturing", "website_url": "https://www.wmfts.com", "location": "Falmouth, Cornwall, UK", "certifications": ["ISO 9001", "FDA", "USP Class VI", "ISO 14644"], "capabilities": ["Peristaltic Pump Manufacture", "Sinusoidal Pump Design", "Single-Use Fluid Path Systems", "Precision Tubing Manufacture", "Filling Machine Engineering"], "industries": ["Pharmaceutical", "Biopharmaceutical", "Food & Beverage", "Chemical", "Water Treatment"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1956, "materials": ["Stainless Steel", "PTFE", "Silicone", "Peristaltic Tubing Polymers"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Spirax Sarco Ltd', 'Spirax Sarco, headquartered in Cheltenham and part of the FTSE 100 Spirax Group, has manufactured steam management products since 1932 and traces its founding to 1888. The company produces steam traps, control valves, pressure regulators, and heat exchangers for the control of steam, hot water, and compressed air in process and commercial applications. It employs over 8,000 people globally with significant UK manufacturing operations.', '{"company_type": "Valve Manufacturing", "website_url": "https://www.spiraxsarco.com", "location": "Cheltenham, Gloucestershire, UK", "certifications": ["ISO 9001", "PED", "CE Marking", "ATEX"], "capabilities": ["Steam Trap Manufacture", "Control Valve Design", "Pressure Regulator Manufacture", "Heat Exchanger Engineering", "Steam System Design"], "industries": ["Pharmaceutical", "Food & Beverage", "Chemical", "Oil & Gas", "Power Generation"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1888, "materials": ["Stainless Steel", "Cast Iron", "Bronze", "Duplex"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oliver Valves Ltd', 'Oliver Valves, established in 1979 and based in Knutsford, Cheshire, is a world leader in instrumentation, subsea, and pipeline valve design and manufacture, employing 350 people on site. The company serves the global oil & gas industry with over 8,000 valve types and has installed over 70,000 valves and 12,000 subsea valves across 60 countries. The group includes Oliver Valvetek for subsea applications and Oliver Hydcovalves for hydrogen and carbon capture markets.', '{"company_type": "Valve Manufacturing", "website_url": "https://www.valves.co.uk", "location": "Knutsford, Cheshire, UK", "certifications": ["ISO 9001", "API Q1", "API 6A", "PED", "ATEX"], "capabilities": ["Instrumentation Valve Manufacture", "Subsea Valve Design", "Pipeline Valve Engineering", "Ball Valve Manufacture", "Needle Valve Manufacture"], "industries": ["Oil & Gas", "Subsea", "Offshore", "Hydrogen", "Carbon Capture"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1979, "materials": ["Stainless Steel", "Duplex", "Super Duplex", "Inconel", "Titanium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'BEL Valves', 'BEL Valves, part of the British Engines Group and established in Newcastle-upon-Tyne in 1964, designs and manufactures high-integrity valves, actuators, and controls for subsea, surface, and onshore oil & gas applications. The company has installed over 70,000 valves and 12,000 valves subsea in more than 60 countries, and was the first to produce subsea electric actuators for the North Sea. Its manufacturing facility remains in Newcastle, producing bespoke high-pressure and high-temperature valve solutions.', '{"company_type": "Valve Manufacturing", "website_url": "https://www.belvalves.com", "location": "Newcastle upon Tyne, Tyne and Wear, UK", "certifications": ["ISO 9001", "PED", "ATEX", "DNV", "Lloyd''s Register", "API"], "capabilities": ["High-Pressure Valve Manufacture", "Subsea Valve Design", "Actuator Engineering", "Gate Valve Manufacture", "Bespoke Valve Fabrication"], "industries": ["Oil & Gas", "Subsea", "Offshore", "Petrochemical"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1964, "materials": ["Stainless Steel", "Duplex", "Super Duplex", "Inconel", "Carbon Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Severn Glocon UK Valves Ltd', 'Severn Glocon, headquartered in Gloucester and established in 1961, is a global specialist in the design and manufacture of severe service control, choke, and butterfly valves for the oil & gas, LNG, and power industries. With 286 employees and facilities in the UK, Middle East, USA, India, and Australia, the company has been recognised with a Queen''s Award for Enterprise in International Trade. Products are certified to API, ISO, and SIL standards and serve some of the most demanding process conditions worldwide.', '{"company_type": "Valve Manufacturing", "website_url": "https://www.severnvalve.com", "location": "Gloucester, Gloucestershire, UK", "certifications": ["ISO 9001", "ISO 14001", "ISO 45001", "API Q1", "API 6A", "PED", "ATEX", "SIL", "CE Marking"], "capabilities": ["Severe Service Control Valve Design", "Choke Valve Manufacture", "Butterfly Valve Engineering", "Subsea Valve Manufacture", "Actuator Assembly"], "industries": ["Oil & Gas", "LNG/NGL", "Power Generation", "Chemical", "Offshore"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1961, "materials": ["Stainless Steel", "Duplex", "Super Duplex", "Tungsten Carbide", "Alloy Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Kinetrol Ltd', 'Kinetrol is a privately-owned British company founded in 1958 and based across three sites in Farnham, Surrey, manufacturing pneumatic rotary quarter-turn actuators, spring-return mechanisms, and associated valve control equipment. The company employs 201–500 people and exports approximately 80% of production to international markets including North America, China, and the Middle East. Its actuators are used in automation, water, oil & gas, power, and industrial automation applications.', '{"company_type": "Actuator Manufacturing", "website_url": "https://www.kinetrol.com", "location": "Farnham, Surrey, UK", "certifications": ["ISO 9001", "ATEX"], "capabilities": ["Pneumatic Rotary Actuator Manufacture", "Spring-Return Actuator Design", "Positioner Manufacture", "Limit Switch Box Assembly", "Valve Automation Packages"], "industries": ["Oil & Gas", "Water Treatment", "Power Generation", "Chemical", "Industrial Automation"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1958, "materials": ["Aluminium", "Stainless Steel", "Ductile Iron"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Seetru Limited', 'Seetru is a Bristol-based manufacturer of safety relief valves and liquid level gauges founded in 1949, serving compressed air, industrial gas, steam, liquid, and liquefied gas applications. The company holds extensive international approvals including ASME/NB (UV), TÜV, DNV, ABS, Lloyd''s Register, and WRAS, making its products suitable for marine, offshore, and process industries. Products are UKCA marked, CE marked, and compliant with PED and ISO 4126.', '{"company_type": "Safety Valve Manufacturing", "website_url": "https://www.seetru.com", "location": "Bristol, Bristol, UK", "certifications": ["ISO 9001", "PED", "ASME/NB (UV)", "TÜV", "DNV", "Lloyd''s Register", "ABS", "WRAS", "UKCA"], "capabilities": ["Safety Relief Valve Manufacture", "Pressure Relief Valve Design", "Level Gauge Manufacture", "Valve Testing", "Custom Safety Valve Engineering"], "industries": ["Oil & Gas", "Marine", "Chemical", "Water Treatment", "Power Generation"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1949, "materials": ["Bronze", "Stainless Steel", "Cast Iron", "PTFE"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Gresswell Valves', 'Gresswell Valves, established in Birmingham in the early 1930s and now based in Telford, Shropshire, is a specialist manufacturer of safety relief valves and pressure relief valves for the boiler, process, oil and gas, shipping, and pump protection sectors. The company has emerged as a market leader with a worldwide distributor network and has PED Category IV certification and CE marking across its full valve range. In 2010, it expanded its range by acquiring Empire Engineering.', '{"company_type": "Safety Valve Manufacturing", "website_url": "https://gresswellvalves.com", "location": "Telford, Shropshire, UK", "certifications": ["PED Cat IV", "CE Marking"], "capabilities": ["Safety Relief Valve Manufacture", "Pressure Relief Valve Design", "Boiler Safety Valve Supply", "Pump Protection Valve Engineering"], "industries": ["Oil & Gas", "Marine", "Chemical", "Water Treatment", "Boiler & Steam"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1930, "materials": ["Bronze", "Stainless Steel", "Cast Iron"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Brooksbank Valves Ltd', 'Brooksbank Valves is an independent, family-owned UK manufacturer of isolation valves established in 1953 at Cross Hills, West Yorkshire, originally to supply the Royal Navy with high-quality valve solutions. The company manufactures ball valves, gate valves, globe valves, check valves, and butterfly valves in both standard and exotic materials, with the quality management system certified to ISO 9001:2015 by DNV since 1986. Products comply with PED, Lloyd''s Register, and relevant ISO and API standards.', '{"company_type": "Valve Manufacturing", "website_url": "https://www.brooksbank.co.uk", "location": "Cross Hills, West Yorkshire, UK", "certifications": ["ISO 9001", "PED", "DNV", "Lloyd''s Register"], "capabilities": ["Ball Valve Manufacture", "Gate Valve Manufacture", "Globe Valve Manufacture", "Check Valve Manufacture", "Butterfly Valve Manufacture", "Naval Marine Valve Supply"], "industries": ["Marine", "Naval", "Oil & Gas", "Chemical", "Water Treatment"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1953, "materials": ["Stainless Steel", "Duplex", "Super Duplex", "Bronze", "Gunmetal", "Monel", "Hastelloy", "Titanium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'IMI Process Automation', 'IMI Process Automation is the process valve and actuator division of IMI plc, a global fluid and motion control group headquartered in Birmingham since 1862. The division engineers bespoke control valves, actuators, and integrated automation packages for critical process industries including pharmaceutical, chemical, and food & beverage. IMI plc employs over 10,000 people worldwide and is listed on the London Stock Exchange.', '{"company_type": "Valve Manufacturing", "website_url": "https://processautomation.imiplc.com", "location": "Birmingham, West Midlands, UK", "certifications": ["ISO 9001", "ATEX", "PED", "SIL"], "capabilities": ["Control Valve Design", "Actuator Manufacture", "Valve Automation Packages", "Hygienic Valve Engineering", "Precision Flow Control"], "industries": ["Pharmaceutical", "Food & Beverage", "Chemical", "Oil & Gas", "Water Treatment"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1862, "materials": ["Stainless Steel", "Duplex", "Hastelloy", "Carbon Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AUMA Actuators Ltd', 'AUMA Actuators Ltd, incorporated in the UK in 1971 and headquartered in Clevedon, North Somerset, is the British subsidiary of AUMA Riester GmbH & Co. KG, the world''s largest manufacturer of electric valve actuators. The company supplies electric multi-turn and part-turn actuators for the water, oil & gas, power, and chemical industries, and has committed to expanding UK operations. AUMA''s global workforce spans 2,300 employees in 30 locations.', '{"company_type": "Actuator Manufacturing", "website_url": "https://www.auma.co.uk", "location": "Clevedon, North Somerset, UK", "certifications": ["ISO 9001", "ATEX", "IECEx", "SIL", "CE Marking"], "capabilities": ["Electric Multi-Turn Actuator Supply", "Part-Turn Actuator Manufacture", "Actuator Control Unit Design", "Valve Automation Integration", "Remote Monitoring Systems"], "industries": ["Water Treatment", "Oil & Gas", "Power Generation", "Chemical", "Offshore"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1971, "materials": ["Aluminium", "Stainless Steel", "Cast Iron"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Verderflex Ltd', 'Verderflex is the UK-based peristaltic pump manufacturing arm of the Verder Group, producing hose pumps and tube pumps from its facility in Castleford, West Yorkshire with a workforce of approximately 50 people. The company specialises in peristaltic and screw-channel (VerderHUS) pumps for demanding industrial applications including chemical dosing, wastewater, mining, food, and biopharma. Certified to ISO 9001, ISO 14001, and ISO 45001.', '{"company_type": "Pump Manufacturing", "website_url": "https://www.verderliquids.com/int/en/verderflex/", "location": "Castleford, West Yorkshire, UK", "certifications": ["ISO 9001", "ISO 14001", "ISO 45001"], "capabilities": ["Peristaltic Hose Pump Manufacture", "Tube Pump Design", "Screw-Channel Centrifugal Pump Manufacture", "Chemical Dosing Pump Engineering"], "industries": ["Water Treatment", "Chemical", "Mining", "Food & Beverage", "Pharmaceutical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1997, "materials": ["Stainless Steel", "Natural Rubber", "NBR", "EPDM", "PTFE"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Tapflo UK Ltd', 'Tapflo UK, launched in 1997 and based in Southampton, is the British arm of the global Tapflo Group (founded in Sweden over 45 years ago), manufacturing and distributing air-operated double-diaphragm pumps, centrifugal pumps, peristaltic pumps, and tailor-built process systems. The company holds ISO 9001:2015 certification and offers ATEX-rated, FDA, EHEDG, and USP VI certified pump options for pharmaceutical, food, and chemical applications. It supplies a broad industrial client base across the UK.', '{"company_type": "Pump Manufacturing", "website_url": "https://www.tapflopumps.co.uk", "location": "Southampton, Hampshire, UK", "certifications": ["ISO 9001", "ATEX", "EHEDG", "FDA", "USP VI"], "capabilities": ["Diaphragm Pump Manufacture", "Centrifugal Pump Supply", "Peristaltic Pump Engineering", "Sanitary Pump Design", "Custom Process System Build"], "industries": ["Pharmaceutical", "Food & Beverage", "Chemical", "Water Treatment", "Cosmetics"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1997, "materials": ["Stainless Steel", "Aluminium", "PTFE", "HDPE", "Cast Iron"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'North Ridge Pumps Ltd', 'North Ridge Pumps is an independent UK pump manufacturer and distributor established in 1998 and based in West Bridgford, Nottingham. The company supplies centrifugal, lobe, gear, peristaltic, and diaphragm pumps for freshwater, seawater, glycol, heavy oil, grease, food, and chemical applications. It serves industrial, marine, and process markets with a strong focus on technical pump selection and application engineering.', '{"company_type": "Pump Manufacturing", "website_url": "https://www.northridgepumps.com", "location": "West Bridgford, Nottingham, UK", "certifications": ["ISO 9001", "ATEX"], "capabilities": ["Centrifugal Pump Supply", "Lobe Pump Manufacture", "Gear Pump Engineering", "Peristaltic Pump Distribution", "Marine Pump Supply"], "industries": ["Marine", "Chemical", "Oil & Gas", "Food & Beverage", "Water Treatment"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1998, "materials": ["Stainless Steel", "Cast Iron", "Bronze", "Duplex"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Amazon Filters Ltd', 'Amazon Filters, founded in 1985 by engineer Mike Pizzey and headquartered in Camberley, Surrey, is one of Europe''s leading manufacturers of industrial filter cartridges, capsule filters, and filter housings with over 220 employees. Products are manufactured in cleanroom conditions using FDA food-contact compliant materials for applications in pharmaceutical, food & beverage, chemical, and water treatment industries. The company also has subsidiaries in Germany and Poland.', '{"company_type": "Filtration Systems", "website_url": "https://www.amazonfilters.com", "location": "Camberley, Surrey, UK", "certifications": ["ISO 9001", "FDA", "USP Class VI", "CE Marking"], "capabilities": ["Filter Cartridge Manufacture", "Capsule Filter Design", "Filter Housing Manufacture", "Sterile Filtration Engineering", "Membrane Filtration Supply"], "industries": ["Pharmaceutical", "Food & Beverage", "Chemical", "Water Treatment", "Biotechnology"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1985, "materials": ["PES", "PVDF", "PTFE", "Polypropylene", "Nylon", "Glass Fibre"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Porvair Filtration Group Ltd', 'Porvair Filtration Group, incorporated in 1966 and headquartered in Fareham, Hampshire, designs and manufactures high-performance filtration and separation materials and products for aerospace, nuclear, life sciences, chemical, and industrial process markets. Products include sintered metal filters, polymeric membrane cartridges, and custom porous materials, with approximately 501 employees across UK and US manufacturing sites. The group holds ISO 9001 and AS9100D certifications.', '{"company_type": "Filtration Systems", "website_url": "https://www.porvairfiltration.com", "location": "Fareham, Hampshire, UK", "certifications": ["ISO 9001", "AS9100D", "EASA Part 21G", "USP VI"], "capabilities": ["Sintered Metal Filter Manufacture", "Membrane Cartridge Design", "Custom Porous Material Manufacture", "Sterile Filtration Engineering", "Aerospace Filtration Supply"], "industries": ["Aerospace", "Pharmaceutical", "Chemical", "Nuclear", "Food & Beverage"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1966, "materials": ["Stainless Steel", "Titanium", "PES", "PVDF", "PTFE", "Borosilicate Glass"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Allied Filter Systems Ltd', 'Allied Filter Systems, established over 40 years ago and headquartered in Irlam, Manchester, is the UK''s leading manufacturer and supplier of liquid filtration system components, producing filter bags, cartridge filter housings, and strainers across three UK sites. The company manufactures liquid filter bags at its Irlam and Eccles facilities and produces stainless steel housings and strainers at its Warrington site. It serves chemical, food & beverage, water treatment, and general process industries.', '{"company_type": "Filtration Systems", "website_url": "https://www.alliedfilter.co.uk", "location": "Irlam, Manchester, UK", "certifications": ["ISO 9001"], "capabilities": ["Liquid Filter Bag Manufacture", "Cartridge Filter Housing Design", "Strainer Manufacture", "Bag Filter System Engineering", "Custom Filtration Housing Fabrication"], "industries": ["Chemical", "Food & Beverage", "Water Treatment", "Oil & Gas", "Pharmaceutical"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1980, "materials": ["Stainless Steel", "Carbon Steel", "Polypropylene", "Nylon", "Polyester"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Membracon UK Ltd', 'Membracon UK, established in 2002 and headquartered in Wolverhampton, West Midlands, is a global leader in industrial water treatment providing membrane-based solutions including ultrafiltration, nanofiltration, reverse osmosis, and ceramic filtration systems. Originally founded to serve the electropainting industry with membrane technology, the company has expanded to serve world-class manufacturing businesses on every continent. Its parent company Membracon Filtration B.V. is headquartered in the Netherlands.', '{"company_type": "Filtration Systems", "website_url": "https://www.membracon.co.uk", "location": "Wolverhampton, West Midlands, UK", "certifications": ["ISO 9001"], "capabilities": ["Ultrafiltration System Design", "Reverse Osmosis System Engineering", "Nanofiltration Supply", "Ceramic Membrane Filtration", "Electrocoating Equipment Manufacture"], "industries": ["Automotive", "Chemical", "Food & Beverage", "Water Treatment", "Pharmaceutical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2002, "materials": ["Ceramic", "PES", "PVDF", "Spiral Wound Membranes"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
