INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Chell Instruments Ltd', 'Chell Instruments, founded in 1976 and based in North Walsham, Norfolk, is a UK designer and manufacturer of gas mass flow meters, mass flow controllers, pressure instrumentation, and vacuum measurement systems. The company is UKAS accredited to ISO/IEC 17025:2017 for calibration services and produces both proprietary instruments and bespoke automated systems for research, industrial, and OEM customers. It has over 40 years of experience in precise gas flow measurement and control.', '{"company_type": "Flow Meter Manufacturing", "website_url": "https://chell.co.uk", "location": "North Walsham, Norfolk, UK", "certifications": ["ISO 9001", "UKAS ISO/IEC 17025"], "capabilities": ["Mass Flow Meter Manufacture", "Mass Flow Controller Design", "Pressure Instrument Manufacture", "Vacuum Measurement Systems", "Turnkey Automated System Build"], "industries": ["Research & Development", "Semiconductor", "Chemical", "Pharmaceutical", "Aerospace"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1976, "materials": ["Stainless Steel", "Aluminium", "PEEK"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Flowquip Ltd', 'Flowquip, founded in 1982 and based in Sowerby Bridge, West Yorkshire, is the UK''s leading provider of flow meters and process control systems, supplying Coriolis, electromagnetic, ultrasonic, and positive displacement flow measurement technologies. The company provides complete solutions encompassing design, supply, installation, and calibration for oil & gas, food & beverage, and energy industries. Its flow experts have over four decades of experience matching measurement technology to specific process conditions.', '{"company_type": "Flow Meter Manufacturing", "website_url": "https://www.flowquip.co.uk", "location": "Sowerby Bridge, West Yorkshire, UK", "certifications": ["ISO 9001", "ATEX", "WRAS"], "capabilities": ["Flow Meter Supply", "Coriolis Meter Distribution", "Electromagnetic Meter Systems", "Ultrasonic Flow Measurement", "Process Control System Design"], "industries": ["Oil & Gas", "Food & Beverage", "Water Treatment", "Chemical", "Energy"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1982, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pressure Tech Ltd', 'Pressure Tech, established in 2000 and based in Glossop, Derbyshire, is a specialist UK manufacturer of high-quality stainless steel pressure regulators for oil & gas, renewable energy, and industrial gas applications, employing over 35 people. Products cover pressures up to 1,380 bar (20,000 psi) and are manufactured predominantly in 316 stainless steel, with ATEX and IECEx certified variants available for hazardous environments. The company holds ISO 9001:2015 and PED certifications.', '{"company_type": "Valve Manufacturing", "website_url": "https://www.pressure-tech.com", "location": "Glossop, Derbyshire, UK", "certifications": ["ISO 9001", "PED", "ATEX", "IECEx"], "capabilities": ["Pressure Regulator Manufacture", "Back Pressure Regulator Design", "High-Pressure Gas Regulator Engineering", "Custom Pressure Control Solutions"], "industries": ["Oil & Gas", "Renewable Energy", "Industrial Gas", "Chemical", "Hydrogen"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2000, "materials": ["316 Stainless Steel", "Duplex", "Hastelloy", "PEEK"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oxford Flow Ltd', 'Oxford Flow is a University of Oxford spin-out founded in 2015, based in Oxford, that develops and manufactures innovative piston-based control valves and pressure regulators with a single moving part, eliminating traditional failure modes such as stems, seals, and diaphragms. The company has raised over $40M in venture capital including from bp Ventures and Energy Impact Partners, and has deployed valves across Europe, the US, and the Middle East. Products target oil & gas, gas distribution, power, and water industries.', '{"company_type": "Valve Manufacturing", "website_url": "https://oxford-flow.com", "location": "Oxford, Oxfordshire, UK", "certifications": ["ATEX", "PED"], "capabilities": ["Pressure Regulator Manufacture", "Control Valve Design", "Pilot Valve Engineering", "Low Emission Valve Systems", "Actuated Valve Assembly"], "industries": ["Oil & Gas", "Gas Distribution", "Power Generation", "Water Treatment", "Hydrogen"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2015, "materials": ["Stainless Steel", "Carbon Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Johnson Valves', 'Johnson Valves (trading name of G J Johnson & Sons Ltd) is a Southampton-based specialist with over 50 years of experience in the industrial, marine, and boiler valve markets, supplying pipeline valves, metering systems, pressure safety valves, and fluid control instrumentation. The company serves marine, boilerhouse, process, HVAC, and water industries in the UK and internationally. Its product range covers ball valves, gate valves, butterfly valves, check valves, and safety relief valves.', '{"company_type": "Valve Manufacturing", "website_url": "https://www.johnsonvalves.co.uk", "location": "Totton, Southampton, UK", "certifications": ["ISO 9001", "PED", "DNV", "Lloyd''s Register"], "capabilities": ["Marine Valve Supply", "Industrial Valve Distribution", "Safety Relief Valve Engineering", "Metering System Supply", "Boilerhouse Valve Packages"], "industries": ["Marine", "Industrial", "Water Treatment", "HVAC", "Oil & Gas"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1970, "materials": ["Bronze", "Stainless Steel", "Cast Iron", "Ductile Iron", "Gunmetal"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'GEMÜ Valves Ltd', 'GEMÜ Valves Ltd is the UK subsidiary of GEMÜ GmbH, a German family-owned valve manufacturer founded in 1964, operating from Warrington with a team of 15 support staff since establishing in England in 1981. GEMÜ manufactures diaphragm, ball, butterfly, check, globe, and solenoid valves with specialist expertise in hygienic and high-purity applications for pharmaceutical, biotechnology, food, and semiconductor industries. The global parent employs 1,900 people across six manufacturing locations.', '{"company_type": "Valve Manufacturing", "website_url": "https://www.gemu-group.com/en_EN/", "location": "Warrington, Cheshire, UK", "certifications": ["ISO 9001", "EHEDG", "FDA", "USP Class VI", "PED", "ATEX"], "capabilities": ["Diaphragm Valve Manufacture", "Hygienic Valve Design", "Solenoid Valve Engineering", "Ball Valve Supply", "Single-Use Valve Systems"], "industries": ["Pharmaceutical", "Biotechnology", "Food & Beverage", "Semiconductor", "Chemical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1981, "materials": ["Stainless Steel", "PTFE", "EPDM", "PFA"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Trillium Flow Technologies UK Ltd', 'Trillium Flow Technologies, with UK roots dating to 1966 and operating as Trillium since 2018 following acquisition from Weir Group, is a Glasgow-headquartered global designer and manufacturer of engineered valves and pumps for critical infrastructure including nuclear, power, and oil & gas. The UK entity manufactures gate, globe, check, ball, butterfly, and safety valves, including the Sarasin-RSBD brand of safety valves with API 520/526 and ASME UV certification. Operations span the USA, UK, Europe, the Middle East, and Asia.', '{"company_type": "Valve Manufacturing", "website_url": "https://www.trilliumflow.com", "location": "Glasgow, Scotland, UK", "certifications": ["ISO 9001", "PED", "ATEX", "API 520", "API 526", "ASME UV"], "capabilities": ["Gate Valve Manufacture", "Globe Valve Design", "Safety Valve Engineering", "Nuclear Valve Manufacture", "Check Valve Supply", "Subsea Valve Engineering"], "industries": ["Nuclear", "Power Generation", "Oil & Gas", "Chemical", "Water Treatment"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1966, "materials": ["Carbon Steel", "Stainless Steel", "Duplex", "Alloy Steel", "Super Alloys"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


