INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Smiths Interconnect', 'Smiths Interconnect is a global high-reliability connector and interconnect solutions manufacturer with significant UK operations, operating as part of FTSE-listed Smiths Group plc. Through the Hypertac brand they manufacture hyperboloid spring contact connectors offering ultra-low contact resistance, serving aerospace, defence, space, medical, semiconductor test, and rail markets. They hold approvals from ESA, NASA, ISRO, and JAXA for space-qualified products.', '{"company_type": "Connector Manufacturing", "website_url": "https://www.smithsinterconnect.com", "location": "London (HQ), with UK manufacturing sites, UK", "certifications": ["ISO 9001", "AS9100", "ESCC 3401", "ESCC 3402"], "capabilities": ["Hyperboloid Spring Contact Connectors", "RF & Microwave Connectors", "Space-Qualified Interconnects", "High-Speed Data Connectors", "Custom Interconnect Assemblies"], "industries": ["Aerospace", "Defence", "Space", "Medical", "Semiconductor Test", "Rail"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": ["Copper Alloys", "Titanium", "Gold Plating"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

