VALUES ('Products', 'Manufacturer', 'Gem Cable Solutions Ltd', 'Gem Cable Solutions is a St Albans-based manufacturer of cable assemblies, wire harnesses, and control cabinets for defence, aerospace, and satellite markets, operating for over 30 years with AS9100D certification. The company manufactures in a Class 8 cleanroom environment and holds JOSCAR and SC21 accreditations, making it a trusted UK defence supply chain partner. Markets served include satellite communications, aerospace, marine, robotics, nuclear, and broadcast.', '{"company_type": "Cable Assembly, Wiring Harness", "website_url": "https://www.gemcable.co.uk", "location": "St Albans, Hertfordshire, UK", "certifications": ["AS9100D", "ISO 9001:2015", "ISO 14001:2015", "JOSCAR", "SC21"], "capabilities": ["Cable Assembly Manufacture", "Wire Harness Manufacture", "Control Cabinet Build", "Box Build", "Cleanroom Assembly"], "industries": ["Defence", "Aerospace", "Satellite", "Marine", "Nuclear", "Robotics", "Broadcast"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Copper", "PTFE", "Silicone", "Screened Cable"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'TT Electronics (Fairford Division)', 'TT Electronics Fairford is a dedicated NADCAP-accredited cable harness and assembly manufacturer based in Fairford, Gloucestershire, established in 1978 and operating as part of the TT Electronics plc group. The facility employs over 80 people and specialises in complex harnesses for major defence platforms including F-35, Typhoon, and Storm Shadow. Certifications include AS9100, NADCAP AC7121, and UL Wiring Harness Traceability approval.', '{"company_type": "Cable Assembly, Wiring Harness", "website_url": "https://www.ttelectronics.com/global-manufacturing/cable-harness-assembly/", "location": "Fairford, Gloucestershire, UK", "certifications": ["AS9100", "ISO 9001:2015", "ISO 14001:2015", "NADCAP AC7121", "UL Wiring Harness Traceability"], "capabilities": ["Complex Cable Harness Manufacture", "Military Harness Assembly", "IPC/WHMA-A-620 Class 3 Assembly", "Electro-Mechanical Assembly"], "industries": ["Aerospace", "Defence"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1978, "materials": ["Copper", "PTFE", "Silicone", "MIL-spec Wire", "Screened Cable"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cablescan Ltd (an Amphenol company)', 'Cablescan is a UK manufacturer of high-performance electrical cable assemblies and control panels for aerospace, defence, marine, and industrial sectors, operating from a 39,000 sq ft facility in Brough, East Yorkshire. The company was acquired by Amphenol in 2019 and holds AS9100D and SC21 accreditations. Capabilities include avionics test bench manufacture, complex harness design, and repair and overhaul services.', '{"company_type": "Cable Assembly, Wiring Harness", "website_url": "https://www.cablescan.co.uk", "location": "Brough, East Yorkshire, UK", "certifications": ["AS9100D", "ISO 9001:2015", "SC21"], "capabilities": ["Cable Assembly Manufacture", "Avionics Test Bench Manufacture", "Control Panel Build", "Harness Design & Test", "Repair & Overhaul"], "industries": ["Aerospace", "Defence", "Marine", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Copper", "PTFE", "Screened Cable"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'WH Kemp Electrics Ltd', 'WH Kemp is the longest established cable harness manufacturer in England, founded in 1967 and based in Westbury, Wiltshire. The company holds ISO 9001 and UL ZPFW2 wiring harness component recognition, and was the first British manufacturer to achieve the UL Wire Harness accreditation. Products are manufactured to IPC/WHMA-A-620 standards for medical, defence, oil and gas, nuclear, scientific, and robotics sectors.', '{"company_type": "Cable Assembly, Wiring Harness", "website_url": "https://www.whkemp.co.uk", "location": "Westbury, Wiltshire, UK", "certifications": ["ISO 9001:2015", "UL ZPFW2", "IPC/WHMA-A-620"], "capabilities": ["Wire Harness Manufacture", "Cable Assembly", "Electrical Control Panel Build", "Electro-Mechanical Assembly"], "industries": ["Medical", "Defence", "Oil & Gas", "Nuclear", "Scientific", "Marine", "Automotive", "Robotics"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1967, "materials": ["Copper", "Silicone", "PTFE", "PVC"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'K Lacey Wires and Cables', 'K Lacey is a specialist cable assembly and wire harness manufacturer based in Rustington, West Sussex, with over 50 years of experience and Made in Britain certification. The company holds AS9100, AS9120, and ISO 9001 certifications, with all production operators trained to IPC/WHMA-A-620 standards. They supply aerospace, defence, automotive, and communications sectors with custom cable assemblies and wiring harnesses.', '{"company_type": "Cable Assembly, Wiring Harness", "website_url": "https://www.klaceycables.co.uk", "location": "Rustington, West Sussex, UK", "certifications": ["ISO 9001", "AS9100", "AS9120", "IPC/WHMA-A-620"], "capabilities": ["Cable Assembly Manufacture", "Wiring Harness & Loom Manufacture", "Cut, Strip & Tin", "Wire Crimping", "Electrical Testing"], "industries": ["Aerospace", "Defence", "Automotive", "Communications", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Copper", "PTFE", "Silicone", "MIL-spec Wire"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cablepoint Ltd', 'Cablepoint is a Hull-based cable assembly manufacturer established in 1991, operating from a 1,500 m² production facility on Sutton Fields Industrial Estate. The company manufactures high-voltage cable assemblies for EV battery packs, motors, and charging systems, as well as assemblies for military, pharmaceutical, agricultural, and traffic management sectors. Certified to ISO 9001, ISO 14001, and IPC/WHMA-A-620.', '{"company_type": "Cable Assembly, HV Cable Assembly", "website_url": "https://www.cablepoint.co.uk", "location": "Hull, East Yorkshire, UK", "certifications": ["ISO 9001", "ISO 14001", "IPC/WHMA-A-620", "UL", "CE"], "capabilities": ["HV Cable Assembly Manufacture", "Moulded & Potted Cable Assembly", "Wiring Harness Manufacture", "Electrical Testing"], "industries": ["Automotive / EV", "Military", "Pharmaceutical", "Agricultural", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1991, "materials": ["Copper", "Silicone", "XLPE", "PVC", "TPU"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Heatsense Cables Ltd', 'Heatsense Cables is a Rochdale-based specialist manufacturer of thermocouple and high-performance cables founded in 1984, certified to ISO 9001, ISO 14001, and AS9100 Rev D. The company manufactures cables insulated with PTFE, FEP, ETFE, PEEK, EFGLAS, and silicone for extreme temperature applications in aerospace, nuclear, medical, and R&D sectors. Heatsense holds F4N (Fit for Nuclear) approval from the NAMRC.', '{"company_type": "Wire & Cable Manufacturing", "website_url": "https://www.heatsensecables.co.uk", "location": "Rochdale, Lancashire, UK", "certifications": ["ISO 9001:2015", "ISO 14001:2015", "AS9100 Rev D", "F4N (Fit for Nuclear)"], "capabilities": ["Thermocouple Cable Manufacture", "High-Temperature Cable Manufacture", "PTFE Cable Extrusion", "Specialist Cable Design"], "industries": ["Aerospace", "Nuclear", "Medical", "Scientific & R&D", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1984, "materials": ["PTFE", "FEP", "ETFE", "XLETFE", "PEEK", "EFGLAS", "Silicone", "Copper", "Nickel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Axon'' Cable Ltd', 'Axon'' Cable operates a UK manufacturing facility at Rosyth, Fife, Scotland, forming part of the French-headquartered Axon'' Cable Group specialising in high-performance cables and Micro-D / Nano-D connectors. The UK operation serves aerospace, defence, and space sectors with fluoropolymer-insulated cables, Mil-1553B databus looms, RF/EMI shielded assemblies, and ESA-standard space cables. Products comply with ESCC 3901, ESCC 3902, and MIL-spec standards.', '{"company_type": "Wire & Cable Manufacturing, Connector Manufacturing", "website_url": "https://www.axon-cable.com/en/axon-cable-united-kingdom", "location": "Rosyth, Fife, Scotland, UK", "certifications": ["ISO 9001", "AS9100", "ESCC 3901", "ESCC 3902"], "capabilities": ["Space Cable Manufacture", "Fluoropolymer Cable Extrusion", "Micro-D & Nano-D Connector Manufacture", "RF/EMI Shielded Assembly", "Mil-1553B Databus Loom Assembly"], "industries": ["Aerospace", "Defence", "Space", "Medical", "Robotics"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["PTFE", "FEP", "ETFE", "Copper", "Silver-Plated Copper"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Scott Cables Ltd', 'Scott Cables is a Portsmouth, Hampshire-based specialist manufacturer and distributor of RF coaxial cable assemblies, microwave cables, and wiring harnesses. The company manufactures bespoke coaxial cable assemblies and harnesses for defence, aerospace, rail, automotive, and telecommunications sectors from their modern Hampshire facility. Products cover a wide range of coaxial cable types and RF connector configurations.', '{"company_type": "Cable Assembly, RF Coaxial Cable", "website_url": "https://www.scottcables.com", "location": "Portsmouth, Hampshire, UK", "certifications": ["ISO 9001"], "capabilities": ["RF Coaxial Cable Assembly Manufacture", "Microwave Cable Assembly", "Wiring Loom Manufacture", "Harness Assembly"], "industries": ["Defence", "Aerospace", "Rail", "Automotive", "Telecommunications", "Broadcast"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Copper", "PTFE", "Low-Loss Foam Dielectric", "Aluminium Foil Shielding"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ICS (Interconnection Cables & Systems) Ltd', 'ICS is a British family-run RF coaxial cable assembly manufacturer founded in 1972 and based in Peterchurch, Herefordshire. Operating from a 5,000 sq ft facility, the company manufactures bespoke coaxial cable assemblies for satellite communications, scientific research, data, and industrial sectors, with all cables 100% functionally tested. ICS holds ISO 9001:2015 accreditation.', '{"company_type": "Cable Assembly, RF Coaxial Cable", "website_url": "https://www.ics-hereford.co.uk", "location": "Peterchurch, Herefordshire, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["RF Coaxial Cable Assembly Manufacture", "Custom Wire Assembly", "Flat Ribbon Cable Assembly", "100% Functional Cable Testing"], "industries": ["Satellite Communications", "Scientific Research", "Data", "Defence", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1972, "materials": ["Copper", "PTFE", "Low-Loss Coaxial", "Aluminium Shielding"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'H V Wooding Ltd', 'H V Wooding is a Hythe, Kent-based precision component manufacturer with over 50 years of experience specialising in copper and aluminium busbars, motor laminations, stators, and rotors. The company serves EV/hybrid vehicles, electrical switchgear, wind turbines, and solar energy sectors, with long-standing partnerships including Schneider Electric, Honeywell, Rolls-Royce, and GE Renewables. Certified to ISO 9001, ISO 14001, and ISO 45001.', '{"company_type": "Busbar & Precision Component Manufacturing", "website_url": "https://www.hvwooding.co.uk", "location": "Hythe, Kent, UK", "certifications": ["ISO 9001:2015", "ISO 14001:2015", "ISO 45001:2018"], "capabilities": ["Copper Busbar Manufacture", "Aluminium Busbar Manufacture", "Motor Lamination Manufacture", "Stator & Rotor Manufacture", "Precision Stamping & Pressing"], "industries": ["Automotive / EV", "Electrical Switchgear", "Renewable Energy", "Power Generation", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Copper", "Aluminium", "Electrical Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SIGA (Electronics) Ltd', 'SIGA Electronics is a Sandy, Bedfordshire-based manufacturer of toroidal and bobbin wound transformers and magnetic components established in 1961, originally supplying the aerospace industry. The company designs and produces a full range of wound components for telecom, industrial, military, aerospace, automotive, oil and gas, medical, and renewable energy sectors from a purpose-built factory. Products include UL-approved transformers and components conforming to IEC 61869.', '{"company_type": "Magnetic Components Manufacturing", "website_url": "https://sigatransformers.co.uk", "location": "Sandy, Bedfordshire, UK", "certifications": ["ISO 9001", "UL", "IEC 61869"], "capabilities": ["Toroidal Transformer Manufacture", "Bobbin Wound Component Manufacture", "Custom Inductor Design", "Current Transformer Manufacture"], "industries": ["Aerospace", "Telecommunications", "Military", "Automotive", "Medical", "Oil & Gas", "Renewable Energy", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1961, "materials": ["Silicon Steel", "Ferrite", "Copper", "Aluminium", "Epoxy Resin"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Noratel UK Ltd', 'Noratel UK is the British subsidiary of Noratel Group, part of FTSE 250-listed discoverIE Group plc, based in Nantwich, Cheshire. As one of Europe''s leading manufacturers of customised transformers and wound components with over 100 years of heritage, Noratel specialises in products for renewable energy (wind pitch control, solar inverters), rail, eMobility, motor drives, and medical devices. The group employs 2,500 globally and 75% of products are bespoke.', '{"company_type": "Magnetic Components Manufacturing", "website_url": "https://www.noratel.com", "location": "Nantwich, Cheshire, UK", "certifications": ["ISO 9001:2015", "ISO 14001:2015", "ISO 13485", "APQP4Wind"], "capabilities": ["Custom Transformer Design & Manufacture", "Wound Component Manufacture", "Power Filter Manufacture", "Reactor Manufacture"], "industries": ["Renewable Energy", "Rail", "eMobility / EV", "Motor Drives", "Medical", "Marine & Offshore", "Audio"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": ["Silicon Steel", "Ferrite", "Copper", "Aluminium", "Nanocrystalline"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Wilson Power Solutions Ltd', 'Wilson Power Solutions is a Leeds-based power and distribution transformer manufacturer with over 135 skilled professionals operating from a 5,500 m² facility, and UK Companies House registration since 1993. The company specialises in custom transformers for major UK and European renewable energy projects as well as conventional industrial applications, with all products manufactured to BS and IEC standards. Certified to ISO 9001, ISO 14001, and ISO 45001.', '{"company_type": "Power Transformer Manufacturing", "website_url": "https://wilsonpowersolutions.co.uk", "location": "Leeds, West Yorkshire, UK", "certifications": ["ISO 9001", "ISO 14001", "ISO 45001"], "capabilities": ["Distribution Transformer Manufacture", "Power Transformer Manufacture", "Dry-Type Transformer Manufacture", "Custom Transformer Design"], "industries": ["Renewable Energy", "Utilities", "Industrial", "Construction", "Data Centres"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1993, "materials": ["Silicon Steel", "Copper", "Aluminium", "Epoxy Resin"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Winder Power Ltd', 'Winder Power is a Leeds, West Yorkshire-based designer and manufacturer of distribution, power, and grid transformers with roots dating back to 1898, operating from an 80,000 sq ft modern factory in Pudsey. The company serves utilities, heavy industry, commercial infrastructure, and renewable energy sectors including solar, wind, and battery storage. With over 135 employees, they design and manufacture transformers for generator, rectifier, and converter applications.', '{"company_type": "Power Transformer Manufacturing", "website_url": "https://www.winderpower.co.uk", "location": "Pudsey, Leeds, West Yorkshire, UK", "certifications": ["ISO 45001"], "capabilities": ["Power Transformer Manufacture", "Distribution Transformer Manufacture", "Grid Transformer Manufacture", "Transformer Installation & Servicing"], "industries": ["Utilities", "Renewable Energy", "Heavy Industry", "Commercial Infrastructure", "Rail"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1898, "materials": ["Silicon Steel", "Copper", "Aluminium", "Insulating Oil"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'R Baker (Electrical) Ltd', 'R Baker (Electrical) Ltd is a Liverpool-based transformer and inductor manufacturer founded in 1982, producing custom-built transformers, chokes, inductors, and rectifier units for defence, marine, offshore, and industrial sectors. The company holds ATEX, IECEx, and FM certifications for transformers used in hazardous environments, and manufactures products certified to BS EN61558 and EN 60076. Customers include defence, offshore, petrochemical, and renewable energy companies.', '{"company_type": "Power Transformer Manufacturing, Magnetic Components", "website_url": "https://www.rbaker.co.uk", "location": "Speke, Liverpool, UK", "certifications": ["ISO 9001:2015", "ATEX", "IECEx", "FM", "CE"], "capabilities": ["Custom Transformer Manufacture", "Inductor & Choke Manufacture", "Rectifier Unit Manufacture", "ATEX-Certified Transformer Manufacture", "Step-Up & Step-Down Transformer Design"], "industries": ["Defence", "Marine", "Offshore", "Renewable Energy", "Petrochemical", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1982, "materials": ["Silicon Steel", "Copper", "Aluminium", "Epoxy Resin"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Leeds Transformer Co. Ltd', 'Leeds Transformer Co. is a Leeds-based bespoke transformer and rectifier manufacturer established in 1947, specialising in custom-built units for hazardous areas, renewable energy, and military applications. The company designs and manufactures a wide range of custom transformers certified to IECEx and ATEX standards for use in explosive atmospheres, and serves solar, defence, and specialist industrial markets.', '{"company_type": "Power Transformer Manufacturing", "website_url": "https://www.leedstransformer.co.uk", "location": "Leeds, West Yorkshire, UK", "certifications": ["IECEx", "ATEX"], "capabilities": ["Bespoke Transformer Manufacture", "Rectifier Unit Manufacture", "ATEX Hazardous Area Transformer Design", "Military Transformer Manufacture"], "industries": ["Defence", "Renewable Energy", "Petrochemical", "Industrial", "Scientific"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1947, "materials": ["Silicon Steel", "Copper", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AGW Electronics Ltd', 'AGW Electronics is a Staveley, Derbyshire-based specialist in sub-contract design and manufacture of wound components, now part of the KAMIC Group''s ETAL division following a 2023 acquisition. Founded in 1975 and operating from a purpose-built 30,000 sq ft facility with approximately 60 employees, the company manufactures toroidal and planar transformers, common mode chokes, EMC suppression chokes, power inductors, and custom wound assemblies for power electronics and industrial markets.', '{"company_type": "Magnetic Components Manufacturing", "website_url": "https://agw.co.uk", "location": "Staveley, Derbyshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Toroidal Transformer Manufacture", "Planar Transformer & Inductor Manufacture", "Common Mode Choke Manufacture", "EMC Suppression Choke Design", "Power Inductor Manufacture", "Custom Wound Component Assembly"], "industries": ["Power Electronics", "Renewable Energy", "Industrial", "Automotive / EV", "Telecommunications"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1975, "materials": ["Ferrite", "Silicon Steel", "Nanocrystalline", "Copper", "Litz Wire"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Admagnetics Ltd', 'Admagnetics is a family-owned transformer and choke manufacturer based in Accrington, Lancashire, founded in 1991 by Alan D Moorhouse MBE. The company manufactures single- and three-phase power transformers, toroidal transformers, line reactors, DC chokes, and inphase transformers to UK and international standards including BS EN 60076 and IEC 60076. Products serve variable speed drives, industrial power, and inverter applications.', '{"company_type": "Magnetic Components Manufacturing, Power Transformer Manufacturing", "website_url": "https://admagnetics.co.uk", "location": "Accrington, Lancashire, UK", "certifications": ["BS EN 60076", "IEC 60076", "Made in Britain"], "capabilities": ["Three-Phase Transformer Manufacture", "Toroidal Transformer Manufacture", "DC Choke & Line Reactor Manufacture", "Custom Transformer Design"], "industries": ["Industrial", "Power Electronics", "Motor Drives", "Renewable Energy", "Marine"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1991, "materials": ["Silicon Steel", "Copper", "Aluminium", "Grain-Oriented Electrical Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'East Manufacturing Technologies Ltd (EMTL)', 'EMTL is a Letchworth, Hertfordshire-based specialist in ferrite cores, soft magnetic materials, and wound ferrite components, trading as East Trading Ltd since 1994 before adding manufacturing operations in 1999. The ISO 9001-certified company supplies ferrite EE, ETD, RM, toroidal, and pot cores along with custom wound assemblies including transformers, chokes, and inductors for power electronics and EMC applications. Products are batch-tested in-house with grinding facilities for air-gap customisation.', '{"company_type": "Magnetic Components Manufacturing", "website_url": "https://emtl.co.uk", "location": "Letchworth, Hertfordshire, UK", "certifications": ["ISO 9001", "RoHS Compliant"], "capabilities": ["Ferrite Core Supply & Gapping", "Custom Wound Ferrite Transformer Manufacture", "Inductor & Choke Manufacture", "Soft Magnetic Material Supply", "Batch Testing"], "industries": ["Power Electronics", "Telecommunications", "Industrial", "Automotive / EV", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1994, "materials": ["Ferrite", "Copper", "MnZn Ferrite", "NiZn Ferrite"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'LaminaCore Solutions', 'LaminaCore Solutions is a UK-based supplier and distributor of high-performance magnetic cores for transformer and inductor designers in power electronics, EV, and renewable energy applications. The company supplies CRGO, nanocrystalline, cobalt-based amorphous, and MuMetal (NiFe) cores in toroidal, C-core, E-core, block, and custom formats to engineering teams and OEMs across the UK and Europe. Key applications include EV inverters, onboard chargers, traction motor controllers, and industrial power supplies.', '{"company_type": "Magnetic Components", "website_url": "https://www.laminacoresolutions.co.uk", "location": "UK", "certifications": [], "capabilities": ["CRGO Core Supply", "Nanocrystalline Core Supply", "Amorphous Core Supply", "Custom Core Formats", "Engineering Support"], "industries": ["Automotive / EV", "Renewable Energy", "Industrial Power Electronics", "Audio"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["CRGO (Silicon Steel)", "Nanocrystalline", "Amorphous (Cobalt-Based)", "MuMetal (NiFe)"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


