INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Alexander Battery Technologies (Europe) Ltd', 'A custom battery pack and charger manufacturer based in Peterlee, County Durham, with over 40 years of global engineering history. They design and manufacture lithium-ion, NiMH and primary battery packs incorporating integrated BMS electronics with wireless connectivity and sensor integration. Serves defence, medical, industrial, and renewable energy storage sectors from a 110+ person UK facility.', '{"company_type": "Battery Pack Assembly, BMS Electronics", "website_url": "https://www.alexandertechnologies.com", "location": "Peterlee, County Durham, UK", "certifications": ["ISO 9001"], "capabilities": ["Custom Lithium-Ion Battery Pack Design", "Battery Management System Development", "NiMH Battery Pack Assembly", "Custom Battery Charger Design", "Smart Battery Packs with Fuel Gauging"], "industries": ["Defence", "Medical", "Industrial", "Renewable Energy Storage", "Electric Vehicles"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1984, "materials": ["Lithium-Ion Cells", "NiMH Cells", "Polymer Enclosures"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AceOn Group Ltd', 'A family-run battery specialist headquartered in Telford, Shropshire, offering custom battery pack assembly and industrial battery distribution across the UK and internationally. With roots tracing back to a production site active since 1993, AceOn holds ISO 9001:2015 accreditation and serves industries including medical, defence, aerospace, railway, and renewable energy. The group operates battery, solar, and energy storage divisions.', '{"company_type": "Battery Pack Assembly", "website_url": "https://www.aceongroup.com", "location": "Telford, Shropshire, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Custom Lithium-Ion Battery Pack Assembly", "Utility-Scale Energy Storage", "Battery Distribution", "Solar Energy Storage Solutions", "Battery Pack Testing"], "industries": ["Medical", "Defence", "Aerospace", "Railway", "Renewable Energy", "Oil & Gas"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 2010, "materials": ["Lithium-Ion Cells", "LiFePO4 Cells", "NiMH Cells"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Lincad Ltd', 'A privately owned precision battery and charger manufacturer based in Ash Vale, Surrey, with nearly 40 years of engineering expertise. Lincad specialises in bespoke lithium-ion battery packs and chargers for military, defence, and harsh-environment applications across land, sea, and air platforms. The company holds ISO 9001:2015, ISO 14001, TickITplus, and Cyber Essentials Plus accreditations and is a registered JOSCAR supplier.', '{"company_type": "Battery Pack Assembly", "website_url": "https://www.lincad.co.uk", "location": "Ash Vale, Surrey, UK", "certifications": ["ISO 9001:2015", "ISO 14001", "TickITplus", "Cyber Essentials Plus", "JOSCAR"], "capabilities": ["Bespoke Lithium-Ion Battery Design", "Custom Battery Charger Manufacture", "Ruggedised Military Battery Systems", "Regulatory Testing to UK Def Stans and US Mil Specs", "Battery Electronics and Firmware"], "industries": ["Defence", "Military", "Subsea", "Aerospace", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1988, "materials": ["Lithium-Ion Cells", "Lithium Polymer Cells", "Ruggedised Enclosures"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Custom Power Ltd', 'Formerly the battery division of Steatite, Custom Power is a specialist UK lithium battery pack manufacturer operating from Crewkerne, Somerset, with a 60,000 sq ft facility. The ISO 9001:2015 certified company builds custom lithium-ion, Li-SOCI2, and NiMH packs for critical industrial, energy, defence, and autonomous applications. They are an approved Ministry of Defence supplier and work with cells from tier-one producers including Panasonic.', '{"company_type": "Battery Pack Assembly", "website_url": "https://custompower.co.uk", "location": "Crewkerne, Somerset, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Custom Lithium-Ion Battery Pack Manufacturing", "Portable Power System Design", "Energy Storage System Build", "Primary Battery Pack Assembly", "COTS Battery Module Supply"], "industries": ["Defence", "Industrial", "Autonomous Systems", "Energy", "Oil & Gas"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Lithium-Ion Cells", "Lithium Thionyl Chloride Cells", "NiMH Cells"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Enix Power Solutions Ltd', 'A European battery pack designer and assembler with a UK production base in Solihull, West Midlands, offering over 30 years of experience. Enix designs and manufactures custom primary and rechargeable lithium battery packs for industrial OEMs and is an authorised assembler for Saft and Tadiran cells. The company operates assembly lines in Solihull as part of a wider European group with operations in France and Spain.', '{"company_type": "Battery Pack Assembly", "website_url": "https://www.enix-power-solutions.com", "location": "Solihull, West Midlands, UK", "certifications": ["ISO 9001"], "capabilities": ["Custom Lithium Battery Pack Design", "Primary Battery Pack Assembly", "Rechargeable Battery Pack Manufacturing", "Authorised Saft and Tadiran Assembly"], "industries": ["Industrial", "Medical", "Defence", "Telecommunications", "IoT"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Lithium Thionyl Chloride Cells", "Lithium-Ion Cells", "Saft Cells", "Tadiran Cells"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
