INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Brill Power Ltd', 'An Oxford University spin-out founded in 2016, Brill Power develops intelligent Battery Management Systems featuring patented Active Loading BMS+ power converter technology for stationary energy storage and electric vehicle applications. Based in Oxford, the company''s Battery Intelligence Platform delivers improvements in longevity, performance, and cost, and has been acquired by Palmer Energy Technology Limited to accelerate UK BESS deployment.', '{"company_type": "BMS Electronics", "website_url": "https://brillpower.com", "location": "Oxford, Oxfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Intelligent BMS Hardware Design", "Active Cell Balancing Technology", "Battery Analytics and Edge Computing", "BESS Module Integration", "Battery State-of-Health Monitoring"], "industries": ["Grid Storage", "Electric Vehicles", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2016, "materials": ["LFP Cells", "BMS Electronics", "Power Converters"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Echion Technologies Ltd', 'A University of Cambridge spinout founded in 2017 and based in Sawston, Cambridgeshire, Echion has invented and patented XNO, a niobium-based anode material enabling lithium-ion batteries to fast charge safely in under 10 minutes with a cycle life exceeding 10,000 cycles. The company raised £29 million in Series B funding in 2024 and opened a 2,000 tonne per year XNO production facility, targeting heavy-duty transport and industrial electrification.', '{"company_type": "Electrode and Electrolyte Materials", "website_url": "https://www.echiontech.com", "location": "Sawston, Cambridgeshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Niobium Oxide Anode Material Production", "Fast-Charge Battery Material Development", "Electrode Material Characterisation", "Scale-Up Manufacturing", "Battery Cell Materials Supply"], "industries": ["Electric Vehicles", "Commercial Transport", "Rail", "Industrial Equipment"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2017, "materials": ["Mixed Niobium Oxide (XNO)", "Anode Active Materials"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Integrals Power Ltd', 'A next-generation battery cathode materials company based in Milton Keynes, developing and commercialising Lithium Iron Phosphate (LFP) and Lithium Manganese Iron Phosphate (LMFP) cathode materials for EV and grid battery manufacturers. Backed by six UK government grants including Advanced Propulsion Centre funding, IPL is establishing a UK pilot plant to position Britain as a hub for LFP cathode supply and has begun distributing material samples to automotive OEMs.', '{"company_type": "Electrode and Electrolyte Materials", "website_url": "https://integralspower.co.uk", "location": "Milton Keynes, Buckinghamshire, UK", "certifications": ["ISO 9001"], "capabilities": ["LFP Cathode Material Manufacturing", "LMFP Cathode Material Development", "Battery Material Scale-Up", "Cathode Material Characterisation", "R&D Material Sample Distribution"], "industries": ["Electric Vehicles", "Grid Storage", "Battery Cell Manufacturing"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Lithium Iron Phosphate (LFP)", "Lithium Manganese Iron Phosphate (LMFP)"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Faradion Ltd', 'Founded in 2011 and headquartered at the Innovation Centre in Sheffield, Faradion is the UK''s first company to invent and commercialise sodium-ion battery technology, holding more patents in non-aqueous sodium-ion than any competing company. Their technology delivers high performance, safety, and cost-effectiveness comparable to lithium-ion chemistry at lead-acid prices, targeting transportation, grid storage, backup power, and off-grid applications. Acquired by Reliance Industries in 2024.', '{"company_type": "Electrode and Electrolyte Materials", "website_url": "https://faradion.co.uk", "location": "Sheffield, South Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Sodium-Ion Cell Chemistry Development", "Cathode and Anode Material IP", "Battery Technology Licensing", "Prototype Cell Production", "Grid and Transport Battery Development"], "industries": ["Grid Storage", "Electric Vehicles", "Off-Grid Power", "Backup Power"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 2011, "materials": ["Sodium-Ion Active Materials", "Non-Aqueous Electrolytes", "Oxide Cathode Materials"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Avocet Battery Materials Ltd (ABM)', 'The only manufacturer of lithium-ion cell tabs in the UK and the entire Western world, based at Manor Point Industrial Park in Holmes Chapel, Cheshire. ABM was founded from Avocet Precision Metals'' 25 years of strip metals expertise and produces nickel, aluminium, and copper cell tabs for pouch cell producers ranging from university R&D programmes to gigafactories. ISO 9001 certified, ABM has a capacity of 1.5 million tab sets per year.', '{"company_type": "Battery Cell Components", "website_url": "https://www.avocetbattery.com", "location": "Holmes Chapel, Cheshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Lithium-Ion Cell Tab Manufacturing", "Nickel Tab Production", "Aluminium Tab Production", "Copper Cell Tab Production", "Pouch Cell Component Supply"], "industries": ["Battery Cell Manufacturing", "Electric Vehicles", "Grid Storage", "Research & Development"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2020, "materials": ["Nickel Strip", "Aluminium Foil", "Copper Foil", "Nickel-Plated Copper"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'BGB Innovation Ltd', 'A family-owned precision engineering company founded in 1976 and based in Grantham, Lincolnshire, BGB is the world''s number one wind turbine slip ring solutions provider, supplying units to six of the top ten global turbine OEMs including Vestas, Siemens Gamesa, and GE. With over 125 employees and annual turnover around £25 million, BGB has been delivering wind turbine electrical slip ring assemblies since 1991 and exports to over 77 countries.', '{"company_type": "Wind Components", "website_url": "https://www.bgbinnovation.com", "location": "Grantham, Lincolnshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Wind Turbine Slip Ring Assembly", "Hub Control Slip Ring Design", "Generator Slip Ring Manufacture", "Wind Turbine Aftermarket Parts Supply", "Custom Rotating Electrical Interface Design"], "industries": ["Wind Energy", "Offshore Wind", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1976, "materials": ["Copper", "Carbon Brushes", "Precious Metal Contacts", "Fibre Glass Composites"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Siemens Gamesa Renewable Energy Ltd (Hull Blade Factory)', 'Siemens Gamesa operates the UK''s largest offshore wind component manufacturing facility at Alexandra Dock in Hull, East Yorkshire, having invested over £310 million in the site since opening in 2016. The factory manufactures up to 108-metre offshore wind turbine blades and employs approximately 1,300 people, with over 2,000 blades delivered to offshore wind projects worldwide. The facility produces recyclable blade technology and serves projects including Sofia, East Anglia, and ScottishPower offshore wind farms.', '{"company_type": "Wind Components", "website_url": "https://www.siemensgamesa.com", "location": "Hull, East Yorkshire, UK", "certifications": ["ISO 9001", "ISO 14001", "OHSAS 18001"], "capabilities": ["Offshore Wind Turbine Blade Manufacture", "108-Metre Composite Blade Production", "Recyclable Blade Technology", "Blade Testing and Certification", "Component Assembly for Offshore Turbines"], "industries": ["Offshore Wind Energy"], "lead_time": null, "min_order": null, "employees": "250+", "established": 2016, "materials": ["Glass Fibre Composites", "Carbon Fibre", "Epoxy Resin", "Balsa Wood Core"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
