INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sunfixings Ltd', 'Incorporated in 2011 and headquartered in Bourton-on-the-Water, Gloucestershire, Sunfixings is a trusted leader in designing, manufacturing, and supplying solar PV mounting systems for residential, commercial, agricultural, and ground-mounted installations across the UK and Europe. Having completed over 1,000 unique projects, they supply to high-profile clients including Sainsbury''s, ASDA, and Battersea Dogs Home. The company is pursuing ISO 9001, ISO 14001, and OHSAS 18001 accreditation.', '{"company_type": "Solar Mounting Systems", "website_url": "https://www.sunfixings.co.uk", "location": "Bourton-on-the-Water, Gloucestershire, UK", "certifications": ["MCS", "ISO 9001 (in progress)", "ISO 14001 (in progress)"], "capabilities": ["Rooftop Solar PV Mounting Design", "Ground-Mounted Racking Systems", "Agricultural Solar Mounting", "Carport Solar Structures", "Facade-Mounted PV Systems"], "industries": ["Solar Energy", "Commercial Solar", "Agricultural Solar", "Residential Solar"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2011, "materials": ["Aluminium Extrusions", "Stainless Steel Fixings", "Galvanised Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'RADIX Group Ltd', 'The UK''s largest supplier and installer of ground screws and screw pile foundations, RADIX manufactures the SolarMount racking system in the UK for commercial and utility-scale solar projects. Based in the UK with operations extending to Ireland, Europe, Scandinavia, and Australia, RADIX systems come with a 25-year warranty and the company has been trusted on over 3 GW of renewable energy projects worldwide, with production capacity of 1 MW per week (5,000 panels).', '{"company_type": "Solar Mounting Systems", "website_url": "https://radixgroup.co.uk", "location": "UK", "certifications": ["ISO 9001"], "capabilities": ["Ground Screw Foundation Supply and Installation", "Solar Racking System Manufacture", "SolarMount Frame Design", "SolarTripod Ground Mount Production", "Engineered Foundation Solutions for Solar Farms"], "industries": ["Solar Energy", "Renewable Energy", "Commercial Solar", "Utility-Scale Solar"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Galvanised Steel", "Aluminium", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Anesco Ltd', 'A Reading, Berkshire-based renewable energy company founded in 2010, Anesco is one of the UK''s largest providers of grid-scale solar farm and battery energy storage EPC and asset management services. The company has designed and constructed 144 solar farms and BESS projects, managing over 1.6 GW of clean energy across 24,000 assets. Anesco delivers full EPC contracts for utility-scale BESS up to 100 MW and has constructed some of the UK''s largest and most complex grid storage developments.', '{"company_type": "Grid-Scale Energy Storage System Integrator", "website_url": "https://anesco.co.uk", "location": "Reading, Berkshire, UK", "certifications": ["ISO 9001", "ISO 14001", "OHSAS 18001"], "capabilities": ["Grid-Scale BESS EPC Delivery", "Solar Farm Engineering, Procurement and Construction", "Renewable Energy Asset Management", "BESS Operations and Maintenance", "Energy Company Obligation Scheme Management"], "industries": ["Grid Storage", "Solar Energy", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "250+", "established": 2010, "materials": ["Tier-1 Lithium-Ion Battery Cells", "Inverters", "Transformer Equipment"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'BELECTRIC Solar Ltd', 'A UK subsidiary of the German Elevion Group, BELECTRIC UK has operated since 2010 and is a leading EPC and O&M service provider for large-scale solar farms and battery energy storage systems. The UK arm serves as Belectric''s Global Centre of Excellence for BESS, having built its first UK battery storage system in 2017. BELECTRIC employs over 90 solar experts and currently manages O&M for more than 300 MWp of installed PV capacity across the UK.', '{"company_type": "Grid-Scale Energy Storage System Integrator", "website_url": "https://belectric.com/belectric-uk", "location": "UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Large-Scale Solar Farm EPC", "Battery Energy Storage System Integration", "BESS Engineering and Procurement", "Solar O&M Services", "Grid-Connected System Commissioning"], "industries": ["Solar Energy", "Grid Storage", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 2010, "materials": ["Tier-1 Battery Systems", "Solar PV Modules", "Grid-Scale Inverters"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Zenobe Energy Ltd', 'Founded in 2017 and headquartered in London, Zenobe is a leading owner and operator of grid-scale battery storage in the UK with over 730 MW in operation, including the Blackhillock site in Scotland, which is Europe''s largest grid-scale battery. Zenobe also finances and manages over 1,000 electric vehicles for fleet operators and is expanding internationally into Australia, New Zealand, North America, and Benelux. The company integrates and operates grid-connected BESS assets for network frequency response and energy trading.', '{"company_type": "Grid-Scale Energy Storage System Integrator", "website_url": "https://www.zenobe.com", "location": "London, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Grid-Scale Battery Storage Ownership and Operation", "BESS Project Development and Integration", "EV Fleet Battery Financing", "Frequency Response and Grid Services", "Second-Life Battery Repurposing"], "industries": ["Grid Storage", "Electric Vehicles", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "250+", "established": 2017, "materials": ["Tier-1 Lithium-Ion Battery Systems", "Grid-Scale Inverters"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Penso Power Ltd', 'A London-based BESS project developer founded in 2017, Penso Power delivered Europe''s first 100 MW grid-scale battery at Minety in 2020 and has built a development pipeline exceeding 2 GW across the UK and Australia. The company specialises in originating, developing, and managing large-scale battery energy storage projects through to financial close, partnering with battery system suppliers such as Sungrow. Penso Power is now majority-owned by BW ESS.', '{"company_type": "Grid-Scale Energy Storage System Integrator", "website_url": "https://www.pensoenergy.com", "location": "London, UK", "certifications": ["ISO 9001"], "capabilities": ["Grid-Scale BESS Project Development", "Battery Storage Site Origination", "Revenue Floor Contract Procurement", "Grid Connection Management", "International BESS Pipeline Management"], "industries": ["Grid Storage", "Renewable Energy"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2017, "materials": ["Tier-1 Lithium-Ion Battery Systems", "Container-Based BESS Enclosures"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Powervault Ltd', 'A London-based home and commercial battery storage company founded in 2012, Powervault manufactures intelligent residential and commercial battery storage systems incorporating AI-powered SMARTSTOR energy management software. The company designs and produces its energy storage units from its London headquarters, targeting solar-paired storage and smart grid edge applications. Powervault raised over £3.8 million in investment to scale its battery storage technology.', '{"company_type": "Grid-Scale Energy Storage System Integrator", "website_url": "https://www.powervault.co.uk", "location": "London, UK", "certifications": ["ISO 9001", "MCS"], "capabilities": ["Residential Battery Storage System Manufacture", "Commercial Energy Storage Design", "AI Energy Management Software", "Solar-Paired Storage Integration", "Smart Grid Edge Storage"], "industries": ["Grid Storage", "Solar Energy", "Residential Energy"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2012, "materials": ["Lithium-Ion Cells", "BMS Electronics", "Smart Inverter Components"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Myenergi Ltd', 'Founded in 2016 by Lee Sutton and Jordan Brompton, Myenergi is an award-winning British designer and manufacturer of eco-smart home energy products headquartered in Stallingborough, Grimsby, with a 66,000 sq ft UK manufacturing facility. Their flagship Zappi EV charger is solar-compatible and one of the UK''s most popular home charge points, complemented by the Eddi power diverter and Libbi home battery. Myenergi has surpassed 500,000 unit sales and reports cumulative revenues exceeding £160 million.', '{"company_type": "EV Charging Equipment", "website_url": "https://www.myenergi.com", "location": "Stallingborough, Grimsby, Lincolnshire, UK", "certifications": ["ISO 9001", "OZEV Approved", "CE", "MCS"], "capabilities": ["Smart Solar-Compatible EV Charger Manufacture", "Home Battery Storage Production", "Solar PV Diverter Manufacturing", "Home Energy Management Systems", "V2H Ready Charger Development"], "industries": ["Electric Vehicles", "Solar Energy", "Residential Energy"], "lead_time": null, "min_order": null, "employees": "250+", "established": 2016, "materials": ["Power Electronics", "Enclosures", "Smart Metering Components"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'INDRA Renewable Technologies Ltd', 'A UK EV charger designer and manufacturer founded in 2013 and based in Malvern, Worcestershire. INDRA launched the world''s first domestic Vehicle-to-Grid (V2G) charger in 2018 and designs and builds all its products in the UK. Their Smart LUX and Smart PRO ranges combine fast charging with bidirectional V2G and V2H capability, making INDRA a pioneer in smart grid-interactive charging technology.', '{"company_type": "EV Charging Equipment", "website_url": "https://www.indra.co.uk", "location": "Malvern, Worcestershire, UK", "certifications": ["ISO 9001", "OZEV Approved", "CE", "OLEV Grant Eligible"], "capabilities": ["Smart EV Charger Design and Manufacture", "Vehicle-to-Grid (V2G) Charger Development", "Vehicle-to-Home (V2H) Bidirectional Charging", "Home Energy Management Integration", "Commercial EV Charging Solutions"], "industries": ["Electric Vehicles", "Smart Grid", "Residential Energy"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2013, "materials": ["Power Electronics", "Smart Metering ICs", "Enclosures"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'EO Charging Ltd', 'Founded in 2015 by Charlie Jardine and based in Stowmarket, Suffolk, EO Charging designs and manufactures smart EV charging hardware and fleet charging management software, having installed over 60,000 charge points across 35 countries. The company supplies major fleet operators including Amazon, DHL, and Tesco, and has grown from a Suffolk barn to one of the UK''s leading EV charge point manufacturers with 180 employees. EO specialises in scalable fleet and workplace charging solutions.', '{"company_type": "EV Charging Equipment", "website_url": "https://eocharging.com", "location": "Stowmarket, Suffolk, UK", "certifications": ["ISO 9001", "OZEV Approved", "CE"], "capabilities": ["Smart EV Charger Hardware Design", "Fleet Charging Management Software", "Commercial Workplace Charging Systems", "Scalable Charging Infrastructure", "OEM EV Charging Hardware Supply"], "industries": ["Electric Vehicles", "Fleet Electrification", "Commercial Transport"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 2015, "materials": ["Power Electronics", "Smart Communication Modules", "Enclosures"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Rolec Services Ltd', 'A multidivisional manufacturer based in Boston, Lincolnshire, with over 30 years of experience making the UK''s largest range of outdoor electrical solutions including smart AC and DC rapid EV charging points, marina service pedestals, and caravan electrical hook-ups. Rolec employs approximately 140 people in a purpose-built office, showroom, and factory complex and has manufactured and installed over 400,000 public and private charge points. The company was acquired by Swedish infrastructure group Sdiptech.', '{"company_type": "EV Charging Equipment", "website_url": "https://www.rolecserv.com", "location": "Boston, Lincolnshire, UK", "certifications": ["ISO 9001", "OZEV Approved", "CE"], "capabilities": ["AC Fast Charger Manufacture", "DC Rapid Charger Manufacture", "Marina Electrical Service Pedestals", "Caravan Park Electrical Hook-Ups", "Smart EV Charging Network Software"], "industries": ["Electric Vehicles", "Marine", "Leisure and Hospitality"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Power Electronics", "Galvanised Steel Enclosures", "Smart Metering Components"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


