INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Morgan Advanced Materials plc', 'Morgan Advanced Materials is a FTSE 250 multinational headquartered in Windsor, UK, with over 60 global sites and a dedicated Technical Ceramics business unit. They manufacture high-performance ceramic components for extreme environments including high-voltage insulators, CVD silicon carbide, and specialist alumina and zirconia formulations. Their Thermal Products division also produces ceramic fibre blankets, castable refractories, and microporous insulation under the Kaowool and Superwool brands.', '{"company_type": "Advanced Ceramics", "website_url": "https://www.morganadvancedmaterials.com", "location": "Windsor, Berkshire, UK", "certifications": ["ISO 9001", "AS9100", "ISO 14001", "IATF 16949"], "capabilities": ["CVD Silicon Carbide", "Ceramic Fibre Manufacturing", "High Voltage Insulator Production", "Refractory Castable Manufacture", "Microporous Insulation"], "industries": ["Aerospace", "Power Generation", "Electronics", "Defence", "Industrial Processing", "Medical"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1856, "materials": ["Alumina", "Zirconia", "Silicon Carbide", "Aluminium Nitride", "Ceramic Fibre", "Microporous Silica"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Almath Crucibles Ltd', 'Based in Newmarket, Suffolk and founded in 1996, Almath is a leading British manufacturer and global exporter of high-purity alumina crucibles and advanced ceramic components. They hold an extensive stock range and offer bespoke precision-machined parts designed in-house, supplying leading research institutions including the University of Cambridge, CERN, and MIT. They serve fusion energy, nuclear, semiconductor, and materials research sectors.', '{"company_type": "Advanced Ceramics", "website_url": "https://almathcrucibles.com", "location": "Newmarket, Suffolk, UK", "certifications": ["ISO 9001"], "capabilities": ["Alumina Crucible Manufacturing", "Precision Ceramic Machining", "Custom Ceramic Design", "High Purity Processing"], "industries": ["Nuclear", "Semiconductor", "Scientific Research", "Fusion Energy", "Pharmaceutical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1996, "materials": ["Alumina", "Zirconia", "ZTA", "MgO", "MACOR", "Quartz", "Boron Nitride", "Sapphire", "Aluminium Nitride"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Mantec Technical Ceramics Ltd', 'Headquartered in Stoke-on-Trent, Staffordshire, and with a heritage spanning over 50 years, Mantec Technical Ceramics is a specialist manufacturer of alumina-based porous ceramics, ceramic gas distribution components, and filtration media. A subsidiary of Mantec Group, the company consolidates the former Ceramic Gas Products, Fairey Filtration Systems, and Taylor Tunnicliff businesses. They serve aerospace, EV automotive, food and drink, and wastewater treatment industries.', '{"company_type": "Advanced Ceramics", "website_url": "https://mantectechnicalceramics.com", "location": "Stoke-on-Trent, Staffordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Porous Ceramic Manufacture", "Ceramic Filtration Media", "Gas Distribution Components", "Ceramic Extrusion"], "industries": ["Aerospace", "Automotive", "Water Treatment", "Food & Beverage", "Industrial Filtration"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Alumina", "Cordierite", "Silicon Carbide"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Capital Refractories Ltd', 'Capital Refractories is one of the largest independent refractory companies in the UK, having manufactured and supplied high-quality refractory products to metal melters for over 70 years. Based in Sheffield with approximately 250 employees across nine sites in the UK, US, Europe, China, and India, they specialise in refractory linings and technical ceramic products for metal melting, foundry, and cement industries. Their product range covers castables, bricks, and monolithic systems.', '{"company_type": "Refractory Materials", "website_url": "https://capital-refractories.com", "location": "Sheffield, South Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Refractory Brick Manufacture", "Castable Refractory Formulation", "Refractory Lining Installation", "Technical Ceramics Supply"], "industries": ["Metals & Foundry", "Cement", "Glass", "Aluminium Smelting", "Petrochemical"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": ["Alumina", "Silica", "Magnesia", "Monolithic Castables", "Refractory Bricks"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'John Moncrieff Ltd', 'Founded in 1865 in Perth, Scotland, John Moncrieff is one of the UK''s oldest and most established technical glass manufacturers. They supply precision-engineered glass components and materials including borosilicate, fused quartz, sapphire, soda-lime, aluminosilicate, and ceramic glass, serving optical, defence, laser, and telecommunications industries. The company played a pivotal historical role in the development of heat-resistant borosilicate glass.', '{"company_type": "Specialty Glass", "website_url": "https://www.johnmoncrieff.co.uk", "location": "Perth, Scotland, UK", "certifications": ["ISO 9001"], "capabilities": ["Precision Glass Fabrication", "Optical Component Manufacture", "Sight Glass Production", "Glass Rod and Tube Supply", "Custom Glass Design"], "industries": ["Optics", "Defence", "Telecommunications", "Laser", "Industrial Process"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1865, "materials": ["Borosilicate Glass", "Fused Quartz", "Sapphire Glass", "Aluminosilicate Glass", "Ceramic Glass", "Soda-Lime Glass"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cambridge Glassblowing Ltd', 'Established in 1977 in Cottenham, Cambridgeshire, Cambridge Glassblowing is one of the UK''s most advanced scientific glassblowing facilities. They design and manufacture custom borosilicate and silica quartz glassware to specification, from precision miniature components up to pilot plant reactor systems of 100 litres. Their ISO 9001 and 45001-certified operations serve pharmaceutical, chemical, and scientific research sectors. The company was acquired by AGI in recent years.', '{"company_type": "Specialty Glass", "website_url": "https://www.cambridge-glassblowing.com", "location": "Cottenham, Cambridgeshire, UK", "certifications": ["ISO 9001", "ISO 45001"], "capabilities": ["Scientific Glassblowing", "Custom Glassware Design", "Borosilicate Fabrication", "Quartz Silica Fabrication", "Glass Reactor Systems"], "industries": ["Pharmaceutical", "Chemical Processing", "Scientific Research", "Semiconductor", "Academic"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1977, "materials": ["Borosilicate Glass", "Fused Quartz / Silica"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Robson Scientific Ltd', 'Established in 1988 and based in Sawbridgeworth, Hertfordshire, Robson Scientific is a specialist manufacturer of high-purity fused quartz and silica scientific glassware and components. Using industrial glassblowing techniques and lathe-drawn quartz tubing to close tolerances, they supply the semiconductor, optical fibre, water sterilisation, and lamp industries with 99.995% SiO2 fused quartz products. They offer a full technical advisory service alongside their manufacturing.', '{"company_type": "Specialty Glass", "website_url": "https://www.robsonscientific.co.uk", "location": "Sawbridgeworth, Hertfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Quartz Tubing Manufacture", "Fused Silica Fabrication", "Close-Tolerance Lathe Drawing", "Scientific Glassblowing"], "industries": ["Semiconductor", "Optical Fibre", "Water Sterilisation", "Lighting", "Laboratory"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1988, "materials": ["Fused Quartz (99.995% SiO2)", "Fused Silica"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Permabond Engineering Adhesives Ltd', 'Headquartered in Colden Common, Winchester, Hampshire, Permabond is a leading manufacturer of engineering adhesives with a history in the industry since the 1960s. Their product portfolio covers cyanoacrylates, structural acrylics, anaerobics, epoxies, polyurethanes, UV-cure adhesives, and MS-polymer-based systems. They hold approvals for aerospace (including Mil-Spec), automotive, electronics, medical device manufacture, and oil and gas applications.', '{"company_type": "Industrial Adhesives", "website_url": "https://www.permabond.co.uk", "location": "Winchester, Hampshire, UK", "certifications": ["ISO 9001", "ISO 13485"], "capabilities": ["Adhesive Formulation", "Cyanoacrylate Manufacturing", "Structural Acrylic Manufacture", "Anaerobic Sealant Production", "UV Cure Adhesive Development"], "industries": ["Aerospace", "Automotive", "Electronics", "Medical", "Oil & Gas", "Defence"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Cyanoacrylate", "Epoxy", "Acrylic", "Anaerobic", "Polyurethane", "MS Polymer"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
