INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Intertronics Ltd', 'Based in Kidlington, Oxfordshire and founded in 1979, Intertronics is a specialist distributor and technical partner for adhesives, encapsulants, potting compounds, conformal coatings, and dispensing equipment for high-technology assembly. With more than 30 years of application engineering experience and a Technology Centre near Oxford, they serve medical device, electronics, aerospace, and precision engineering manufacturers across the UK. Their ''Adhere Academy'' training and seminars are industry-recognised.', '{"company_type": "Industrial Adhesives", "website_url": "https://www.intertronics.co.uk", "location": "Kidlington, Oxfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Adhesive Application Engineering", "Potting and Encapsulation", "UV Curing Systems", "Robotic Dispensing", "Conformal Coating"], "industries": ["Electronics", "Medical Devices", "Aerospace", "Photonics", "Defence"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1979, "materials": ["Epoxy", "Silicone", "Polyurethane", "UV Cure", "Cyanoacrylate"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Teer Coatings Ltd', 'Founded in 1985 and employing over 50 staff, Teer Coatings is based in Worcestershire and is the UK''s leading independent PVD coating services company and equipment manufacturer. Using magnetron sputtering technology, they provide hard coatings (TiN, CrN, CrAlN), low-friction coatings (MoST, Graphit-iC, DLC), and precious metal coatings (Au, Ag, Pt, Ru) for aerospace, motorsport, sensors, and cutting tool industries. They also design and manufacture PVD coating systems for sale.', '{"company_type": "PVD Coatings", "website_url": "https://www.teercoatings.co.uk", "location": "Droitwich, Worcestershire, UK", "certifications": ["ISO 9001"], "capabilities": ["Magnetron Sputtering", "PVD Hard Coating", "DLC Coating", "Precious Metal Thin Film", "Low Friction Coating", "Coating Equipment Manufacture"], "industries": ["Aerospace", "Motorsport", "Sensors", "Cutting Tools", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1985, "materials": ["TiN", "CrN", "CrAlN", "CrAlTiN", "DLC", "MoST", "Gold", "Silver", "Platinum", "Ruthenium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Ionbond UK Ltd (Consett Coating Centre)', 'Established in Consett, County Durham in 1982, Ionbond UK operates one of the most advanced PVD and CVD coating facilities in the UK, serving as the UK headquarters of the international Ionbond IHI Group. The Consett facility houses eight coating chambers including the three largest PVD chambers in the UK, offering cathodic arc, magnetron sputtering, HIPIMS, and PACVD (diamond-like carbon) processes. Certified to ISO 9001, AS9100, Nadcap Merit Status, it serves aerospace, medical, oil and gas, and semiconductor sectors.', '{"company_type": "PVD Coatings", "website_url": "https://www.ionbond.com/contacts-locations/great-britain/", "location": "Consett, County Durham, UK", "certifications": ["ISO 9001", "AS9100", "Nadcap"], "capabilities": ["PVD Coating", "CVD Coating", "PACVD DLC Coating", "HIPIMS", "Cathodic Arc Deposition"], "industries": ["Aerospace", "Medical", "Oil & Gas", "Semiconductor", "Automotive"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1982, "materials": ["TiN", "TiAlN", "CrN", "DLC", "Tribobond Coatings"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Wallwork Cambridge Ltd', 'Part of the Wallwork Group — the UK''s largest independent thermal treatment organisation — Wallwork Cambridge is the PVD/CVD coating and vacuum services division based in Cambridge. They offer Nitron Flight aerospace PVD coatings, plasma nitriding, vacuum brazing, and bespoke coating development for mission-critical aerospace components. Holding AS9100, Nadcap, and multiple aerospace prime approvals including Rolls-Royce and Airbus, they serve defence, aerospace, and high-performance engineering customers.', '{"company_type": "PVD Coatings", "website_url": "https://wallworkht.co.uk", "location": "Cambridge, Cambridgeshire, UK", "certifications": ["AS9100", "ISO 9001", "Nadcap", "ISO 14001"], "capabilities": ["PVD Coating", "CVD Coating", "Plasma Nitriding", "Vacuum Brazing", "Bespoke Coating Development"], "industries": ["Aerospace", "Defence", "Motorsport", "Energy", "Medical"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": ["TiN", "TiAlN", "CrN", "DLC", "Aluminium Nitride Coatings"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Hardide Coatings Ltd', 'Based in Bicester, Oxfordshire, Hardide Coatings is the global leader in nano-structured CVD tungsten carbide/tungsten metal matrix composite coatings. Their Hardide-T and Hardide-A coatings provide ultra-high hardness (1100–1600 HV) combined with exceptional toughness and are Airbus-qualified as a hard chrome replacement. The UK facility is certified to ISO 9001, AS9100, Nadcap, and ISO 14001, with prime approvals from Airbus, Leonardo, BAE Systems, and Lockheed Martin.', '{"company_type": "CVD Coatings", "website_url": "https://www.hardide.com", "location": "Bicester, Oxfordshire, UK", "certifications": ["ISO 9001", "AS9100", "Nadcap", "ISO 14001"], "capabilities": ["CVD Tungsten Carbide Coating", "Hard Chrome Replacement", "Wear-Resistant Coating", "Corrosion-Resistant Coating", "Complex Geometry Coating"], "industries": ["Aerospace", "Oil & Gas", "Defence", "Power Generation", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": ["Tungsten Carbide", "Tungsten Metal Matrix Composite"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Plasma Coatings Ltd (PCL)', 'Operating since 1971 from Tideswell, Derbyshire, Plasma Coatings Limited is a specialist thermal spray contractor to the aerospace, commercial, and biomedical industries. They apply metal, ceramic, and composite coatings using plasma spray, flame spray, and HVOF processes on components up to 1.5 metres in diameter using robotic spray facilities. PCL holds AS9100 certification and has maintained Nadcap Merit Status continuously since 2005, holding OEM approvals from multiple aerospace primes.', '{"company_type": "Thermal Spray Coatings", "website_url": "https://plasma-group.co.uk", "location": "Tideswell, Derbyshire, UK", "certifications": ["AS9100", "Nadcap", "ISO 9001"], "capabilities": ["Plasma Spray Coating", "HVOF Coating", "Flame Spray Coating", "Robotic Spray Application", "Coating Micro-evaluation"], "industries": ["Aerospace", "Biomedical", "Industrial", "Defence"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1971, "materials": ["Alumina", "Zirconia", "Tungsten Carbide", "Chromium Carbide", "MCrAlY Bond Coats", "Stellite"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Zircotec Ltd', 'Based in Abingdon, Oxfordshire, and originating from the UK Atomic Energy Authority at Harwell, Zircotec is a specialist manufacturer of plasma-sprayed ceramic thermal barrier coatings and flexible ceramic heat shields. Their ThermoHold and ZircoFlex products are used extensively in Formula 1, WRC, aerospace, oil and gas, marine, and clean energy sectors. The company supplies customers including all major F1 teams, and has expanded into offshore engineering and space applications.', '{"company_type": "Thermal Spray Coatings", "website_url": "https://zircotec.com", "location": "Abingdon, Oxfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Plasma Spray Ceramic Coating", "Thermal Barrier Coating", "Flexible Ceramic Heat Shield Manufacture", "Coloured Ceramic Coatings"], "industries": ["Motorsport", "Aerospace", "Oil & Gas", "Marine", "Clean Energy"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1994, "materials": ["Zirconia", "Alumina", "MCrAlY Bond Coats", "Ceramic Composite"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Surface Technology UK Ltd', 'With over 70 years of industry experience, Surface Technology UK is the UK''s leading independent provider of electroless nickel plating, PTFE coatings, HVOF thermal spray, fluoropolymer coatings, and anti-corrosion treatments. Operating from multiple UK sites and holding AS9100 aerospace certification, they serve aerospace, oil and gas, chemical processing, and defence customers with over 200 coating options. They are an approved SIFCO Process provider for selective electroplating.', '{"company_type": "Specialty Coatings", "website_url": "https://www.surfacetechnology.co.uk", "location": "Nottingham, Nottinghamshire, UK", "certifications": ["ISO 9001", "AS9100", "ISO 14001"], "capabilities": ["Electroless Nickel Plating", "HVOF Thermal Spray", "Plasma Spray", "PTFE Coating", "Fluoropolymer Coating", "SIFCO Selective Plating"], "industries": ["Aerospace", "Oil & Gas", "Defence", "Chemical Processing", "Pharmaceutical"], "lead_time": null, "min_order": null, "employees": "50-249", "established": null, "materials": ["Electroless Nickel", "PTFE", "Tungsten Carbide", "Chromium Carbide", "Fluoropolymer"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Keronite International Ltd', 'Founded in 2000 and headquartered in Haverhill, Suffolk, Keronite is the world leader in Plasma Electrolytic Oxidation (PEO) surface treatment for aluminium, magnesium, and titanium alloys. Their patented PEO process converts the metal surface into a hard, dense ceramic oxide layer up to 2000 HV — harder than steel — providing outstanding corrosion protection, wear resistance, and thermal stability. AS9100-certified with space applications validated through the UK Space Agency, they serve aerospace, space, defence, and automotive sectors.', '{"company_type": "Advanced Surface Coatings", "website_url": "https://www.keronite.com", "location": "Haverhill, Suffolk, UK", "certifications": ["AS9100", "ISO 9001"], "capabilities": ["Plasma Electrolytic Oxidation (PEO)", "Ceramic Oxide Coating on Light Alloys", "Optical Coating for Space Structures", "Hard Anodising Alternative"], "industries": ["Aerospace", "Space", "Defence", "Automotive", "Electronics"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2000, "materials": ["Alumina (on Aluminium)", "Periclase (on Magnesium)", "Rutile/Anatase (on Titanium)"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Indestructible Paint Ltd', 'Established in 1978 in Birmingham, Indestructible Paint is an independent AS9100 Rev D-certified manufacturer of high-performance specialty surface coatings for aerospace engines, airframes, and accessories. Their product range includes engine coatings (Rockhard, Ipcote, Ipseal), high-temperature coatings, intumescent fire retardant coatings, two-pack polyurethane and epoxy systems, and low-VOC formulations. They are a major supplier to international aerospace and defence OEMs.', '{"company_type": "Specialty Coatings", "website_url": "https://indestructible.co.uk", "location": "Birmingham, West Midlands, UK", "certifications": ["AS9100 Rev D", "ISO 9001"], "capabilities": ["Aerospace Engine Coating Formulation", "High Temperature Coating Manufacture", "Intumescent Coating Production", "Low VOC Coating Development"], "industries": ["Aerospace", "Defence", "Marine"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1978, "materials": ["Polyurethane", "Epoxy", "High Temperature Silicone", "Intumescent Systems"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Impreglon UK Ltd', 'Established in 1986 and part of the global Impreglon Group, Impreglon UK is a leading UK applicator of PTFE, Teflon, Xylan, fluoropolymer, and thermal spray coatings to customer components. They hold ISO 9001 and ISO 14001 accreditation and offer the full Teflon, Xylan, and Greblon ranges alongside PTFE, PFA, FEP, ETFE, and ECTFE (Halar) coatings. They serve petrochemical, food processing, pharmaceutical, and industrial sectors requiring non-stick, chemical-resistant, or thermally sprayed surfaces.', '{"company_type": "Specialty Coatings", "website_url": "https://www.impreglon.co.uk", "location": "Kirkby-in-Ashfield, Nottinghamshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["PTFE Coating Application", "Fluoropolymer Coating", "Thermal Spray Coating", "Non-Stick Coating", "Chemical Resistant Coating"], "industries": ["Petrochemical", "Food Processing", "Pharmaceutical", "Industrial", "Aerospace"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1986, "materials": ["PTFE", "PFA", "FEP", "ETFE", "ECTFE (Halar)", "Xylan"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Anderman Ceramics Ltd', 'Founded in 1947 and headquartered in Kidderminster, Worcestershire, Anderman Ceramics is a leading international distributor and technical ceramics specialist supplying over 1,000 customers including major aerospace, power generation, and automotive accounts. They provide advanced ceramics and refractories from alumina to zirconia, with extensive knowledge of industrial ceramic processes and an ISO 9001:2015-certified global supply chain covering the UK, USA, France, China, and Southeast Asia. Their earthwaterfire.com platform was one of the first e-commerce sites in the ceramics industry.', '{"company_type": "Advanced Ceramics", "website_url": "https://www.earthwaterfire.com", "location": "Kidderminster, Worcestershire, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Technical Ceramics Distribution", "Custom Ceramic Component Sourcing", "Refractory Product Supply", "Application Engineering"], "industries": ["Aerospace", "Power Generation", "Automotive", "Glass", "Industrial"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1947, "materials": ["Alumina", "Zirconia", "Silicon Carbide", "Silicon Nitride", "Boron Nitride", "Mullite"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Lucideon Ltd', 'Based in Stoke-on-Trent, Staffordshire — the historic UK ceramics heartland — Lucideon (formerly CERAM, formerly the British Ceramic Research Association) is an independent materials development, testing, consultancy, and advanced ceramics commercialisation company. They operate state-of-the-art facilities including the AMRICC Centre in Stoke-on-Trent, serving healthcare, aerospace, nuclear, construction, and power generation sectors with materials testing, failure analysis, and new product development. Their advanced ceramics capability spans alumina, zirconia, silicon carbide, and specialty ceramic systems.', '{"company_type": "Advanced Ceramics", "website_url": "https://www.lucideon.com", "location": "Stoke-on-Trent, Staffordshire, UK", "certifications": ["ISO 9001", "ISO 17025"], "capabilities": ["Advanced Ceramics Development", "Materials Testing & Characterisation", "Ceramic Failure Analysis", "New Product Development", "Pilot Scale Manufacturing"], "industries": ["Healthcare", "Aerospace", "Nuclear", "Construction", "Power Generation"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1948, "materials": ["Alumina", "Zirconia", "Silicon Carbide", "Bioceramics", "Refractory Ceramics"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pyrotek TAB Refractory Services Ltd', 'Based near Matlock, Derbyshire, and now operating as part of the global Pyrotek group following acquisition, TAB Refractory Services has over 50 years of experience as a world leader in aluminium furnace refractory lining and maintenance. They have installed more than 1,100 aluminium furnace linings in over 30 countries, offering full design, installation, and maintenance of refractory systems for reverberatory, tower, rotary, and other furnace types. They serve aluminium primary and secondary smelters, foundries, and die casters globally.', '{"company_type": "Refractory Materials", "website_url": "https://www.pyrotek.com/services/refractory/", "location": "Matlock, Derbyshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Refractory Furnace Lining", "Refractory Installation", "Furnace Design Consultancy", "Refractory Maintenance", "Emergency Relining"], "industries": ["Aluminium Smelting", "Foundry", "Die Casting", "Non-Ferrous Metals"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1974, "materials": ["Castable Refractory", "Refractory Brick", "Ceramic Fibre", "Monolithic Refractory"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Henkel Ltd (Adhesive Technologies)', 'Operating from Hemel Hempstead, Hertfordshire as the UK operations hub of the global Henkel group, Henkel Adhesive Technologies is the world market leader in engineering adhesives, sealants, and functional coatings under brands including Loctite, Bonderite, and Teroson. Their UK facility manufactures and distributes industrial adhesives for structural bonding, thread locking, gasketing, retaining, and specialty electronic applications. They serve virtually every manufacturing sector including aerospace, automotive, electronics, and renewable energy.', '{"company_type": "Industrial Adhesives", "website_url": "https://www.henkel.co.uk", "location": "Hemel Hempstead, Hertfordshire, UK", "certifications": ["ISO 9001", "ISO 14001", "AS9100"], "capabilities": ["Structural Adhesive Manufacture", "Thread Locking Compound Production", "Anaerobic Gasketing", "Electronic Encapsulant Supply", "Specialty Sealant Development"], "industries": ["Aerospace", "Automotive", "Electronics", "Renewable Energy", "Industrial"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": ["Epoxy", "Acrylic", "Anaerobic", "Cyanoacrylate", "Polyurethane", "Silicone"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


