INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sterling Thermal Technology Ltd', 'Founded in 1904 and based in Aylesbury, Buckinghamshire, Sterling TT designs and manufactures bespoke shell-and-tube, compact fin, and single-tube heat exchangers from a 5,000 sq m facility. They serve clients across power generation, renewable energy, oil and gas, defence, marine, and chemical sectors in over 50 countries. The company designs to ASME VIII, BS5500, TEMA, and CODAP standards and works with inspection authorities including Lloyd''s Register, DNV, and Bureau Veritas.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://www.sterlingtt.com", "location": "Aylesbury, Buckinghamshire, UK", "certifications": ["ISO 9001:2015", "ISO 45001:2018", "ISO 14001:2014", "TEMA", "ASME VIII"], "capabilities": ["Shell and Tube Heat Exchanger Design", "Compact Fin Heat Exchanger Manufacturing", "Bespoke Thermal Engineering", "Pressure Vessel Design", "In-house Thermal Simulation"], "industries": ["Power Generation", "Renewable Energy", "Oil and Gas", "Defence", "Marine", "Chemical"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1904, "materials": ["Stainless Steel", "Carbon Steel", "Nickel Alloys", "Copper", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Thermex Ltd', 'Established in Redditch, Worcestershire in 1979, Thermex is a leading UK manufacturer of shell-and-tube, air-cooled, and brazed plate heat exchangers serving marine, industrial hydraulics, defence, off-highway, and EV/hybrid markets. The company employs over 60 staff and holds ASME VIII accreditation and PED compliance. In recent years they have expanded into EV and hybrid vehicle cooling projects.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://www.thermex.co.uk", "location": "Redditch, Worcestershire, UK", "certifications": ["ISO 9001", "ISO 14001", "PED 2014/68/EU", "ASME VIII", "TEMA", "Cyber Essentials"], "capabilities": ["Shell and Tube Heat Exchanger Manufacturing", "Air-Cooled Heat Exchanger Manufacturing", "Brazed Plate Heat Exchanger Manufacturing", "Hydraulic Oil Cooling", "EV Cooling Systems"], "industries": ["Marine", "Industrial Hydraulics", "Defence", "Off-Highway and Construction", "Electric Vehicles", "Power Generation"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1979, "materials": ["Copper", "Aluminium", "Stainless Steel", "Carbon Steel", "Brass"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Therco-Serck Ltd', 'Based in Sheffield with a heritage tracing back to the early 1900s, Therco-Serck designs and manufactures TEMA-type shell-and-tube heat exchangers in steel, nickel, and corrosion-resistant alloys for the marine, power generation, petrochemical, and oil and gas industries. Their Integrated Management System is approved by Lloyd''s Register. The company operates multiple UK sites and combines holistic design activity with advanced manufacturing.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://www.thercoserckhtx.com", "location": "Sheffield, South Yorkshire, UK", "certifications": ["ISO 9001", "OHSAS 18001", "TEMA", "Lloyd''s Register Approved"], "capabilities": ["TEMA Shell and Tube Heat Exchanger Manufacturing", "Corrosion-Resistant Alloy Fabrication", "Marine Cooling Equipment", "Industrial Heat Transfer Design", "Heat Exchanger Repair and Servicing"], "industries": ["Marine", "Power Generation", "Petrochemical", "Oil and Gas", "Rail", "Steel"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1900, "materials": ["Carbon Steel", "Stainless Steel", "Nickel Alloys", "Duplex Steel", "Titanium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Turnbull & Scott (Engineers) Ltd', 'Founded in 1933 and headquartered in Hawick, Scottish Borders, Turnbull & Scott specialises in custom extended-surface heat exchangers including spiral-fin and plate-fin designs, steam condensers, economisers, and heat recovery units. They have 90+ years of expertise serving nuclear, oil and gas, power generation, and industrial sectors, with active involvement in the Hinkley Point C nuclear new build project.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://www.turnbull-scott.co.uk", "location": "Hawick, Scottish Borders, UK", "certifications": ["ISO 9001", "Passport to Safety", "Gas Safe"], "capabilities": ["Extended Surface Heat Exchanger Manufacturing", "Spiral-Fin Coil Design", "Steam Condenser Manufacturing", "Economiser Design", "Nuclear-Grade Heat Exchangers", "Heat Recovery Systems"], "industries": ["Nuclear", "Power Generation", "Oil and Gas", "Chemical", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1933, "materials": ["Carbon Steel", "Stainless Steel", "Alloy Steel", "Copper"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'E J Bowman (Birmingham) Ltd', 'Established in 1919 in Birmingham, Bowman is a leading UK manufacturer of shell-and-tube heat exchangers and oil coolers, producing products from a 6,000 sq m facility in Chester Street, Aston. Their product range spans marine engineering, hydraulic equipment, cogeneration (CHP) systems, engine testing, and swimming pool heating. The company has over 100 years of continuous heat transfer experience and exports globally.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://ej-bowman.com", "location": "Birmingham, West Midlands, UK", "certifications": ["ISO 9001:2015", "Lloyd''s Register", "Bureau Veritas"], "capabilities": ["Shell and Tube Heat Exchanger Manufacturing", "Oil Cooler Manufacturing", "Marine Heat Exchangers", "CHP System Heat Exchangers", "Engine Test Cell Cooling", "Swimming Pool Heat Exchangers"], "industries": ["Marine", "Hydraulics", "Power Generation (CHP)", "Automotive Testing", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1919, "materials": ["Copper", "Brass", "Stainless Steel", "Carbon Steel", "Cupro-Nickel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'UK Exchangers Ltd', 'Founded in 1991 and based in Olney, Buckinghamshire, UK Exchangers specialises in the design and manufacture of a broad range of heat exchangers for industrial, food and dairy, hygienic, refrigeration, HVAC, and marine applications. Products include gasketed and brazed plate, finned tube coil, corrugated tube, all-welded plate, and air-to-air heat exchangers. The company is ISO 9001 and ISO 14001 certified and supplies both from stock and to bespoke order.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://www.uk-exchangers.com", "location": "Olney, Buckinghamshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Plate Heat Exchanger Supply", "Brazed Plate Heat Exchanger Manufacturing", "Finned Tube Coil Manufacturing", "Air-to-Air Heat Exchanger Supply", "All-Welded Plate Heat Exchangers"], "industries": ["Food and Dairy", "HVAC", "Refrigeration", "Marine", "Industrial", "Agriculture"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1991, "materials": ["Stainless Steel", "Copper", "Titanium", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HRS Heat Exchangers Ltd', 'Founded in 1981 and headquartered in Watford, Hertfordshire, HRS Heat Exchangers specialises in corrugated shell-and-tube, scraped surface, and plate heat exchangers for food and beverage, pharmaceutical, water treatment, chemical, and biogas industries. With 78 employees and offices worldwide, they provide complete thermal process systems. The group has production capacity in Europe and Asia and technical offices across six continents.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://www.hrs-heatexchangers.com", "location": "Watford, Hertfordshire, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Corrugated Tube Heat Exchanger Manufacturing", "Scraped Surface Heat Exchanger Manufacturing", "Plate Heat Exchanger Design", "Hygienic Process Design", "Aseptic Filling Systems", "CIP Package Design"], "industries": ["Food and Beverage", "Pharmaceutical", "Water Treatment", "Chemical", "Biogas and Energy", "Environmental"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1981, "materials": ["Stainless Steel", "Titanium", "Duplex Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Spiro-Gills Thermal Products Ltd', 'With roots dating to 1946, Spiro-Gills manufactures air-cooled heat exchangers, process and engine coolers, and finned tube from their site in Stafford, operating as part of the DMI Group. They are the only UK manufacturer of High Frequency Welded Finned Tube and serve oil refineries, petrochemical plants, power stations, and gas production facilities worldwide. ASME-accredited welders and ISO 9001:2015 certification underpin their quality systems.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://spiro-gills.com", "location": "Stafford, Staffordshire, UK", "certifications": ["ISO 9001:2015", "ASME Welding Certification", "PED"], "capabilities": ["Air-Cooled Heat Exchanger Manufacturing", "High Frequency Welded Finned Tube Manufacturing", "Shell and Tube Heat Exchanger Manufacturing", "Process Cooler Design", "Engine Cooler Manufacturing"], "industries": ["Oil and Gas", "Petrochemical", "Power Generation", "Fertiliser", "Gas Processing"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1946, "materials": ["Carbon Steel", "Stainless Steel", "Aluminium", "Copper", "Alloy Steels"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Paul & Loughran Ltd', 'Incorporated in 1978 and located in Consett, County Durham, Paul & Loughran is a process plant fabrication specialist offering complete design, fabrication, and assembly of shell-and-tube heat exchangers, pressure vessels, gas filters, and pig traps for the oil, gas, and petrochemical industries. They serve major operators both domestically and overseas with over 40 years of experience in demanding process environments.', '{"company_type": "Heat Exchanger and Pressure Vessel Manufacturing", "website_url": "https://pl-uk.com", "location": "Consett, County Durham, UK", "certifications": ["ISO 9001", "PED", "TEMA"], "capabilities": ["Shell and Tube Heat Exchanger Manufacturing", "Pressure Vessel Fabrication", "Gas Filter Manufacturing", "Pig Trap Fabrication", "Skid Module Assembly"], "industries": ["Oil and Gas", "Petrochemical", "Chemical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1978, "materials": ["Carbon Steel", "Stainless Steel", "Alloy Steel", "Duplex Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Columbia-Staver Limited', 'Established in 1972 and headquartered in Wickford, Essex, Columbia-Staver is a full-service thermal management solutions provider specialising in heat pipes, vapour chambers, liquid cold plates, and natural and forced convection heat sinks. With 50 years of experience, they serve aerospace, EV, battery, space, military, and consumer electronics sectors across Europe and North America. UK design and manufacturing is augmented by lower-cost production capability in China.', '{"company_type": "Thermal Management Systems", "website_url": "https://www.columbia-staver.co.uk", "location": "Wickford, Essex, UK", "certifications": ["ISO 9001:2015", "ISO 14001:2015"], "capabilities": ["Heat Pipe Design and Manufacturing", "Vapour Chamber Assembly", "Liquid Cold Plate Manufacturing", "Heat Sink Manufacturing", "Sintered Powder Metal Wick Fabrication", "Ultra-Flat Heat Pipe Manufacturing"], "industries": ["Electric Vehicles", "Aerospace", "Space", "Military", "Consumer Electronics", "Battery Systems"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1972, "materials": ["Copper", "Aluminium", "Sintered Powder Metal"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'cTech Ltd', 'Founded in 2003 and based in Crondall, Hampshire, cTech provides enabling thermal management technologies to OEMs and research establishments. Their product portfolio includes heat pipe assemblies, thermoelectric coolers (Peltier devices), water chillers, thermal interface materials, and custom thermal design services. They serve electronics cooling and specialist industrial markets, offering both standard and fully custom solutions.', '{"company_type": "Thermal Management Systems", "website_url": "https://ctech.co.uk", "location": "Crondall, Hampshire, UK", "certifications": [], "capabilities": ["Heat Pipe Solution Design", "Thermoelectric Cooler Supply", "Water Chiller Supply", "Thermal Interface Material Supply", "Custom Thermal Design", "Two-Phase Heat Transfer Engineering"], "industries": ["Electronics", "Defence", "Telecommunications", "Industrial", "Research and Development"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2003, "materials": ["Copper", "Aluminium", "Phase Change Materials"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Grayson Thermal Systems', 'Founded in Birmingham in 1978 and based in Tyseley, Grayson Thermal Systems designs and manufactures OE and aftermarket heating and cooling products for zero-emission vehicles, buses, coaches, commercial vehicles, off-road equipment, and rail applications. Over 70% of their current production is for BEV and FCEV applications. They launched their Battery Thermal Management System (BTMS) in 2014 and have manufacturing operations in both the UK and the USA.', '{"company_type": "Thermal Management Systems", "website_url": "https://www.graysonts.com", "location": "Tyseley, Birmingham, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Battery Thermal Management System Design", "EV Cooling Module Manufacturing", "Bus and Coach HVAC Manufacturing", "Fuel Cell Thermal Management", "Aftermarket Thermal Servicing"], "industries": ["Electric Vehicles", "Fuel Cell Vehicles", "Bus and Coach", "Commercial Vehicles", "Rail", "Defence", "Agriculture"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1978, "materials": ["Aluminium", "Copper", "Stainless Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HiETA Technologies Ltd', 'Founded in 2011 and based at the Bristol and Bath Science Park, HiETA Technologies is a product design and production company exploiting metal additive manufacturing (3D printing) to produce compact, lightweight heat exchangers, recuperators, and thermal management components. Their AM-produced parts are typically 40% lighter and smaller than conventionally manufactured equivalents. Key programmes include heat exchangers for the Airbus RACER helicopter and investment from Meggitt PLC.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://www.hieta.co.uk", "location": "Bristol, UK", "certifications": ["AS9100"], "capabilities": ["Additive Manufacturing of Heat Exchangers", "Compact Recuperator Design", "Turbo-Machinery Component Production", "Waste Heat Recovery System Design", "Fuel Cell Heat Exchanger Manufacturing", "Thermal Simulation"], "industries": ["Aerospace", "Defence", "Automotive", "Motorsport", "Energy", "Sustainable Power"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 2011, "materials": ["Aluminium", "Titanium", "Stainless Steel", "Nickel Superalloys"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Senior Aerospace Thermal Engineering Ltd', 'Founded in 1988 and based in Royston, Hertfordshire (acquired by Senior plc in 2013), this aerospace-focused company specialises in hot and cold formed components, complex fabricated assemblies, and thermal insulation heat shields and systems for aero engine and airframe OEMs and Tier 1 suppliers globally. They operate from a purpose-built 6,500 sq m facility and hold AS9100 Rev D certification with NADCAP accreditation for special processes.', '{"company_type": "Aerospace Thermal Management", "website_url": "https://www.thermalengineering.co.uk", "location": "Royston, Hertfordshire, UK", "certifications": ["AS9100 Rev D", "NADCAP"], "capabilities": ["Thermal Insulation Heat Shield Manufacturing", "Hot and Cold Formed Component Production", "Complex Fabricated Assemblies", "Ducts and Panel Manufacturing", "Fire and Heat Shield Systems", "LPT Insulation Blankets"], "industries": ["Aerospace", "Defence"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1988, "materials": ["Titanium", "Stainless Steel", "Aluminium", "Composite Materials"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oxford Cryosystems Ltd', 'Launched in 1985 from Oxford University and based in Oxfordshire, Oxford Cryosystems is the world''s market-leading manufacturer of cryogenic cooling devices for scientific research, particularly X-ray diffraction and crystallography. Their Cryostream product line is the universal standard for sample cooling in diffraction experiments globally. The company is a subsidiary of Judges Scientific and employs around 34 staff.', '{"company_type": "Cryogenic Equipment Manufacturing", "website_url": "https://oxcryo.com", "location": "Oxfordshire, UK", "certifications": [], "capabilities": ["Cryogenic Cooler Design and Manufacturing", "Gas Flow Cryostat Manufacturing", "Gifford-McMahon Cryocooler Supply", "Scientific Instrument Development", "Cryogenic Control Software"], "industries": ["Scientific Research", "Crystallography", "Pharmaceutical", "Astrophysics"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1985, "materials": ["Stainless Steel", "Aluminium", "Copper"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ICEoxford Ltd', 'Founded in 2004 and based in Witney, Oxfordshire, ICEoxford designs and manufactures specialist ultra-low temperature and high magnetic field cryogenic systems for scientific, quantum computing, and neutron scattering applications. They have supplied state-of-the-art dilution refrigerator systems to the UK National Quantum Computing Centre and received Institute of Physics Business Innovation Awards. The company serves global research institutions and hi-tech industry.', '{"company_type": "Cryogenic Equipment Manufacturing", "website_url": "https://www.iceoxford.com", "location": "Witney, Oxfordshire, UK", "certifications": [], "capabilities": ["Dilution Refrigerator Manufacturing", "Ultra-Low Temperature System Design", "High Magnetic Field Cryostat Supply", "Quantum Computing Cryogenic Systems", "Custom Cryogenic Engineering"], "industries": ["Quantum Computing", "Scientific Research", "Defence", "Neutron Scattering"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2004, "materials": ["Stainless Steel", "Copper", "Aluminium"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Airedale International Air Conditioning Ltd', 'Founded in 1974 and headquartered in Leeds, West Yorkshire (now operating as Airedale by Modine, part of Modine Manufacturing Company), Airedale is a world leader in critical precision cooling solutions for data centres, healthcare, nuclear, and telecommunications industries. They employ over 425 staff globally and manufacture precision air conditioning units, chillers, condensers, dry coolers, and air handling units from their UK facilities including a new 14.6-acre Bradford site.', '{"company_type": "Cooling Systems Manufacturing", "website_url": "https://www.airedale.com", "location": "Leeds, West Yorkshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Precision Air Conditioning Manufacturing", "Chiller Manufacturing", "Condenser and Dry Cooler Design", "Data Centre Cooling Systems", "Building Management System Integration", "Air Handling Unit Manufacturing"], "industries": ["Data Centres", "Healthcare", "Nuclear", "Telecommunications", "Pharmaceutical", "Commercial"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1974, "materials": ["Aluminium", "Copper", "Stainless Steel", "Carbon Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Elmatic (Cardiff) Ltd', 'Founded in 1949 and based in Rumney, Cardiff, Elmatic is one of the UK''s leading manufacturers of industrial electric heating elements, operating from a 45,000 sq ft factory with approximately 50 employees. Their product range includes cartridge heaters, immersion heaters, duct heaters, PTC heaters, mica heaters, and bespoke custom assemblies. They serve automotive, aerospace, food processing, plastics, and oil and gas industries.', '{"company_type": "Industrial Heating Element Manufacturing", "website_url": "https://www.elmatic.co.uk", "location": "Rumney, Cardiff, Wales, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Cartridge Heater Manufacturing", "Immersion Heater Manufacturing", "Air Duct Heater Manufacturing", "PTC Heater Supply", "Bespoke Heating Element Design", "Strip and Band Heater Manufacturing"], "industries": ["Automotive", "Aerospace", "Food Processing", "Plastics", "Oil and Gas", "Pharmaceutical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1949, "materials": ["Nichrome", "Stainless Steel", "Copper", "Mica", "Ceramic"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Thermaglow Ltd', 'Founded in 1957 in Winterton-on-Sea and now based in Great Yarmouth, Norfolk, Thermaglow is one of the UK''s largest manufacturers of electric heating elements for industrial, commercial, and domestic use. Products include tubular rod elements, immersion heaters, duct heaters, and heating blankets used in wind turbine blade manufacture, marine, and aerospace repair applications. They hold ISO 9001:2015 certification and the Made in Britain mark.', '{"company_type": "Industrial Heating Element Manufacturing", "website_url": "https://www.thermaglow.co.uk", "location": "Great Yarmouth, Norfolk, UK", "certifications": ["ISO 9001:2015", "Made in Britain"], "capabilities": ["Tubular Rod Heating Element Manufacturing", "Immersion Heater Manufacturing", "Industrial Duct Heater Manufacturing", "Heating Blanket Manufacturing", "Custom Element Design"], "industries": ["Wind Energy", "Marine", "Aerospace", "Industrial", "Commercial", "Domestic"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1957, "materials": ["Stainless Steel", "Copper", "Nichrome", "Incoloy"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Haydale Graphene Industries plc', 'Headquartered in Ammanford, Wales, Haydale is an advanced materials company that has developed patented plasma-functionalised graphene nanoparticles for use in heat-transfer fluids, thermal management composites, and aerospace components. They have received UK IPO patent approval for a graphene-enhanced heat-transfer fluid delivering substantially higher thermal efficiency than conventional coolants, targeting data centre liquid cooling and industrial thermal management markets.', '{"company_type": "Thermal Interface and Heat Transfer Materials", "website_url": "https://haydale.com", "location": "Ammanford, Carmarthenshire, Wales, UK", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Graphene Nanoparticle Functionalisation", "Thermal Management Fluid Development", "Composite Material Development", "Direct-to-Chip Cooling Fluid Supply", "Thermal Conductivity Enhancement"], "industries": ["Data Centres", "Aerospace", "Electronics", "Industrial Thermal Management"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2010, "materials": ["Graphene", "Polymer Composites", "Heat Transfer Fluids"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Watlow Limited', 'Watlow Limited is the UK operation of Watlow Electric Manufacturing Company (founded 1922, USA), based in Nottingham. Watlow designs and manufactures complete thermal systems including industrial electric heaters, sensors, and controllers for semiconductor, food processing, medical, and industrial markets. As the largest industrial heater manufacturer in their segment, they provide single-source thermal loop accountability from heater through controller to sensor.', '{"company_type": "Industrial Heating and Thermal Systems", "website_url": "https://www.watlow.com", "location": "Nottingham, Nottinghamshire, UK", "certifications": ["ISO 9001", "ISO 14001", "ATEX"], "capabilities": ["Cartridge and Immersion Heater Manufacturing", "Ceramic and Advanced Heater Design", "Temperature Controller Manufacturing", "RTD and Thermocouple Sensor Manufacturing", "Thermal System Integration"], "industries": ["Semiconductor", "Food Processing", "Medical", "Chemical", "Industrial"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1922, "materials": ["Stainless Steel", "Incoloy", "Ceramic", "Nickel Alloys"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Heat Exchange Group Ltd', 'Operating from manufacturing centres in the North of England, Heat Exchange Group brings together the heritage brands of Green''s Power, Thornhill, and the acquired intellectual property and designs of Hunt Thermal Technologies (since 1964). The group manufactures high-integrity shell-and-tube, air-cooled, and finned-tube heat exchangers and industrial boilers for power generation, oil and gas, marine, and industrial sectors. They have 200-tonne handling capacity and advanced CNC fabrication.', '{"company_type": "Heat Exchanger Manufacturing", "website_url": "https://heatexchangegroup.co.uk", "location": "Wakefield, West Yorkshire, UK", "certifications": ["ISO 9001", "PED", "TEMA"], "capabilities": ["Shell and Tube Heat Exchanger Manufacturing", "Air-Cooled Heat Exchanger Manufacturing", "Industrial Boiler Manufacturing", "Finned-Tube Fabrication", "High-Integrity Welding", "CNC Tube Bending"], "industries": ["Power Generation", "Oil and Gas", "Marine", "Industrial", "Petrochemical"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1964, "materials": ["Carbon Steel", "Stainless Steel", "Alloy Steel", "Duplex Steel"], "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
