INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ETher NDE Ltd', 'Based in St Albans, Hertfordshire, ETher NDE is a dedicated British manufacturer of eddy current (ECT) non-destructive testing equipment, probes, and accessories. Founded in 2009, the company has delivered thousands of instruments across 80 countries and has participated in EU Horizon 2020 research programmes for pipeline health monitoring. They serve aerospace, automotive, nuclear, and energy industries with a range of portable and automated eddy current instruments.', '{"company_type": "NDT Equipment", "website_url": "https://ethernde.com", "location": "St Albans, Hertfordshire, UK", "certifications": ["ISO 9001", "Made in Britain"], "capabilities": ["Eddy Current Testing", "Pulsed Eddy Current", "Conductivity Measurement", "Probe Manufacturing", "Surface Flaw Detection"], "industries": ["Aerospace", "Automotive", "Nuclear", "Energy", "Rail"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2009, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Baugh & Weedon NDE Ltd', 'Established in 1967 and based in Hereford, Baugh & Weedon is the leading British manufacturer of Magnetic Particle Inspection (MPI) benches, Liquid Penetrant Inspection (LPI) lines, UV inspection lamps, and dual UV/white light meters. Their MAGAZON range of MPI benches is designed and built in the UK and exported worldwide through an established global distributor network. They serve aerospace, defence, automotive, and oil and gas sectors.', '{"company_type": "NDT Equipment", "website_url": "https://www.bw-nde.com", "location": "Hereford, Herefordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Magnetic Particle Inspection", "Liquid Penetrant Testing", "UV Lamp Manufacturing", "Light Measurement", "Ultrasonic Thickness Gauging"], "industries": ["Aerospace", "Automotive", "Defence", "Oil & Gas", "Power Generation"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1967, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'RSL NDT Ltd', 'Based in Aberdeen and operating for over five decades, RSL NDT supplies industry-leading NDT equipment, provides UKAS-accredited calibration services (UKAS No. 9882 to ISO 17025), and offers fast, flexible equipment rental for shutdowns and project demands. Their rental and calibration fleet covers UT flaw detectors, phased array sets, eddy current units, hardness testers, UV lamps, and subsea systems. They primarily serve oil & gas, petrochemical, and offshore inspection sectors.', '{"company_type": "NDT Equipment", "website_url": "https://rslndt.com", "location": "Aberdeen, Scotland, UK", "certifications": ["ISO 17025", "UKAS Accredited (No. 9882)"], "capabilities": ["Ultrasonic Testing Equipment Supply", "Phased Array UT", "Eddy Current Testing", "UKAS Calibration", "Equipment Rental", "Subsea NDT Systems"], "industries": ["Oil & Gas", "Petrochemical", "Offshore", "Aerospace", "Power Generation"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Aberlink Ltd', 'Founded in 1993 and based in Eastcombe, Gloucestershire, Aberlink is the largest UK-owned manufacturer of coordinate measuring machines (CMMs), vision systems, and 3D measurement software. All products are wholly British-designed and manufactured at their Gloucestershire facility. Aberlink machines are known for being highly reliable, cost-effective, and easy to use, and are supplied to aerospace, automotive, and general engineering industries internationally.', '{"company_type": "Metrology", "website_url": "https://www.aberlink.com", "location": "Eastcombe, Gloucestershire, UK", "certifications": ["ISO 9001"], "capabilities": ["CMM Manufacturing", "Vision Measurement Systems", "3D Metrology Software", "CNC Measurement", "Dimensional Inspection"], "industries": ["Aerospace", "Automotive", "Medical Devices", "General Engineering", "Defence"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1993, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Eley Metrology Ltd', 'Based in Derby and operating for over 40 years, Eley Metrology is the leading UK independent manufacturer of granite-based coordinate measuring machines (CMMs) and operates a UKAS-accredited calibration laboratory on site. They were the first CMM company in the world to attain ISO 10360, and their machines are hand-lapped from granite without requiring software error mapping. Customers include major names from the aerospace, automotive, and precision engineering industries.', '{"company_type": "Metrology", "website_url": "https://eleymet.com", "location": "Derby, Derbyshire, UK", "certifications": ["ISO 17025", "UKAS Accredited", "ISO 10360"], "capabilities": ["CMM Manufacturing", "Granite CMM Construction", "UKAS Calibration", "Dimensional Metrology", "CMM Verification"], "industries": ["Aerospace", "Automotive", "Precision Engineering", "Medical Devices"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nikon Metrology UK Ltd', 'Based in Tring, Hertfordshire, Nikon Metrology UK is the British arm of Nikon''s metrology division and manufactures world-leading microfocus X-ray and computed tomography (CT) inspection systems, laser radar large-volume measurement systems, CMMs, and optical CNC measuring equipment. Their Laser Radar system performs fully automated, non-contact measurement up to 60 metres and is used in aerospace and automotive assembly inspection. They serve aerospace, automotive, electronics, and energy sectors.', '{"company_type": "Metrology", "website_url": "https://www.nikonmetrology.com/en-gb", "location": "Tring, Hertfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Microfocus X-ray CT", "Laser Radar Measurement", "CMM Systems", "3D Laser Scanning", "Optical CNC Measurement", "Industrial CT"], "industries": ["Aerospace", "Automotive", "Electronics", "Energy", "Defence"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Solartron Metrology Ltd', 'Headquartered in Bognor Regis, West Sussex, Solartron Metrology was established in 1946 and is a world leader in the design and manufacture of precision dimensional sensors, LVDT gauging probes, displacement transducers, optical linear encoders, and associated instrumentation. Part of the AMETEK Ultra Precision Technologies division, they export over 97% of production globally. Their sensors are used in electric vehicles, aerospace, defence, semiconductor, and bearing manufacturing quality control processes.', '{"company_type": "Metrology", "website_url": "https://www.solartronmetrology.com", "location": "Bognor Regis, West Sussex, UK", "certifications": ["ISO 9001"], "capabilities": ["LVDT Displacement Sensors", "Gauging Probes", "Linear Encoders", "Non-Contact Measurement", "In-Process Gauging"], "industries": ["Aerospace", "Automotive", "Semiconductor", "Defence", "Bearings Manufacturing", "Electronics"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1946, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Temperature Applied Sciences Ltd (TAS)', 'Established in 1969 and based in Goring-by-Sea, West Sussex, TAS is the UK''s premier manufacturer of environmental test chambers and simulation equipment with over 50 years of industry experience. Their product range covers temperature chambers, climatic temperature and humidity chambers, thermal vacuum chambers, altitude chambers, and large-scale walk-in test rooms. Chambers operate from -120°C to +350°C and they serve aerospace, automotive, pharmaceutical, and electronics industries.', '{"company_type": "Environmental Testing", "website_url": "https://www.tasltd.co.uk", "location": "Goring-by-Sea, West Sussex, UK", "certifications": ["ISO 9001", "Made in Britain"], "capabilities": ["Thermal Cycling Chambers", "Climatic Chambers", "Thermal Vacuum Testing", "Altitude Chambers", "Humidity Testing", "Walk-in Test Rooms"], "industries": ["Aerospace", "Automotive", "Pharmaceutical", "Electronics", "Defence", "Construction"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1969, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'CVMS Climatic Ltd', 'Located in Leighton Buzzard, Bedfordshire, CVMS Climatic is a specialist UK manufacturer of environmental test chambers, from compact benchtop climatic chambers through to large-scale walk-in and drive-in test facilities. Their product range includes thermal shock chambers, temperature and humidity chambers, and bespoke climatic test systems. They serve aerospace, automotive, electronics, defence, and battery testing sectors, and provide chamber calibration and service support.', '{"company_type": "Environmental Testing", "website_url": "https://cvmsclimatic.com", "location": "Leighton Buzzard, Bedfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Thermal Shock Testing", "Climatic Test Chambers", "Walk-in Environmental Rooms", "Humidity Testing", "Temperature Cycling"], "industries": ["Aerospace", "Automotive", "Electronics", "Defence", "Battery Testing"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sharetree Ltd', 'Originally formed in 1972 and based in Stonehouse, Gloucestershire, Sharetree is a family-owned UK manufacturer of thermal and environmental test chambers. All chambers are designed and manufactured at their Gloucestershire facility, and their product range includes hygrothermal chambers, multi-functional chambers, 2-axis tilt chambers, and product tilt-and-rotate chambers. They supply standard and custom solutions to aerospace, electronics, defence, and automotive development and production testing.', '{"company_type": "Environmental Testing", "website_url": "https://sharetree.co.uk", "location": "Stonehouse, Gloucestershire, UK", "certifications": ["ISO 9001"], "capabilities": ["Thermal Cycling Chambers", "Hygrothermal Testing", "Environmental Stress Screening", "Custom Chamber Design", "2-Axis Tilt Chambers"], "industries": ["Aerospace", "Electronics", "Defence", "Automotive", "Telecommunications"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1972, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'TS Space Systems Ltd', 'Based in Marlow, Buckinghamshire, TS Space Systems has over 30 years of experience (established 1984) designing, building, and operating thermal vacuum chambers for space simulation and materials testing. They operate three in-house TVAC chambers and provide standard ESA/NASA thermal vacuum cycling, outgassing testing to ECSS-Q-ST-70-02, and vacuum UV exposure services. They are world leaders in solar simulators for photovoltaic testing and serve the space, defence, and aerospace sectors.', '{"company_type": "Environmental Testing", "website_url": "https://www.ts-space.co.uk", "location": "Marlow, Buckinghamshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Thermal Vacuum Testing", "TVAC Chamber Manufacturing", "Outgassing Testing", "Solar Simulation", "Vacuum UV Exposure", "Space Hardware Qualification"], "industries": ["Space", "Aerospace", "Defence", "Telecommunications"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1984, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Testometric Co. Ltd', 'Founded in 1970 and located in Rochdale, Lancashire, Testometric has over 50 years of experience in the design and manufacture of universal strength testing machines for tensile strength, compression, flexure, shear, and product testing. Their machines offer force capacities from 1 kN to 1,000 kN and serve the plastics, rubber, composites, textiles, and packaging industries. They supply quality control and materials research organisations worldwide.', '{"company_type": "Materials Testing", "website_url": "https://www.testometric.co.uk", "location": "Rochdale, Lancashire, UK", "certifications": ["ISO 9001"], "capabilities": ["Tensile Testing", "Compression Testing", "Flexure Testing", "Shear Testing", "Product Testing", "Universal Testing Machines"], "industries": ["Plastics", "Rubber", "Composites", "Textiles", "Packaging", "Medical Devices"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1970, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Tinius Olsen Ltd', 'The UK subsidiary of Tinius Olsen is based in Redhill, Surrey, and is part of a company founded in 1880 that is the leading specialist manufacturer of static tension and compression materials testing machines. Their UK operation supports European design, manufacturing, sales, and service of machines testing metals, alloys, composites, plastics, rubber, textiles, and wood. They serve research institutions, quality control laboratories, and manufacturers across aerospace, automotive, and pharmaceutical sectors.', '{"company_type": "Materials Testing", "website_url": "https://www.tiniusolsen.com", "location": "Redhill, Surrey, UK", "certifications": ["ISO 9001"], "capabilities": ["Tensile Testing Machines", "Compression Testing", "Impact Testing", "Hardness Testing", "Fatigue Testing", "Universal Testing Machines"], "industries": ["Aerospace", "Automotive", "Pharmaceutical", "Construction", "Plastics", "Metals"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1880, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Instron Ltd', 'Instron Ltd is based in High Wycombe, Buckinghamshire, established as the European manufacturing and support hub in 1960. Part of the Illinois Tool Works group, Instron manufactures tensile, compression, fatigue, impact, rheology, and structural testing machines. The UK facility received a Queen''s Award for Export Achievement in 1968 and serves the full range of materials testing applications from small medical device components to large structural aerospace assemblies.', '{"company_type": "Materials Testing", "website_url": "https://www.instron.com/en", "location": "High Wycombe, Buckinghamshire, UK", "certifications": ["ISO 9001", "NADCAP"], "capabilities": ["Tensile Testing", "Fatigue Testing", "Impact Testing", "Compression Testing", "Structural Testing", "Rheology"], "industries": ["Aerospace", "Automotive", "Medical Devices", "Pharmaceutical", "Materials Research", "Composites"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1960, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Foundrax Engineering Products Ltd', 'Based in Somerton, Somerset, Foundrax was founded in 1948 and is the world''s only company specialising entirely in Brinell hardness testing equipment and accessories. Their range covers portable Brinell testers, production machines, radial arm testers, bridge-type testers, UKAS-certified reference blocks, and National Standard-level calibration machines. Foundrax equipment is exported to 45 countries, and the company has been influential in developing ISO and BSI hardness testing standards.', '{"company_type": "Materials Testing", "website_url": "https://foundrax.co.uk", "location": "Somerton, Somerset, UK", "certifications": ["ISO 9001", "UKAS"], "capabilities": ["Brinell Hardness Testing", "Portable Hardness Testing", "Reference Block Manufacture", "National Standard Calibration Machines", "Hardness Tester Verification"], "industries": ["Steel & Metals", "Aerospace", "Automotive", "Foundry", "Nuclear", "Defence"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1948, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HBK (Hottinger Brüel & Kjær) — LDS Shakers, Royston', 'The Royston, Hertfordshire facility is HBK''s global manufacturing centre for LDS electrodynamic vibration shaker systems, the largest vibration shaker factory in the world. Originally Ling Dynamic Systems (LDS), acquired by Brüel & Kjær in 2009 and subsequently merged into HBK in 2020. The Royston site produces approximately 900 shakers per year across a force range covering small electronics through to spacecraft and aircraft structures, and is used by NASA, ESA, and major defence primes.', '{"company_type": "Vibration Testing", "website_url": "https://www.hbkworld.com/en/products/integrated-systems/vibration-testing", "location": "Royston, Hertfordshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Electrodynamic Shaker Manufacturing", "High-Force Vibration Testing", "Vibration Controllers", "Power Amplifiers", "Slip Tables", "Shaker Maintenance & Repair"], "industries": ["Aerospace", "Space", "Defence", "Automotive", "Electronics", "Rail"], "lead_time": null, "min_order": null, "employees": "250+", "established": null, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Data Physics (UK) Ltd', 'Located in Hailsham, East Sussex, Data Physics (UK) Ltd — formerly Gearing & Watson Electronics — is the UK manufacturing and support facility for SignalForce electrodynamic vibration shakers, power amplifiers, slip tables, head expanders, and vibration controllers. The facility designs and builds shaker systems and provides maintenance, calibration, and repair services for all shaker brands. They serve aerospace, defence, automotive, and electronics sectors requiring vibration qualification testing.', '{"company_type": "Vibration Testing", "website_url": "https://dataphysics.com", "location": "Hailsham, East Sussex, UK", "certifications": ["ISO 9001"], "capabilities": ["Electrodynamic Shaker Systems", "Vibration Controllers", "Power Amplifiers", "Slip Tables", "Shaker Service & Calibration", "Vibration Analysis"], "industries": ["Aerospace", "Defence", "Automotive", "Electronics", "Space"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'CentraTEQ Ltd', 'Founded in 2008 and based in Solihull, Warwickshire, CentraTEQ is the leading UK distributor and integrator of vibration test equipment and product testing solutions. They are the exclusive UK distributor for ETS Solutions shakers (20 N to 500 kN range), agents for Benchmark/AVEX shock test systems, and supply HALT/HASS test systems. CentraTEQ serves UK manufacturers across aerospace, automotive, electronics, and defence requiring product qualification and environmental stress screening.', '{"company_type": "Vibration Testing", "website_url": "https://centrateq.com", "location": "Solihull, Warwickshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Electrodynamic Shakers", "HALT/HASS Testing Systems", "Shock Testing", "Vibration Control Systems", "Package Testing", "Product Environmental Testing"], "industries": ["Aerospace", "Automotive", "Electronics", "Defence", "Telecommunications"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2008, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Furness Controls Ltd', 'Founded in 1966 and headquartered in Bexhill-on-Sea, East Sussex, Furness Controls is a world expert in leak testing, pressure and flow measurement instrumentation. Their UKAS-accredited calibration laboratory (UKAS No. 0580) provides traceable calibration services from their Bexhill facility and UK Service Centre at Tamworth. They manufacture ultra-low range differential pressure sensors, automatic leak testers for production lines, and flow measurement instruments, serving automotive, medical, and general manufacturing sectors.', '{"company_type": "Leak Detection", "website_url": "https://www.furness-controls.com", "location": "Bexhill-on-Sea, East Sussex, UK", "certifications": ["ISO 9001", "ISO 17025", "UKAS Accredited (No. 0580)"], "capabilities": ["Differential Pressure Measurement", "Automatic Leak Testing", "Flow Measurement", "Production Line Leak Testing", "UKAS Calibration", "Pressure Transmitters"], "industries": ["Automotive", "Medical Devices", "HVAC", "Pharmaceutical", "Aerospace", "General Manufacturing"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1966, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'TQC Ltd', 'Based in Nottingham, TQC has over 35 years of experience as a specialist designer and manufacturer of bespoke leak testing equipment, assembly automation machines, and quality control systems. They provide air decay, helium, and water submersion leak test solutions for manufacturing production lines, with all mechanical, electrical, and software design conducted in-house. TQC serves automotive, aerospace, medical device, and general manufacturing clients worldwide.', '{"company_type": "Leak Detection", "website_url": "https://www.tqc.co.uk", "location": "Nottingham, Nottinghamshire, UK", "certifications": ["ISO 9001:2015"], "capabilities": ["Air Decay Leak Testing", "Helium Leak Testing", "Vacuum Leak Testing", "Assembly Automation", "Bespoke Leak Test Rig Design", "Force & Vision Testing"], "industries": ["Automotive", "Aerospace", "Medical Devices", "HVAC", "General Manufacturing"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sercal NDT Equipment Ltd', 'Located in Cannock, Staffordshire, Sercal has been operating independently since 1987 and is a key company within the Oceanscan Group. Sercal holds the distinction of being the first UK-based UKAS-accredited calibration laboratory (UKAS No. 0381) for ultrasonic flaw detectors, eddy current equipment, thickness meters, and transducers. They supply, service, calibrate, and hire NDT equipment including subsea inspection systems rated to 250 m depth, serving oil & gas, nuclear, and offshore sectors.', '{"company_type": "NDT Equipment", "website_url": "https://www.sercal.co.uk", "location": "Cannock, Staffordshire, UK", "certifications": ["ISO 17025", "UKAS Accredited (No. 0381)"], "capabilities": ["UKAS Calibration", "Ultrasonic Equipment Supply", "Eddy Current Testing", "Subsea NDT Systems", "Equipment Rental", "Thickness Measurement"], "industries": ["Oil & Gas", "Nuclear", "Offshore", "Petrochemical", "Aerospace"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1987, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Metrix NDT Ltd', 'Based in Loughborough, Leicestershire, Metrix NDT is a UK designer, manufacturer, and supplier of X-ray inspection systems, digital radiography, and computed tomography (CT) solutions, with over 40 years of combined team experience in industrial X-ray inspection. In 2024, Metrix NDT became part of the Fairley Gunn Group. They provide customised X-ray cabinet systems and industrial CT solutions for weld inspection, casting evaluation, electronics inspection, and composite analysis.', '{"company_type": "NDT Equipment", "website_url": "https://metrixndt.com", "location": "Loughborough, Leicestershire, UK", "certifications": ["ISO 9001"], "capabilities": ["Digital X-ray Inspection Systems", "Industrial CT", "Computed Radiography", "Weld Inspection", "Casting Evaluation", "Electronics Inspection"], "industries": ["Aerospace", "Automotive", "Electronics", "Defence", "Manufacturing"], "lead_time": null, "min_order": null, "employees": "10-49", "established": null, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Phoenix Inspection Systems Ltd (Phoenix ISL)', 'Established in 1983 and based in Warrington, Cheshire, Phoenix ISL is a leading worldwide manufacturer of ultrasonic NDT transducers, scanners, and automated inspection systems, with over 30 years of specific experience designing systems for the nuclear sector. Acquired by Nova Instruments in 2014, they serve nuclear, offshore oil & gas, aerospace, composites, and rail industries in over 33 countries. Their product range covers TOFD, phased array, pulse-echo, and corrosion mapping solutions.', '{"company_type": "NDT Equipment", "website_url": "https://www.phoenixisl.com", "location": "Warrington, Cheshire, UK", "certifications": ["ISO 9001", "NADCAP"], "capabilities": ["Ultrasonic Transducers", "Phased Array Systems", "TOFD Testing", "Automated Scanning Systems", "Corrosion Mapping", "Nuclear Inspection Systems"], "industries": ["Nuclear", "Oil & Gas", "Aerospace", "Composites", "Rail", "Power Generation"], "lead_time": null, "min_order": null, "employees": "50-249", "established": 1983, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Dolphitech Ltd', 'Dolphitech Ltd is the UK subsidiary of Norwegian NDT technology innovator Dolphitech AS, based in Milton, Cambridgeshire, acting as a global training and support hub. They manufacture the dolphicam2, a matrix array ultrasonic system that provides high-definition full-aperture imaging of composite structures and bonded assemblies without requiring water coupling or scanning. Approved by Boeing and Airbus, it is widely used for composite inspection in aerospace, defence, marine, and automotive sectors.', '{"company_type": "NDT Equipment", "website_url": "https://dolphitech.com/uk", "location": "Milton, Cambridgeshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Matrix Array Ultrasonic Testing", "Composite Inspection", "Bonded Structure Inspection", "Portable NDT Systems", "Full-Aperture Ultrasonic Imaging"], "industries": ["Aerospace", "Defence", "Automotive", "Marine", "Space", "Energy"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 2021, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Precision Acoustics Ltd', 'Established in 1997 and based in Dorchester, Dorset, Precision Acoustics is a leading global manufacturer of hydrophones, ultrasound transducers, PVdF-based acoustic sensors, and ultrasound measurement instruments operating in the 40 kHz to 50 MHz frequency range. They serve medical ultrasound R&D, industrial NDT, and academic research markets, and maintain a close collaboration with the National Physical Laboratory. In November 2024, the company was acquired by Coda Octopus Group.', '{"company_type": "NDT Equipment", "website_url": "https://www.acoustics.co.uk", "location": "Dorchester, Dorset, UK", "certifications": ["ISO 9001"], "capabilities": ["Hydrophone Manufacturing", "Ultrasonic Transducers", "Acoustic Pressure Measurement", "PVdF Sensor Technology", "Ultrasound Intensity Measurement"], "industries": ["Medical Devices", "NDT", "Academic Research", "Defence", "Pharmaceutical"], "lead_time": null, "min_order": null, "employees": "10-49", "established": 1997, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Elcometer Ltd', 'Founded in 1947 and headquartered in Manchester (Droylsden, M43), Elcometer is a world leader in the design, manufacture, and supply of coating inspection equipment, ultrasonic NDT gauges, abrasive blast equipment, and concrete inspection tools. The company launched one of the world''s first non-destructive coating thickness gauges in 1947 and now operates through offices in seven countries with over 150 distributors in 70+ countries. They serve protective coatings, marine, oil & gas, civil engineering, and aerospace sectors.', '{"company_type": "NDT Equipment", "website_url": "https://www.elcometer.com", "location": "Manchester, Greater Manchester, UK", "certifications": ["ISO 9001"], "capabilities": ["Coating Thickness Measurement", "Adhesion Testing", "Surface Roughness Measurement", "Ultrasonic NDT", "Holiday Detection", "Gloss Measurement"], "industries": ["Protective Coatings", "Marine", "Oil & Gas", "Civil Engineering", "Aerospace", "Automotive"], "lead_time": null, "min_order": null, "employees": "250+", "established": 1947, "materials": null, "key_equipment": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

